INSERT INTO dbo.CourseCatalog (TermID, CourseTitle, CourseDescription, Department, College, CourseLevel, Credits, Prerequisites)
VALUES
  ('Winter28', N'EXS 234: Kinesiology and Biomechanics', N'An analysis of human movement using principles of physics and anatomy. Topics include joint mechanics, muscle function, gait analysis, ergonomics, and injury mechanisms. Students conduct biomechanical analyses using video and motion capture technology.', N'Exercise Science', N'Health Sciences', 200, 3, N'BIO 101 and PHY 101'),
  ('Winter28', N'PSY 182: Introduction to Psychology', N'A survey of the major areas of psychological science including cognition, development, social behavior, personality, psychopathology, and neuroscience. Students learn to evaluate psychological claims using scientific evidence and critical thinking skills.', N'Psychology', N'Arts & Sciences', 100, 3, NULL),
  ('Fall26', N'CPE 414: Senior Design in Computer Engineering', N'A capstone project integrating hardware and software design. Student teams develop a complete embedded computing system from specification through implementation and testing.', N'Computer Engineering', N'Engineering', 400, 3, N'Senior standing in CPE'),
  ('Fall26', N'PHL 139: Ethics', N'An introduction to moral philosophy examining major ethical theories including utilitarianism, deontology, virtue ethics, and care ethics. Students apply these frameworks to contemporary moral issues including bioethics, environmental ethics, and social justice.', N'Philosophy', N'Arts & Sciences', 100, 3, NULL),
  ('Fall27', N'BAN 303: Predictive Analytics', N'An applied course in building predictive models for business applications. Topics include linear and logistic regression, decision trees, random forests, and neural network basics. Students develop end-to-end predictive analytics workflows from data preparation through model deployment.', N'Business Analytics', N'Business', 300, 3, N'BAN 202 and BAN 201'),
  ('Spring27', N'THR 336: Playwriting', N'A workshop course in dramatic writing. Students study dramatic structure, create original short and full-length plays, participate in peer critique, and hear their work read by student actors. Explores diverse storytelling traditions and voices.', N'Theatre', N'Fine Arts', 300, 3, N'THR 101 or ENG 211'),
  ('Spring27', N'CHM 256: Analytical Chemistry', N'A study of quantitative and qualitative analytical methods including gravimetry, titrimetry, spectrophotometry, chromatography, and electroanalytical techniques. Emphasizes method validation, error analysis, and quality assurance in chemical measurements.', N'Chemistry', N'Arts & Sciences', 200, 3, N'CHM 102'),
  ('Fall26', N'NUR 379: Medical-Surgical Nursing', N'Clinical nursing practice focused on adults with acute and chronic health conditions. Students develop skills in assessment, care planning, medication administration, and patient education across hospital and outpatient settings.', N'Nursing', N'Health Sciences', 300, 3, N'NUR 201, NUR 202, NUR 203'),
  ('Fall26', N'PHY 246: University Physics II', N'A calculus-based treatment of electromagnetism including electric fields, Gauss''s law, capacitance, DC circuits, magnetic fields, Faraday''s law, and electromagnetic waves. Laboratory emphasizes precision measurement and circuit analysis.', N'Physics', N'Arts & Sciences', 200, 4, N'PHY 211 and MTH 242'),
  ('Winter28', N'CIV 404: Construction Project Management', N'An advanced course in managing construction projects. Topics include estimating, scheduling (CPM), contract administration, safety management, quality control, and building information modeling (BIM).', N'Civil Engineering', N'Engineering', 400, 3, N'CIV 301'),
  ('Spring28', N'WLG 417: Senior Seminar in World Languages', N'A capstone seminar in which students conduct independent research on a topic related to language, linguistics, or culture. Students present their findings in both the target language and English, demonstrating advanced analytical and communication skills.', N'World Languages', N'Arts & Sciences', 400, 4, N'Senior standing in WLG'),
  ('Spring28', N'WLG 226: Intermediate Spanish', N'A continuation of language study that deepens communicative competence through reading, writing, speaking, and listening activities. Students engage with authentic texts and media from the Spanish-speaking world while expanding grammatical accuracy and cultural understanding.', N'World Languages', N'Arts & Sciences', 200, 3, N'WLG 102 or placement'),
  ('Winter27', N'MGT 113: Introduction to Entrepreneurship', N'An exploration of the entrepreneurial mindset and new venture creation. Students learn to identify opportunities, develop business models, conduct market analysis, and pitch ideas. Includes case studies of successful startups and social enterprises.', N'Management', N'Business', 100, 3, NULL),
  ('Winter27', N'MEC 477: Senior Design Project', N'A two-semester capstone experience in which student teams design, build, and test a mechanical system or device. Teams work with industry sponsors, manage budgets and schedules, and present their work at the engineering design showcase.', N'Mechanical Engineering', N'Engineering', 400, 4, N'Senior standing in MEC'),
  ('Winter28', N'SOC 504: Graduate Seminar in Social Stratification', N'An advanced seminar examining theories and research on social inequality. Topics include class structure, income and wealth distribution, intergenerational mobility, intersectionality, and comparative stratification systems.', N'Sociology', N'Arts & Sciences', 500, 3, N'Graduate standing'),
  ('Spring27', N'CSC 514: Advanced Topics in Machine Learning', N'Graduate-level study of cutting-edge machine learning research including deep reinforcement learning, graph neural networks, federated learning, and large language models. Students read and present current research papers and complete an original research project demonstrating novel application of ML techniques.', N'Computer Science', N'Arts & Sciences', 500, 3, N'CSC 341 and graduate standing'),
  ('Spring27', N'CIV 277: Environmental Engineering', N'An introduction to environmental engineering principles including water and wastewater treatment, air quality, solid waste management, and environmental impact assessment. Students analyze engineering solutions for environmental protection.', N'Civil Engineering', N'Engineering', 200, 4, N'CHM 101 and MTH 242'),
  ('Winter27', N'EXS 339: Strength and Conditioning', N'A practical course in designing exercise programs for athletic performance and general fitness. Students learn resistance training techniques, periodization, speed and agility development, and program design for diverse populations.', N'Exercise Science', N'Health Sciences', 300, 3, N'EXS 211'),
  ('Winter28', N'MEC 567: Graduate Seminar in Advanced Manufacturing', N'An advanced seminar covering emerging manufacturing technologies including additive manufacturing, smart factories, digital twins, and sustainable manufacturing practices. Students analyze case studies and conduct research projects.', N'Mechanical Engineering', N'Engineering', 500, 3, N'Graduate standing'),
  ('Summer28', N'MGT 388: Strategic Management', N'An integrative course examining how organizations develop and implement strategy. Topics include industry analysis, competitive advantage, resource-based view, diversification, strategic alliances, and corporate governance. Students complete a comprehensive strategic analysis.', N'Management', N'Business', 300, 3, N'MGT 201 and MKT 201 and FIN 201'),
  ('Spring28', N'BIO 523: Graduate Topics in Molecular Biology', N'Advanced seminar focusing on current frontiers in molecular biology research. Topics may include single-cell genomics, synthetic biology, RNA therapeutics, and structural biology. Students lead journal club discussions and develop original research proposals.', N'Biology', N'Arts & Sciences', 500, 3, N'Graduate standing'),
  ('Fall26', N'MUS 368: Music Technology and Production', N'An introduction to music technology including digital audio workstations, MIDI sequencing, audio recording and mixing, synthesis, and sound design. Students produce original recordings and learn the technical skills used in modern music production.', N'Music', N'Fine Arts', 300, 3, N'MUS 101'),
  ('Summer28', N'MEC 302: Machine Design', N'An applied course in designing mechanical components and systems. Topics include stress analysis, fatigue, bearings, gears, shafts, springs, and bolted connections. Students use CAD software and finite element analysis to design and optimize components.', N'Mechanical Engineering', N'Engineering', 300, 3, N'MEC 201 and MEC 203'),
  ('Winter28', N'MUS 352: World Music', N'A comparative study of musical traditions from Africa, Asia, Latin America, and indigenous cultures. Students explore the social functions of music, instruments and performance practices, and the impact of globalization on world music traditions.', N'Music', N'Fine Arts', 300, 4, N'MUS 102 or MUS 201'),
  ('Summer27', N'ENV 149: Introduction to Environmental Science', N'A multidisciplinary survey of environmental issues including climate change, biodiversity loss, pollution, resource depletion, and sustainable development. Integrates concepts from biology, chemistry, geology, and policy to understand human impacts on natural systems.', N'Environmental Science', N'Arts & Sciences', 100, 3, NULL),
  ('Fall26', N'ENG 349: Technical and Professional Writing', N'A practical course in writing for professional contexts including reports, proposals, instructions, and digital content. Students learn document design principles, audience analysis, usability testing, and collaborative writing strategies used in workplace environments.', N'English', N'Arts & Sciences', 300, 3, N'ENG 102'),
  ('Spring27', N'NUR 329: Community and Public Health Nursing', N'An exploration of nursing practice in community settings. Topics include health promotion, disease prevention, epidemiology, environmental health, vulnerable populations, and the nurse''s role in public health emergency preparedness.', N'Nursing', N'Health Sciences', 300, 3, N'NUR 301'),
  ('Fall27', N'MEC 371: Heat Transfer', N'A study of heat transfer by conduction, convection, and radiation. Topics include steady and transient conduction, forced and natural convection, heat exchangers, and thermal radiation. Applications include HVAC, electronics cooling, and energy systems.', N'Mechanical Engineering', N'Engineering', 300, 3, N'MEC 202 and MEC 311'),
  ('Spring28', N'CHM 444: Instrumental Analysis', N'Advanced analytical methods including atomic spectroscopy, mass spectrometry, advanced chromatography, and surface analysis techniques. Students operate modern instrumentation and develop methods for complex sample analysis.', N'Chemistry', N'Arts & Sciences', 400, 4, N'CHM 203'),
  ('Fall27', N'MTH 412: Real Analysis', N'An advanced course in the rigorous foundations of calculus. Topics include the completeness of the real numbers, sequences and series of functions, metric spaces, continuity, differentiability, and Riemann integration. Emphasizes epsilon-delta proofs and mathematical rigor.', N'Mathematics', N'Arts & Sciences', 400, 3, N'MTH 341'),
  ('Fall26', N'ARH 283: Modern Art: 1860-1960', N'A study of the development of modern art from Impressionism through Abstract Expressionism. Students examine how artists responded to industrialization, urbanization, world wars, and new philosophical ideas through innovative visual forms.', N'Art History', N'Fine Arts', 200, 3, N'ARH 102'),
  ('Summer28', N'PHY 325: Quantum Mechanics', N'A rigorous treatment of quantum theory including the Schrodinger equation, angular momentum, spin, perturbation theory, and the hydrogen atom. Students develop mathematical and conceptual tools for understanding quantum phenomena in atoms, molecules, and solids.', N'Physics', N'Arts & Sciences', 300, 3, N'PHY 221 and MTH 302'),
  ('Spring27', N'MEC 339: Machine Design', N'An applied course in designing mechanical components and systems. Topics include stress analysis, fatigue, bearings, gears, shafts, springs, and bolted connections. Students use CAD software and finite element analysis to design and optimize components.', N'Mechanical Engineering', N'Engineering', 300, 4, N'MEC 201 and MEC 203'),
  ('Winter28', N'ARH 166: Art History Survey II', N'A survey of art and architecture from the Renaissance to the present. Students examine major movements including Renaissance, Baroque, Impressionism, Modernism, and Contemporary art in their cultural and historical contexts.', N'Art History', N'Fine Arts', 100, 3, NULL),
  ('Summer27', N'JOU 234: Photojournalism', N'A course in visual storytelling through photography. Students learn composition, lighting, and digital editing techniques while developing the ability to capture news events and human interest stories through compelling images.', N'Journalism', N'Communications', 200, 4, N'JOU 101'),
  ('Fall26', N'MTH 584: Graduate Seminar in Applied Mathematics', N'An advanced seminar exploring current research topics in applied mathematics. Students read recent publications, present findings, and develop original research questions. Topics rotate and may include mathematical biology, computational fluid dynamics, or network analysis.', N'Mathematics', N'Arts & Sciences', 500, 3, N'Graduate standing in MTH'),
  ('Fall26', N'CPE 304: Real-Time Systems', N'A study of computing systems with timing constraints. Topics include real-time scheduling, priority inversion, embedded real-time operating systems, timing analysis, and safety-critical system design.', N'Computer Engineering', N'Engineering', 300, 3, N'CPE 211 and ELE 301'),
  ('Spring28', N'BIO 119: General Biology II', N'Continuation of General Biology I focusing on organismal biology, ecology, and evolution. Topics include biodiversity, population genetics, ecosystem dynamics, and phylogenetics. Laboratory work includes field ecology and comparative anatomy.', N'Biology', N'Arts & Sciences', 100, 3, N'BIO 101'),
  ('Summer27', N'PHL 283: Philosophy of Mind', N'An examination of fundamental questions about the nature of consciousness, mental representation, personal identity, and the relationship between mind and body. Students explore classic positions and engage with contemporary debates informed by neuroscience and artificial intelligence.', N'Philosophy', N'Arts & Sciences', 200, 3, N'PHL 101'),
  ('Fall27', N'ART 474: Senior Exhibition', N'A capstone course in which students develop and present a cohesive body of work in a professional exhibition. Students write an artist statement, install their work, and participate in a public critique and reception.', N'Studio Art', N'Fine Arts', 400, 4, N'Senior standing in ART'),
  ('Winter27', N'CTV 317: Film Theory and Criticism', N'An examination of major theoretical approaches to cinema including auteur theory, genre theory, feminist film theory, psychoanalytic criticism, and postcolonial perspectives. Students write critical essays analyzing films through theoretical frameworks.', N'Cinema & Television', N'Communications', 300, 3, N'CTV 101'),
  ('Summer27', N'MGT 102: Introduction to Entrepreneurship', N'An exploration of the entrepreneurial mindset and new venture creation. Students learn to identify opportunities, develop business models, conduct market analysis, and pitch ideas. Includes case studies of successful startups and social enterprises.', N'Management', N'Business', 100, 3, NULL),
  ('Spring27', N'MTH 414: Topology', N'An introduction to point-set topology covering topological spaces, continuous functions, connectedness, compactness, and separation axioms. Students develop abstract mathematical reasoning skills applicable to analysis, geometry, and theoretical computer science.', N'Mathematics', N'Arts & Sciences', 400, 3, N'MTH 441'),
  ('Summer27', N'HIS 163: United States History to 1877', N'An examination of American history from indigenous civilizations through Reconstruction. Topics include colonization, revolution, constitutional development, westward expansion, slavery, and the Civil War. Students analyze primary documents and historiographical debates.', N'History', N'Arts & Sciences', 100, 3, NULL),
  ('Spring28', N'WLG 218: Intermediate Spanish', N'A continuation of language study that deepens communicative competence through reading, writing, speaking, and listening activities. Students engage with authentic texts and media from the Spanish-speaking world while expanding grammatical accuracy and cultural understanding.', N'World Languages', N'Arts & Sciences', 200, 3, N'WLG 102 or placement'),
  ('Fall26', N'ELE 381: Electronics', N'A study of semiconductor devices and electronic circuit design. Topics include diodes, transistors (BJT and MOSFET), amplifier design, frequency response, feedback, and operational amplifier circuits.', N'Electrical Engineering', N'Engineering', 300, 3, N'ELE 201'),
  ('Fall26', N'CHM 178: General Chemistry I', N'Introduction to the fundamental principles of chemistry including atomic structure, chemical bonding, stoichiometry, thermochemistry, and gas laws. Laboratory work develops quantitative measurement skills, safety practices, and scientific reasoning.', N'Chemistry', N'Arts & Sciences', 100, 3, NULL),
  ('Spring28', N'POL 127: Introduction to International Relations', N'A survey of theories and issues in international relations including realism, liberalism, constructivism, security studies, international organizations, globalization, human rights, and environmental politics. Students analyze contemporary global challenges.', N'Political Science', N'Arts & Sciences', 100, 3, NULL),
  ('Winter27', N'CSC 175: Digital Literacy and Computing', N'A survey of modern computing concepts for non-majors. Covers how computers process and store information, basics of web development, spreadsheet analysis, and an introduction to computational thinking. Students complete hands-on projects that connect computing to everyday problem-solving.', N'Computer Science', N'Arts & Sciences', 100, 4, NULL),
  ('Winter28', N'BAN 388: Text Analytics and NLP for Business', N'An applied course in extracting insights from unstructured text data. Topics include text preprocessing, sentiment analysis, topic modeling, named entity recognition, and building text classification systems. Applications include customer review analysis, social media monitoring, and document categorization.', N'Business Analytics', N'Business', 300, 3, N'BAN 301 and programming experience');
INSERT INTO dbo.CourseCatalog (TermID, CourseTitle, CourseDescription, Department, College, CourseLevel, Credits, Prerequisites)
VALUES
  ('Winter27', N'PSY 309: Health Psychology', N'An exploration of psychological factors in health and illness. Topics include stress and disease, health behavior change models, pain management, patient-provider communication, and psychological aspects of chronic illness. Examines evidence-based interventions for health promotion.', N'Psychology', N'Arts & Sciences', 300, 3, N'PSY 201'),
  ('Fall26', N'MTH 498: Topology', N'An introduction to point-set topology covering topological spaces, continuous functions, connectedness, compactness, and separation axioms. Students develop abstract mathematical reasoning skills applicable to analysis, geometry, and theoretical computer science.', N'Mathematics', N'Arts & Sciences', 400, 3, N'MTH 441'),
  ('Fall27', N'SPE 309: Transition Planning and Life Skills', N'A course focused on preparing students with disabilities for post-secondary education, employment, and independent living. Topics include self-determination, vocational assessment, community-based instruction, and interagency collaboration.', N'Special Education', N'Education', 300, 4, N'SPE 201'),
  ('Fall26', N'BIO 314: Neuroscience', N'An interdisciplinary exploration of the nervous system from molecular to behavioral levels. Topics include neuronal signaling, synaptic transmission, sensory systems, motor control, learning and memory, and neurological disorders. Bridges biology and psychology perspectives.', N'Biology', N'Arts & Sciences', 300, 3, N'BIO 211 or PSY 201'),
  ('Spring28', N'ECN 331: Labor Economics', N'An analysis of labor markets including labor supply and demand, human capital theory, wage determination, discrimination, unions, unemployment, and labor market policy. Students use data to analyze trends in employment and earnings.', N'Economics', N'Business', 300, 3, N'ECN 201'),
  ('Fall27', N'PBH 299: Biostatistics', N'An introduction to statistical methods for public health research. Topics include descriptive statistics, probability, sampling distributions, hypothesis testing, regression, and survival analysis. Students use SAS or R to analyze health datasets.', N'Public Health', N'Health Sciences', 200, 3, N'MTH 110'),
  ('Winter27', N'ACC 254: Intermediate Accounting II', N'Continuation of Intermediate Accounting I covering accounting for liabilities, stockholders'' equity, investments, leases, pensions, income taxes, and cash flow statements. Emphasizes analysis of complex transactions and financial statement presentation.', N'Accounting', N'Business', 200, 4, N'ACC 211'),
  ('Winter28', N'SOC 348: Sociology of Education', N'An examination of educational institutions through sociological lenses. Topics include educational inequality, school segregation, cultural capital, hidden curriculum, standardized testing, and the role of education in social mobility and social reproduction.', N'Sociology', N'Arts & Sciences', 300, 3, N'SOC 201'),
  ('Spring28', N'ACC 208: Intermediate Accounting II', N'Continuation of Intermediate Accounting I covering accounting for liabilities, stockholders'' equity, investments, leases, pensions, income taxes, and cash flow statements. Emphasizes analysis of complex transactions and financial statement presentation.', N'Accounting', N'Business', 200, 4, N'ACC 211'),
  ('Summer28', N'PBH 219: Health Behavior and Promotion', N'A study of theories and strategies for promoting healthy behaviors. Topics include the health belief model, social cognitive theory, ecological models, motivational interviewing, and designing health communication campaigns for diverse populations.', N'Public Health', N'Health Sciences', 200, 4, N'PBH 101'),
  ('Fall26', N'POL 152: Introduction to International Relations', N'A survey of theories and issues in international relations including realism, liberalism, constructivism, security studies, international organizations, globalization, human rights, and environmental politics. Students analyze contemporary global challenges.', N'Political Science', N'Arts & Sciences', 100, 3, NULL),
  ('Fall26', N'PHL 385: Ethics of Artificial Intelligence', N'A philosophical examination of ethical issues raised by artificial intelligence and autonomous systems. Topics include algorithmic bias, accountability for AI decisions, privacy, the future of work, machine consciousness, and the alignment problem in advanced AI systems.', N'Philosophy', N'Arts & Sciences', 300, 3, N'PHL 102 or CSC 131'),
  ('Spring28', N'NUR 481: Capstone Clinical Practicum', N'An intensive preceptored clinical experience in which senior students practice in a specialty area. Students demonstrate competence in clinical judgment, interprofessional collaboration, and evidence-based practice.', N'Nursing', N'Health Sciences', 400, 4, N'Senior standing in NUR and all clinical courses'),
  ('Spring27', N'MUS 113: Music Theory I', N'A foundational course in the elements of music including notation, scales, intervals, chords, and basic harmony. Students develop ear training skills and learn to analyze musical structure through listening and written exercises.', N'Music', N'Fine Arts', 100, 3, NULL),
  ('Fall26', N'SOC 383: Sociology of Education', N'An examination of educational institutions through sociological lenses. Topics include educational inequality, school segregation, cultural capital, hidden curriculum, standardized testing, and the role of education in social mobility and social reproduction.', N'Sociology', N'Arts & Sciences', 300, 3, N'SOC 201'),
  ('Winter27', N'WLG 154: Elementary Spanish I', N'An introduction to the Spanish language emphasizing communication skills in listening, speaking, reading, and writing. Students learn basic vocabulary, grammar, and pronunciation while exploring diverse Spanish-speaking cultures through authentic materials.', N'World Languages', N'Arts & Sciences', 100, 3, NULL),
  ('Fall27', N'MUS 541: Graduate Seminar in Ethnomusicology', N'An advanced seminar in the study of music in its cultural context. Students engage with ethnomusicological theories and methods, conduct fieldwork, and produce research exploring the relationships between music, identity, and society.', N'Music', N'Fine Arts', 500, 3, N'Graduate standing'),
  ('Spring27', N'CHM 141: General Chemistry I', N'Introduction to the fundamental principles of chemistry including atomic structure, chemical bonding, stoichiometry, thermochemistry, and gas laws. Laboratory work develops quantitative measurement skills, safety practices, and scientific reasoning.', N'Chemistry', N'Arts & Sciences', 100, 4, NULL),
  ('Fall26', N'CSC 143: Digital Literacy and Computing', N'A survey of modern computing concepts for non-majors. Covers how computers process and store information, basics of web development, spreadsheet analysis, and an introduction to computational thinking. Students complete hands-on projects that connect computing to everyday problem-solving.', N'Computer Science', N'Arts & Sciences', 100, 3, NULL),
  ('Fall27', N'ARH 569: Graduate Seminar in Visual Culture', N'An advanced seminar examining theories of visual culture and their application to art historical analysis. Topics include spectatorship, representation, power, and the relationship between high art and popular visual media.', N'Art History', N'Fine Arts', 500, 4, N'Graduate standing'),
  ('Summer28', N'CSC 229: Object-Oriented Programming', N'An in-depth study of object-oriented design principles including encapsulation, inheritance, polymorphism, and abstraction. Students build multi-class applications in Java, learning design patterns and unit testing practices that form the foundation of modern software engineering.', N'Computer Science', N'Arts & Sciences', 200, 3, N'CSC 131'),
  ('Fall27', N'MTH 127: College Algebra', N'A foundational course covering algebraic concepts including linear and quadratic equations, polynomial functions, rational expressions, and systems of equations. Emphasizes analytical thinking and problem-solving techniques that prepare students for calculus and quantitative reasoning across disciplines.', N'Mathematics', N'Arts & Sciences', 100, 3, NULL),
  ('Spring27', N'PHY 306: Quantum Mechanics', N'A rigorous treatment of quantum theory including the Schrodinger equation, angular momentum, spin, perturbation theory, and the hydrogen atom. Students develop mathematical and conceptual tools for understanding quantum phenomena in atoms, molecules, and solids.', N'Physics', N'Arts & Sciences', 300, 2, N'PHY 221 and MTH 302'),
  ('Winter28', N'HIS 559: Graduate Seminar in Public History', N'An advanced seminar examining theories, methods, and ethical issues in public history practice. Students engage with debates about historical memory, representation, and the role of historians in public life while completing a significant public history project.', N'History', N'Arts & Sciences', 500, 3, N'Graduate standing'),
  ('Winter28', N'ECN 333: Behavioral Economics', N'An exploration of how psychological insights modify standard economic models. Topics include prospect theory, bounded rationality, time inconsistency, social preferences, and nudge theory. Students design and analyze behavioral experiments.', N'Economics', N'Business', 300, 4, N'ECN 201'),
  ('Fall26', N'ENG 357: Shakespeare', N'An intensive study of Shakespeare''s major plays including comedies, tragedies, histories, and romances. Students examine dramatic structure, language, performance history, and critical interpretations while considering Shakespeare''s lasting influence on literature and culture.', N'English', N'Arts & Sciences', 300, 4, N'ENG 103'),
  ('Spring28', N'MUS 143: Introduction to Music', N'A survey of music for non-majors exploring diverse genres, styles, and historical periods. Students develop active listening skills and learn to articulate their responses to music through guided analysis of representative works.', N'Music', N'Fine Arts', 100, 3, NULL),
  ('Spring28', N'THR 474: Senior Production Project', N'A capstone experience in which students serve in a major production role — director, designer, stage manager, or lead performer — on a departmental production. Students demonstrate professional-level competence in their area of concentration.', N'Theatre', N'Fine Arts', 400, 3, N'Senior standing in THR'),
  ('Summer27', N'HIS 344: Historical Research Methods', N'A hands-on course in the methods and practices of historical research. Students learn to locate and evaluate primary sources, construct historical arguments, navigate archives, and write research papers that meet professional standards in the discipline.', N'History', N'Arts & Sciences', 300, 3, N'Two 200-level HIS courses'),
  ('Winter27', N'POL 355: International Political Economy', N'An analysis of the intersection of politics and economics in the global arena. Topics include international trade, monetary systems, development, inequality, multinational corporations, and the politics of globalization.', N'Political Science', N'Arts & Sciences', 300, 2, N'POL 102 or ECN 201'),
  ('Spring27', N'BIO 187: Human Biology', N'A survey of human biological systems for non-majors. Covers anatomy and physiology of major organ systems, nutrition, immunology, and genetics as they relate to human health and disease. Emphasizes critical evaluation of health claims in the media.', N'Biology', N'Arts & Sciences', 100, 4, NULL),
  ('Fall27', N'MUS 302: Composition', N'A creative course in composing music for various ensembles and instruments. Students develop compositional techniques including melody, harmony, counterpoint, orchestration, and formal design while finding their personal artistic voice.', N'Music', N'Fine Arts', 300, 4, N'MUS 201'),
  ('Summer28', N'SOC 241: Sociology of Health and Illness', N'An examination of social factors influencing health, illness, and healthcare delivery. Topics include social determinants of health, health disparities, medicalization, patient-provider relationships, and healthcare systems in comparative perspective.', N'Sociology', N'Arts & Sciences', 200, 3, N'SOC 101'),
  ('Spring27', N'CHM 357: Environmental Chemistry', N'An examination of chemical processes in the environment including atmospheric chemistry, water quality, soil chemistry, and pollutant fate and transport. Students analyze environmental data and evaluate remediation strategies for contaminated sites.', N'Chemistry', N'Arts & Sciences', 300, 3, N'CHM 102'),
  ('Fall26', N'NUR 394: Mental Health Nursing', N'A clinical course in nursing care for individuals experiencing mental health challenges. Topics include therapeutic communication, psychiatric assessment, psychopharmacology, crisis intervention, and community-based mental health services.', N'Nursing', N'Health Sciences', 300, 4, N'NUR 201'),
  ('Spring27', N'SOC 189: Social Problems', N'An examination of major social problems including poverty, crime, substance abuse, healthcare access, environmental degradation, and educational inequality. Students analyze the structural causes of social problems and evaluate proposed solutions using sociological frameworks.', N'Sociology', N'Arts & Sciences', 100, 2, NULL),
  ('Spring27', N'MUS 516: Graduate Seminar in Ethnomusicology', N'An advanced seminar in the study of music in its cultural context. Students engage with ethnomusicological theories and methods, conduct fieldwork, and produce research exploring the relationships between music, identity, and society.', N'Music', N'Fine Arts', 500, 3, N'Graduate standing'),
  ('Spring28', N'PBH 349: Global Health', N'An examination of health challenges in a global context. Topics include infectious disease control, maternal and child health, nutrition, health systems strengthening, global health governance, and the social determinants of health across nations.', N'Public Health', N'Health Sciences', 300, 3, N'PBH 201'),
  ('Spring27', N'ACC 149: Principles of Financial Accounting', N'An introduction to the fundamental concepts and practices of financial accounting. Topics include the accounting cycle, financial statement preparation, revenue recognition, asset valuation, and analysis of financial reports. Students develop skills in recording and interpreting business transactions.', N'Accounting', N'Business', 100, 3, NULL),
  ('Fall27', N'PHY 363: Quantum Mechanics', N'A rigorous treatment of quantum theory including the Schrodinger equation, angular momentum, spin, perturbation theory, and the hydrogen atom. Students develop mathematical and conceptual tools for understanding quantum phenomena in atoms, molecules, and solids.', N'Physics', N'Arts & Sciences', 300, 3, N'PHY 221 and MTH 302'),
  ('Spring27', N'PBH 105: Introduction to Public Health', N'An overview of public health principles including epidemiology, health promotion, disease prevention, environmental health, and health policy. Students explore how public health systems address population-level health challenges including infectious disease, chronic conditions, and health disparities.', N'Public Health', N'Health Sciences', 100, 3, NULL),
  ('Spring28', N'WLG 396: Hispanic Literature and Film', N'A study of major works of literature and film from Spain and Latin America in their cultural and historical contexts. Students develop advanced reading and analytical skills while exploring themes of identity, justice, memory, and artistic innovation.', N'World Languages', N'Arts & Sciences', 300, 3, N'WLG 202'),
  ('Winter28', N'CTV 188: Introduction to Television Production', N'A hands-on introduction to television production techniques including camera operation, lighting, audio recording, directing, and non-linear editing. Students produce short-form video projects across multiple genres.', N'Cinema & Television', N'Communications', 100, 3, NULL),
  ('Fall26', N'ARH 386: Contemporary Art Since 1960', N'An examination of art from the 1960s to the present including Pop Art, Minimalism, Conceptual Art, Installation, Performance, and Digital Art. Students analyze how contemporary artists engage with issues of identity, globalization, and technology.', N'Art History', N'Fine Arts', 300, 3, N'ARH 211'),
  ('Winter28', N'CHM 134: General Chemistry I', N'Introduction to the fundamental principles of chemistry including atomic structure, chemical bonding, stoichiometry, thermochemistry, and gas laws. Laboratory work develops quantitative measurement skills, safety practices, and scientific reasoning.', N'Chemistry', N'Arts & Sciences', 100, 3, NULL),
  ('Winter27', N'PSY 272: Social Psychology', N'An examination of how social contexts influence individual thought, feeling, and behavior. Topics include conformity, persuasion, group dynamics, prejudice, attraction, and prosocial behavior. Students critically evaluate classic and contemporary research.', N'Psychology', N'Arts & Sciences', 200, 2, N'PSY 101'),
  ('Fall27', N'SCM 337: Crisis Communications', N'An examination of communication strategies during organizational crises. Students analyze real crisis cases, develop crisis communication plans, conduct media training exercises, and learn to manage reputation in the social media age.', N'Strategic Communications', N'Communications', 300, 3, N'SCM 201'),
  ('Fall26', N'SPE 102: Introduction to Special Education', N'An overview of the field of special education including disability categories, legal foundations (IDEA, Section 504, ADA), inclusive practices, and the continuum of services. Students develop an understanding of diverse learner needs and strengths.', N'Special Education', N'Education', 100, 3, NULL),
  ('Spring28', N'BAN 488: Capstone in Business Analytics', N'A culminating project course in which students solve a real business problem using advanced analytics. Teams work with industry partners to define problems, analyze data, build models, and present actionable recommendations.', N'Business Analytics', N'Business', 400, 3, N'Senior standing in BAN'),
  ('Spring28', N'MTH 318: Probability and Mathematical Statistics', N'A rigorous treatment of probability theory and statistical inference. Topics include random variables, probability distributions, expectation, moment generating functions, maximum likelihood estimation, and hypothesis testing. Provides the mathematical foundation for data science and actuarial work.', N'Mathematics', N'Arts & Sciences', 300, 3, N'MTH 242');
INSERT INTO dbo.CourseCatalog (TermID, CourseTitle, CourseDescription, Department, College, CourseLevel, Credits, Prerequisites)
VALUES
  ('Winter28', N'PHY 486: Electrodynamics', N'An advanced study of electromagnetic theory based on Maxwell''s equations. Topics include boundary value problems, electromagnetic waves, radiation, and special relativity. Students develop skills in vector calculus and mathematical physics.', N'Physics', N'Arts & Sciences', 400, 3, N'PHY 312 and MTH 302'),
  ('Winter28', N'JOU 387: Investigative Reporting', N'An advanced course in long-form investigative journalism. Students develop investigative techniques including document analysis, source development, Freedom of Information requests, and ethical considerations in exposing wrongdoing.', N'Journalism', N'Communications', 300, 3, N'JOU 201'),
  ('Spring28', N'ELE 378: Embedded Systems', N'A practical course in designing microcontroller-based systems. Students program ARM-based processors, interface with sensors and actuators, implement communication protocols, and develop real-time embedded applications.', N'Electrical Engineering', N'Engineering', 300, 3, N'ELE 202 and programming experience'),
  ('Spring28', N'SOC 249: Race and Ethnicity', N'A sociological analysis of race and ethnic relations in the United States and globally. Topics include the social construction of race, immigration, assimilation, institutional racism, intersectionality, and social movements for racial justice.', N'Sociology', N'Arts & Sciences', 200, 3, N'SOC 101'),
  ('Winter27', N'EED 315: Literacy Development and Instruction', N'A study of how children learn to read and write, and how teachers can support literacy development. Topics include phonemic awareness, fluency, vocabulary, comprehension strategies, writing instruction, and assessment of literacy skills.', N'Elementary Education', N'Education', 300, 3, N'EED 201'),
  ('Spring27', N'PHL 182: Logic and Critical Thinking', N'A practical course in formal and informal logic. Students learn to identify argument structures, detect fallacies, evaluate evidence, and construct sound arguments. Develops analytical reasoning skills applicable across academic disciplines and everyday decision-making.', N'Philosophy', N'Arts & Sciences', 100, 3, NULL),
  ('Winter27', N'PHY 524: Advanced Quantum Field Theory', N'Graduate-level introduction to quantum field theory covering canonical quantization, Feynman diagrams, renormalization, and gauge theories. Students explore applications to particle physics and condensed matter systems.', N'Physics', N'Arts & Sciences', 500, 3, N'PHY 321 and graduate standing'),
  ('Spring27', N'MTH 588: Graduate Seminar in Applied Mathematics', N'An advanced seminar exploring current research topics in applied mathematics. Students read recent publications, present findings, and develop original research questions. Topics rotate and may include mathematical biology, computational fluid dynamics, or network analysis.', N'Mathematics', N'Arts & Sciences', 500, 4, N'Graduate standing in MTH'),
  ('Spring28', N'BAN 261: Data Management for Business', N'A practical course in managing and querying business data. Students learn relational database concepts, SQL query writing, data cleaning and transformation techniques, and basic data warehousing principles. Applications focus on marketing, finance, and operations datasets.', N'Business Analytics', N'Business', 200, 2, N'BAN 101'),
  ('Summer27', N'CIV 455: Senior Design in Civil Engineering', N'A capstone project in which student teams design a civil engineering system or infrastructure component. Projects integrate structural, environmental, and geotechnical considerations with sustainability, cost analysis, and regulatory compliance.', N'Civil Engineering', N'Engineering', 400, 3, N'Senior standing in CIV'),
  ('Summer28', N'MKT 469: Strategic Marketing Management', N'A capstone course integrating marketing concepts in strategic decision-making. Students analyze complex marketing cases, develop comprehensive go-to-market strategies, and present recommendations to industry panels.', N'Marketing', N'Business', 400, 3, N'Senior standing in MKT'),
  ('Fall27', N'ARH 338: Contemporary Art Since 1960', N'An examination of art from the 1960s to the present including Pop Art, Minimalism, Conceptual Art, Installation, Performance, and Digital Art. Students analyze how contemporary artists engage with issues of identity, globalization, and technology.', N'Art History', N'Fine Arts', 300, 3, N'ARH 211'),
  ('Summer27', N'POL 266: Public Policy Analysis', N'An examination of the policy-making process from agenda-setting through implementation and evaluation. Students analyze policies in areas such as healthcare, education, the environment, and criminal justice using frameworks from policy analysis.', N'Political Science', N'Arts & Sciences', 200, 3, N'POL 101'),
  ('Spring27', N'MUS 128: Introduction to Music', N'A survey of music for non-majors exploring diverse genres, styles, and historical periods. Students develop active listening skills and learn to articulate their responses to music through guided analysis of representative works.', N'Music', N'Fine Arts', 100, 3, NULL),
  ('Fall27', N'PHY 361: Quantum Mechanics', N'A rigorous treatment of quantum theory including the Schrodinger equation, angular momentum, spin, perturbation theory, and the hydrogen atom. Students develop mathematical and conceptual tools for understanding quantum phenomena in atoms, molecules, and solids.', N'Physics', N'Arts & Sciences', 300, 4, N'PHY 221 and MTH 302'),
  ('Fall26', N'BIO 373: Bioinformatics', N'An introduction to computational approaches for analyzing biological data. Students learn to use databases, sequence alignment tools, phylogenetic analysis, and basic programming for genomic data analysis. Covers applications in personalized medicine and drug discovery.', N'Biology', N'Arts & Sciences', 300, 3, N'BIO 211 and introductory programming or statistics'),
  ('Spring27', N'MTH 376: Probability and Mathematical Statistics', N'A rigorous treatment of probability theory and statistical inference. Topics include random variables, probability distributions, expectation, moment generating functions, maximum likelihood estimation, and hypothesis testing. Provides the mathematical foundation for data science and actuarial work.', N'Mathematics', N'Arts & Sciences', 300, 3, N'MTH 242'),
  ('Spring27', N'FIN 265: Investments', N'An introduction to investment theory and practice. Topics include portfolio theory, asset pricing models, equity and fixed-income analysis, derivatives, mutual funds, and behavioral finance. Students manage a simulated investment portfolio.', N'Finance', N'Business', 200, 3, N'FIN 102'),
  ('Winter28', N'BIO 306: Neuroscience', N'An interdisciplinary exploration of the nervous system from molecular to behavioral levels. Topics include neuronal signaling, synaptic transmission, sensory systems, motor control, learning and memory, and neurological disorders. Bridges biology and psychology perspectives.', N'Biology', N'Arts & Sciences', 300, 3, N'BIO 211 or PSY 201'),
  ('Spring28', N'POL 301: International Political Economy', N'An analysis of the intersection of politics and economics in the global arena. Topics include international trade, monetary systems, development, inequality, multinational corporations, and the politics of globalization.', N'Political Science', N'Arts & Sciences', 300, 3, N'POL 102 or ECN 201'),
  ('Fall26', N'PHL 324: Existentialism', N'A study of existentialist philosophy through works of Kierkegaard, Nietzsche, Heidegger, Sartre, Beauvoir, and Camus. Students explore themes of freedom, anxiety, authenticity, absurdity, and the construction of meaning in a seemingly indifferent universe.', N'Philosophy', N'Arts & Sciences', 300, 3, N'PHL 101'),
  ('Winter28', N'PHY 294: Modern Physics', N'An introduction to twentieth-century physics including special relativity, quantum mechanics, atomic structure, nuclear physics, and particle physics. Students explore the experimental evidence and mathematical frameworks that revolutionized our understanding of nature.', N'Physics', N'Arts & Sciences', 200, 4, N'PHY 212 and MTH 242'),
  ('Winter28', N'CTV 122: Introduction to Television Production', N'A hands-on introduction to television production techniques including camera operation, lighting, audio recording, directing, and non-linear editing. Students produce short-form video projects across multiple genres.', N'Cinema & Television', N'Communications', 100, 3, NULL),
  ('Fall26', N'PSY 505: Graduate Seminar in Cognitive Science', N'An interdisciplinary seminar exploring the intersection of psychology, neuroscience, computer science, and philosophy in understanding the mind. Students examine current debates about consciousness, artificial intelligence, and embodied cognition.', N'Psychology', N'Arts & Sciences', 500, 3, N'Graduate standing'),
  ('Spring28', N'CIV 467: Senior Design in Civil Engineering', N'A capstone project in which student teams design a civil engineering system or infrastructure component. Projects integrate structural, environmental, and geotechnical considerations with sustainability, cost analysis, and regulatory compliance.', N'Civil Engineering', N'Engineering', 400, 4, N'Senior standing in CIV'),
  ('Fall27', N'ART 232: Printmaking', N'An introduction to printmaking techniques including relief, intaglio, screen printing, and monotype. Students explore the unique aesthetic possibilities of each process while developing technical skills and artistic concepts.', N'Studio Art', N'Fine Arts', 200, 3, N'ART 101'),
  ('Spring28', N'THR 392: Directing', N'A study of the art and practice of theatrical direction. Topics include script analysis, concept development, staging, working with actors, and production management. Students direct scenes and one-act plays for public performance.', N'Theatre', N'Fine Arts', 300, 3, N'THR 102 and THR 211'),
  ('Spring27', N'CIV 266: Surveying and Geomatics', N'An introduction to land surveying techniques and geospatial data collection. Topics include measuring distances and angles, leveling, GPS surveying, coordinate systems, and GIS applications in civil engineering.', N'Civil Engineering', N'Engineering', 200, 3, N'MTH 241'),
  ('Fall27', N'BIO 107: Human Biology', N'A survey of human biological systems for non-majors. Covers anatomy and physiology of major organ systems, nutrition, immunology, and genetics as they relate to human health and disease. Emphasizes critical evaluation of health claims in the media.', N'Biology', N'Arts & Sciences', 100, 4, NULL),
  ('Summer28', N'EED 373: Classroom Management and Community Building', N'A practical course in creating positive, productive classroom environments. Students learn proactive management strategies, restorative practices, culturally responsive approaches, and techniques for building inclusive classroom communities.', N'Elementary Education', N'Education', 300, 3, N'EED 202'),
  ('Fall27', N'JOU 249: News Writing and Reporting', N'A practical course in news writing for digital and print media. Students learn to write leads, conduct interviews, cover beats, and produce stories on deadline. Emphasizes accuracy, fairness, AP style, and multimedia storytelling.', N'Journalism', N'Communications', 200, 3, N'JOU 101'),
  ('Spring28', N'EED 295: Curriculum and Instructional Design', N'An introduction to designing effective instruction for diverse learners. Students learn to develop lesson plans, align objectives with assessments, differentiate instruction, and integrate technology meaningfully into teaching practice.', N'Elementary Education', N'Education', 200, 3, N'EED 101'),
  ('Spring28', N'ACC 315: Accounting Information Systems', N'An examination of how information technology supports accounting functions. Topics include database design for accounting applications, internal controls for IT systems, enterprise resource planning, data analytics, and cybersecurity considerations in financial reporting.', N'Accounting', N'Business', 300, 3, N'ACC 211 and CSC 131 or BAN 201'),
  ('Summer27', N'SCM 197: Introduction to Strategic Communications', N'An overview of the strategic communications field including public relations, advertising, and integrated marketing communications. Students learn campaign planning, message development, media relations, and the role of communication in organizational strategy.', N'Strategic Communications', N'Communications', 100, 3, NULL),
  ('Spring28', N'FIN 228: Investments', N'An introduction to investment theory and practice. Topics include portfolio theory, asset pricing models, equity and fixed-income analysis, derivatives, mutual funds, and behavioral finance. Students manage a simulated investment portfolio.', N'Finance', N'Business', 200, 2, N'FIN 102'),
  ('Winter27', N'POL 145: Introduction to American Government', N'An overview of the American political system including the Constitution, federalism, civil liberties, political parties, elections, Congress, the presidency, and the judiciary. Students analyze current political events using foundational concepts in political science.', N'Political Science', N'Arts & Sciences', 100, 3, NULL),
  ('Fall27', N'ELE 432: Senior Design in Electrical Engineering', N'A capstone project in which student teams design and build an electrical or computer engineering system. Projects address real-world problems and include requirements specification, prototyping, testing, and documentation.', N'Electrical Engineering', N'Engineering', 400, 3, N'Senior standing in ELE'),
  ('Summer27', N'PHL 238: Political Philosophy', N'An examination of theories of justice, liberty, equality, and political obligation. Students read foundational texts from Plato, Locke, Mill, Marx, and Rawls alongside contemporary debates about democracy, multiculturalism, and global justice.', N'Philosophy', N'Arts & Sciences', 200, 3, N'PHL 101'),
  ('Summer27', N'EXS 302: Clinical Exercise Physiology', N'A study of exercise prescription for individuals with chronic diseases and special conditions including cardiovascular disease, diabetes, obesity, pulmonary disease, and musculoskeletal disorders. Prepares students for clinical exercise testing certification.', N'Exercise Science', N'Health Sciences', 300, 3, N'EXS 211'),
  ('Winter28', N'ENV 146: Introduction to Environmental Science', N'A multidisciplinary survey of environmental issues including climate change, biodiversity loss, pollution, resource depletion, and sustainable development. Integrates concepts from biology, chemistry, geology, and policy to understand human impacts on natural systems.', N'Environmental Science', N'Arts & Sciences', 100, 3, NULL),
  ('Spring27', N'CTV 386: Film Theory and Criticism', N'An examination of major theoretical approaches to cinema including auteur theory, genre theory, feminist film theory, psychoanalytic criticism, and postcolonial perspectives. Students write critical essays analyzing films through theoretical frameworks.', N'Cinema & Television', N'Communications', 300, 3, N'CTV 101'),
  ('Winter27', N'MGT 144: Introduction to Management', N'An overview of management theory and practice covering planning, organizing, leading, and controlling functions. Students explore classical and contemporary management approaches, ethical leadership, and the changing nature of work in a globalized economy.', N'Management', N'Business', 100, 3, NULL),
  ('Winter27', N'PHY 119: Astronomy and the Universe', N'A survey of modern astronomy for non-science majors. Topics include the solar system, stellar evolution, galaxies, cosmology, and the search for extraterrestrial life. Includes observatory sessions and analysis of astronomical data.', N'Physics', N'Arts & Sciences', 100, 4, NULL),
  ('Winter27', N'THR 175: Acting I', N'A foundational course in acting technique emphasizing relaxation, concentration, imagination, sensory work, and improvisation. Students develop skills in physical and vocal expression through exercises, scene work, and performance projects.', N'Theatre', N'Fine Arts', 100, 3, NULL),
  ('Winter28', N'ART 495: Senior Exhibition', N'A capstone course in which students develop and present a cohesive body of work in a professional exhibition. Students write an artist statement, install their work, and participate in a public critique and reception.', N'Studio Art', N'Fine Arts', 400, 3, N'Senior standing in ART'),
  ('Spring27', N'CHM 253: Organic Chemistry II', N'Continuation of Organic Chemistry I with emphasis on advanced reaction mechanisms, synthesis strategies, aromatic chemistry, and spectroscopic identification methods including NMR, IR, and mass spectrometry.', N'Chemistry', N'Arts & Sciences', 200, 3, N'CHM 201'),
  ('Fall27', N'ENV 341: Climate Change Science and Policy', N'A comprehensive examination of climate change from scientific and policy perspectives. Covers atmospheric physics, climate modeling, observed impacts, mitigation strategies, adaptation planning, and international climate negotiations. Students analyze climate data and evaluate policy proposals.', N'Environmental Science', N'Arts & Sciences', 300, 1, N'ENV 101 and one science elective'),
  ('Winter28', N'MTH 328: Differential Equations', N'A study of ordinary differential equations and their applications. Topics include first-order equations, linear systems, Laplace transforms, numerical methods, and modeling of physical and biological systems. Emphasizes both analytical solutions and qualitative behavior analysis.', N'Mathematics', N'Arts & Sciences', 300, 3, N'MTH 242'),
  ('Fall27', N'CHM 278: Analytical Chemistry', N'A study of quantitative and qualitative analytical methods including gravimetry, titrimetry, spectrophotometry, chromatography, and electroanalytical techniques. Emphasizes method validation, error analysis, and quality assurance in chemical measurements.', N'Chemistry', N'Arts & Sciences', 200, 3, N'CHM 102'),
  ('Summer28', N'JOU 348: Data Journalism', N'An advanced course in using data to find and tell stories. Students learn to obtain public records, analyze datasets using spreadsheets and programming tools, create data visualizations, and produce data-driven investigative reports.', N'Journalism', N'Communications', 300, 3, N'JOU 201 and basic statistics');
INSERT INTO dbo.CourseCatalog (TermID, CourseTitle, CourseDescription, Department, College, CourseLevel, Credits, Prerequisites)
VALUES
  ('Spring27', N'CHM 511: Graduate Research in Chemistry', N'Supervised research in an active faculty research lab. Students conduct original research, participate in group meetings, and present progress reports. Culminates in a thesis or publishable manuscript.', N'Chemistry', N'Arts & Sciences', 500, 3, N'Graduate standing'),
  ('Fall27', N'PSY 342: Cognitive Psychology', N'An in-depth examination of mental processes including attention, perception, memory, language, problem-solving, and decision-making. Students explore computational models of cognition and evaluate evidence from behavioral experiments and brain imaging studies.', N'Psychology', N'Arts & Sciences', 300, 3, N'PSY 201'),
  ('Winter28', N'PHL 494: Senior Thesis in Philosophy', N'An independent research project resulting in a substantial philosophical essay. Students work with a faculty advisor to develop an original argument, engage with scholarly literature, and present their thesis at the departmental colloquium.', N'Philosophy', N'Arts & Sciences', 400, 3, N'Senior standing in PHL'),
  ('Summer27', N'MEC 275: Thermodynamics', N'A study of energy, heat, work, and their transformation in engineering systems. Topics include the first and second laws, entropy, properties of pure substances, power and refrigeration cycles, and energy efficiency analysis.', N'Mechanical Engineering', N'Engineering', 200, 3, N'PHY 211 and MTH 242'),
  ('Spring27', N'CPE 391: Real-Time Systems', N'A study of computing systems with timing constraints. Topics include real-time scheduling, priority inversion, embedded real-time operating systems, timing analysis, and safety-critical system design.', N'Computer Engineering', N'Engineering', 300, 3, N'CPE 211 and ELE 301'),
  ('Fall26', N'NUR 434: Leadership and Management in Nursing', N'A course in nursing leadership including healthcare systems, quality improvement, patient safety, team management, ethical decision-making, and healthcare policy advocacy. Prepares students for professional leadership roles.', N'Nursing', N'Health Sciences', 400, 4, N'Senior standing in NUR'),
  ('Fall26', N'SOC 329: Sociology of Education', N'An examination of educational institutions through sociological lenses. Topics include educational inequality, school segregation, cultural capital, hidden curriculum, standardized testing, and the role of education in social mobility and social reproduction.', N'Sociology', N'Arts & Sciences', 300, 3, N'SOC 201'),
  ('Fall26', N'BIO 278: Microbiology', N'A study of the biology of microorganisms including bacteria, viruses, fungi, and protists. Covers microbial structure, metabolism, genetics, pathogenesis, and immunological responses. Laboratory work includes aseptic technique, staining, culturing, and identification methods.', N'Biology', N'Arts & Sciences', 200, 3, N'BIO 101 and CHM 102'),
  ('Winter27', N'WLG 548: Graduate Studies in Applied Linguistics', N'An advanced seminar in applied linguistics covering second language acquisition, language pedagogy, sociolinguistics, and corpus linguistics. Students design and conduct research projects addressing practical questions in language teaching and learning.', N'World Languages', N'Arts & Sciences', 500, 3, N'Graduate standing'),
  ('Winter27', N'BIO 244: Genetics', N'A comprehensive study of heredity and gene expression from molecular to population levels. Topics include Mendelian genetics, chromosomal inheritance, DNA replication, transcription, translation, gene regulation, and population genetics. Laboratory includes genetic crosses and DNA analysis.', N'Biology', N'Arts & Sciences', 200, 4, N'BIO 101 and BIO 102'),
  ('Winter27', N'BAN 425: Capstone in Business Analytics', N'A culminating project course in which students solve a real business problem using advanced analytics. Teams work with industry partners to define problems, analyze data, build models, and present actionable recommendations.', N'Business Analytics', N'Business', 400, 3, N'Senior standing in BAN'),
  ('Fall26', N'PSY 145: Psychology of Adjustment', N'An exploration of how individuals cope with life challenges including stress, relationships, career decisions, and mental health. Students apply psychological research to understand personal growth and develop evidence-based strategies for well-being.', N'Psychology', N'Arts & Sciences', 100, 3, NULL),
  ('Winter28', N'JOU 265: Photojournalism', N'A course in visual storytelling through photography. Students learn composition, lighting, and digital editing techniques while developing the ability to capture news events and human interest stories through compelling images.', N'Journalism', N'Communications', 200, 3, N'JOU 101'),
  ('Spring27', N'SPE 391: Inclusive Instructional Strategies', N'An advanced methods course in adapting instruction for students with diverse learning needs. Topics include universal design for learning, differentiated instruction, assistive technology, co-teaching models, and evidence-based practices for students with specific disabilities.', N'Special Education', N'Education', 300, 3, N'SPE 201 and EED 202'),
  ('Fall27', N'JOU 102: Media and Society', N'An examination of the role of media in shaping public opinion, culture, and political discourse. Topics include media ownership, media literacy, representation, propaganda, the digital transformation of news, and the economics of the media industry.', N'Journalism', N'Communications', 100, 3, NULL),
  ('Summer28', N'POL 541: Graduate Seminar in Political Theory', N'An advanced seminar examining classic and contemporary political thought. Students engage with texts from ancient, modern, and postmodern traditions while exploring questions of justice, power, freedom, and democracy.', N'Political Science', N'Arts & Sciences', 500, 3, N'Graduate standing'),
  ('Fall27', N'ENG 243: World Literature', N'A comparative study of literary traditions from Africa, Asia, Latin America, the Middle East, and Europe. Students read works in translation and explore themes of identity, migration, colonialism, and cultural exchange across global literary traditions.', N'English', N'Arts & Sciences', 200, 3, N'ENG 103'),
  ('Fall27', N'CPE 372: Operating System Design', N'An examination of operating system internals with emphasis on implementation. Topics include process scheduling, memory management, file systems, device drivers, and system calls. Students implement kernel modules in a Unix-like environment.', N'Computer Engineering', N'Engineering', 300, 3, N'CPE 211 and CSC 231'),
  ('Spring27', N'CTV 213: Documentary Filmmaking', N'A practical course in documentary production. Students study documentary traditions, develop stories, conduct interviews, and produce short documentary films. Covers ethical considerations in representing real people and events on screen.', N'Cinema & Television', N'Communications', 200, 3, N'CTV 102'),
  ('Winter28', N'ACC 547: Graduate Seminar in Data Analytics for Accountants', N'An advanced course in applying data analytics to accounting and auditing problems. Students use Python, SQL, and visualization tools to detect anomalies, automate audit procedures, and extract insights from large financial datasets.', N'Accounting', N'Business', 500, 4, N'ACC 303 and graduate standing'),
  ('Summer27', N'ELE 355: Electronics', N'A study of semiconductor devices and electronic circuit design. Topics include diodes, transistors (BJT and MOSFET), amplifier design, frequency response, feedback, and operational amplifier circuits.', N'Electrical Engineering', N'Engineering', 300, 3, N'ELE 201'),
  ('Winter28', N'ACC 381: Accounting Information Systems', N'An examination of how information technology supports accounting functions. Topics include database design for accounting applications, internal controls for IT systems, enterprise resource planning, data analytics, and cybersecurity considerations in financial reporting.', N'Accounting', N'Business', 300, 3, N'ACC 211 and CSC 131 or BAN 201'),
  ('Summer27', N'HLA 204: Health Information Systems', N'An examination of information technology in healthcare including electronic health records, health information exchange, clinical decision support, data governance, and cybersecurity. Students explore how technology improves care delivery and operational efficiency.', N'Health Administration', N'Health Sciences', 200, 3, N'HLA 101'),
  ('Fall27', N'MEC 178: Introduction to Engineering', N'A broad introduction to engineering disciplines and the engineering design process. Students work in teams to solve open-ended design challenges using computer-aided design tools, prototyping, and iterative testing. Develops creative problem-solving and communication skills.', N'Mechanical Engineering', N'Engineering', 100, 3, NULL),
  ('Fall27', N'MTH 348: Abstract Algebra', N'An introduction to algebraic structures including groups, rings, and fields. Students study concepts of homomorphism, isomorphism, and quotient structures while developing skills in abstract mathematical reasoning and proof construction.', N'Mathematics', N'Arts & Sciences', 300, 3, N'MTH 244'),
  ('Fall26', N'THR 394: Playwriting', N'A workshop course in dramatic writing. Students study dramatic structure, create original short and full-length plays, participate in peer critique, and hear their work read by student actors. Explores diverse storytelling traditions and voices.', N'Theatre', N'Fine Arts', 300, 3, N'THR 101 or ENG 211'),
  ('Fall27', N'ART 287: Painting I', N'An introduction to painting techniques and concepts. Students work in oil and acrylic to develop skills in color mixing, composition, surface quality, and visual expression. Subjects include still life, landscape, and the figure.', N'Studio Art', N'Fine Arts', 200, 3, N'ART 101'),
  ('Summer28', N'CHM 118: General Chemistry I', N'Introduction to the fundamental principles of chemistry including atomic structure, chemical bonding, stoichiometry, thermochemistry, and gas laws. Laboratory work develops quantitative measurement skills, safety practices, and scientific reasoning.', N'Chemistry', N'Arts & Sciences', 100, 3, NULL),
  ('Spring28', N'PHY 175: General Physics II', N'Continuation of General Physics I covering electricity, magnetism, optics, and modern physics. Topics include electric fields, circuits, electromagnetic waves, geometric optics, and an introduction to quantum phenomena.', N'Physics', N'Arts & Sciences', 100, 4, N'PHY 101'),
  ('Spring27', N'EDL 278: Foundations of Educational Leadership', N'An introduction to leadership theories and their application in educational settings. Students explore transformational, distributed, and servant leadership models while examining the roles and responsibilities of school administrators.', N'Educational Leadership', N'Education', 200, 3, N'EED 101 or SPE 101'),
  ('Fall26', N'PHL 339: Philosophy of Science', N'An analysis of the foundations, methods, and implications of scientific inquiry. Topics include the problem of induction, theory change, scientific explanation, realism vs. anti-realism, and the relationship between science and values.', N'Philosophy', N'Arts & Sciences', 300, 3, N'PHL 101 and one science course'),
  ('Winter27', N'PHY 466: Senior Thesis in Physics', N'Independent research culminating in a written thesis and public presentation. Students work closely with a faculty advisor on an original project in experimental or theoretical physics.', N'Physics', N'Arts & Sciences', 400, 3, N'Senior standing in PHY'),
  ('Spring28', N'SPE 545: Graduate Seminar in Learning Disabilities', N'An advanced seminar examining current research on learning disabilities. Topics include neurological bases, evidence-based interventions, response to intervention, and the intersection of learning disabilities with cultural and linguistic diversity.', N'Special Education', N'Education', 500, 3, N'Graduate standing'),
  ('Summer28', N'CPE 373: VLSI Design', N'An introduction to the design of very large scale integrated circuits. Topics include CMOS logic design, layout, verification, timing analysis, and low-power techniques. Students design and simulate circuits using industry CAD tools.', N'Computer Engineering', N'Engineering', 300, 4, N'ELE 202'),
  ('Spring27', N'JOU 489: Senior Capstone in Journalism', N'A culminating project in which students produce a substantial piece of original journalism — investigative report, documentary, multimedia project, or podcast series. Students pitch, research, produce, and present their work.', N'Journalism', N'Communications', 400, 3, N'Senior standing in JOU'),
  ('Spring27', N'MKT 234: Consumer Behavior', N'An examination of how individuals and groups make purchasing decisions. Topics include motivation, perception, learning, attitude formation, cultural influences, and the decision-making process. Students apply behavioral insights to marketing strategy development.', N'Marketing', N'Business', 200, 3, N'MKT 101'),
  ('Winter27', N'CIV 361: Geotechnical Engineering', N'A study of soil mechanics and foundation engineering. Topics include soil classification, effective stress, seepage, consolidation, shear strength, bearing capacity, and slope stability analysis.', N'Civil Engineering', N'Engineering', 300, 3, N'CIV 201 and geology course'),
  ('Winter28', N'ACC 267: Cost Accounting', N'A comprehensive study of cost accounting systems and techniques. Topics include job-order costing, process costing, activity-based costing, standard costing, and cost-volume-profit analysis. Students use accounting data to support management decision-making.', N'Accounting', N'Business', 200, 3, N'ACC 102'),
  ('Fall27', N'HLA 428: Healthcare Strategic Management', N'A capstone course in developing and implementing strategic plans for healthcare organizations. Students analyze competitive environments, assess organizational capabilities, develop strategic initiatives, and present recommendations to industry panels.', N'Health Administration', N'Health Sciences', 400, 3, N'Senior standing in HLA'),
  ('Summer28', N'MTH 152: College Algebra', N'A foundational course covering algebraic concepts including linear and quadratic equations, polynomial functions, rational expressions, and systems of equations. Emphasizes analytical thinking and problem-solving techniques that prepare students for calculus and quantitative reasoning across disciplines.', N'Mathematics', N'Arts & Sciences', 100, 3, NULL),
  ('Spring28', N'JOU 303: Data Journalism', N'An advanced course in using data to find and tell stories. Students learn to obtain public records, analyze datasets using spreadsheets and programming tools, create data visualizations, and produce data-driven investigative reports.', N'Journalism', N'Communications', 300, 3, N'JOU 201 and basic statistics'),
  ('Summer28', N'ECN 418: Senior Seminar in Economics', N'A capstone seminar in which students conduct original empirical research on an economic question. Students develop a research proposal, collect and analyze data, and present findings in both written and oral formats.', N'Economics', N'Business', 400, 4, N'ECN 221 and senior standing'),
  ('Winter28', N'SOC 316: Sociology of Education', N'An examination of educational institutions through sociological lenses. Topics include educational inequality, school segregation, cultural capital, hidden curriculum, standardized testing, and the role of education in social mobility and social reproduction.', N'Sociology', N'Arts & Sciences', 300, 3, N'SOC 201'),
  ('Spring27', N'MUS 258: Music History: Medieval to Classical', N'A survey of Western art music from the medieval period through the Classical era. Students study representative works, examine the cultural contexts of musical production, and develop skills in critical listening and musical analysis.', N'Music', N'Fine Arts', 200, 3, N'MUS 101'),
  ('Fall27', N'ELE 235: Circuit Analysis', N'A study of linear electrical circuits including DC and AC analysis, Kirchhoff''s laws, Thevenin and Norton equivalents, operational amplifiers, and transient response. Laboratory work reinforces analytical techniques with practical circuit construction.', N'Electrical Engineering', N'Engineering', 200, 3, N'PHY 212 and MTH 242'),
  ('Spring27', N'POL 412: Senior Seminar in Political Science', N'A capstone seminar requiring original research on a topic of the student''s choosing. Students develop a research question, conduct systematic analysis using appropriate methods, and produce a scholarly paper suitable for presentation at an academic conference.', N'Political Science', N'Arts & Sciences', 400, 3, N'POL 202 and senior standing'),
  ('Spring27', N'JOU 301: Digital Media Production', N'A practical course in creating content for digital platforms including podcasts, interactive graphics, social media, and web publications. Students learn content management systems, audience analytics, and SEO strategies.', N'Journalism', N'Communications', 300, 3, N'JOU 201'),
  ('Spring27', N'ACC 457: Advanced Accounting', N'A capstone course covering complex accounting topics including business combinations, consolidated financial statements, foreign currency transactions, government and nonprofit accounting, and partnership accounting.', N'Accounting', N'Business', 400, 3, N'ACC 212'),
  ('Spring27', N'PSY 223: Developmental Psychology', N'A lifespan approach to human development from conception through aging. Covers physical, cognitive, and psychosocial development with attention to cultural contexts, individual differences, and applications to parenting, education, and healthcare.', N'Psychology', N'Arts & Sciences', 200, 3, N'PSY 101'),
  ('Spring28', N'ENG 294: World Literature', N'A comparative study of literary traditions from Africa, Asia, Latin America, the Middle East, and Europe. Students read works in translation and explore themes of identity, migration, colonialism, and cultural exchange across global literary traditions.', N'English', N'Arts & Sciences', 200, 3, N'ENG 103');
INSERT INTO dbo.CourseCatalog (TermID, CourseTitle, CourseDescription, Department, College, CourseLevel, Credits, Prerequisites)
VALUES
  ('Fall26', N'SPE 275: Assessment in Special Education', N'A study of formal and informal assessment methods used to identify and serve students with disabilities. Topics include screening, eligibility determination, IEP development, progress monitoring, and the use of data to inform instructional decisions.', N'Special Education', N'Education', 200, 4, N'SPE 101'),
  ('Fall26', N'SCM 475: Senior Campaign Project', N'A capstone course in which student teams develop and present a comprehensive communications campaign for a real client. Includes situation analysis, strategy development, creative execution, media planning, budget, and evaluation plan.', N'Strategic Communications', N'Communications', 400, 3, N'Senior standing in SCM'),
  ('Fall26', N'MUS 255: Musicianship and Ear Training', N'An intensive course developing aural skills including sight-singing, melodic and harmonic dictation, rhythm reading, and score reading. Students build the perceptual skills essential for performance, composition, and analysis.', N'Music', N'Fine Arts', 200, 3, N'MUS 101'),
  ('Winter28', N'EXS 275: Kinesiology and Biomechanics', N'An analysis of human movement using principles of physics and anatomy. Topics include joint mechanics, muscle function, gait analysis, ergonomics, and injury mechanisms. Students conduct biomechanical analyses using video and motion capture technology.', N'Exercise Science', N'Health Sciences', 200, 4, N'BIO 101 and PHY 101'),
  ('Spring28', N'HIS 214: History of Science and Technology', N'An exploration of how scientific knowledge and technological innovation have shaped human societies. Topics include the Scientific Revolution, industrialization, the atomic age, the digital revolution, and ethical debates surrounding emerging technologies.', N'History', N'Arts & Sciences', 200, 4, NULL),
  ('Fall27', N'MKT 241: Marketing Research', N'An introduction to marketing research methods including survey design, focus groups, experimental research, and secondary data analysis. Students learn to use data analytics tools to derive actionable marketing insights from consumer and market data.', N'Marketing', N'Business', 200, 3, N'MKT 101 and MTH 110'),
  ('Fall26', N'HLA 308: Healthcare Quality and Patient Safety', N'A study of methods for improving healthcare quality and ensuring patient safety. Topics include quality measurement, performance improvement, root cause analysis, high reliability organizations, and evidence-based management practices.', N'Health Administration', N'Health Sciences', 300, 3, N'HLA 101'),
  ('Winter27', N'WLG 354: Hispanic Literature and Film', N'A study of major works of literature and film from Spain and Latin America in their cultural and historical contexts. Students develop advanced reading and analytical skills while exploring themes of identity, justice, memory, and artistic innovation.', N'World Languages', N'Arts & Sciences', 300, 3, N'WLG 202'),
  ('Winter27', N'EXS 122: Foundations of Health and Wellness', N'A survey of the dimensions of health and wellness including physical fitness, nutrition, stress management, mental health, substance use, and chronic disease prevention. Students develop a personal wellness plan based on evidence-based guidelines.', N'Exercise Science', N'Health Sciences', 100, 3, NULL),
  ('Spring27', N'PBH 371: Environmental Health', N'A study of environmental factors affecting human health. Topics include water quality, air pollution, toxic substances, food safety, occupational health, climate change, and environmental justice. Students conduct a community environmental health assessment.', N'Public Health', N'Health Sciences', 300, 3, N'PBH 201 and CHM 101'),
  ('Winter28', N'CIV 515: Graduate Seminar in Sustainable Infrastructure', N'An advanced seminar on designing infrastructure for resilience and sustainability. Topics include green building, climate-adaptive design, lifecycle assessment, smart cities, and infrastructure equity.', N'Civil Engineering', N'Engineering', 500, 3, N'Graduate standing'),
  ('Winter27', N'ACC 429: Forensic Accounting and Fraud Examination', N'A study of fraud detection, investigation, and prevention techniques. Topics include financial statement fraud, asset misappropriation, corruption, digital forensics, and expert witness testimony. Students analyze real fraud cases and develop investigative skills.', N'Accounting', N'Business', 400, 3, N'ACC 301'),
  ('Spring28', N'MGT 325: Leadership and Team Development', N'An experiential course in leadership theory and practice. Students assess their leadership styles, practice coaching and facilitation skills, and lead team projects. Covers transformational leadership, emotional intelligence, servant leadership, and leading change.', N'Management', N'Business', 300, 3, N'MGT 201'),
  ('Spring27', N'EED 252: Child Development and Learning', N'A study of how children develop cognitively, socially, and emotionally from birth through adolescence. Students explore major developmental theories and their implications for classroom instruction, assessment, and creating supportive learning environments.', N'Elementary Education', N'Education', 200, 4, N'EED 101'),
  ('Fall26', N'CTV 237: Screenwriting', N'A workshop course in writing for film and television. Students learn story structure, character development, dialogue, and visual storytelling through writing exercises, script analysis, and production of an original short screenplay.', N'Cinema & Television', N'Communications', 200, 4, N'CTV 101'),
  ('Fall26', N'ELE 461: Machine Learning for Engineers', N'An applied course in machine learning methods for engineering applications. Topics include neural networks, convolutional networks for image processing, recurrent networks for time series, and deploying models on edge devices.', N'Electrical Engineering', N'Engineering', 400, 3, N'ELE 203 and programming proficiency'),
  ('Summer27', N'SOC 347: Sociology of Education', N'An examination of educational institutions through sociological lenses. Topics include educational inequality, school segregation, cultural capital, hidden curriculum, standardized testing, and the role of education in social mobility and social reproduction.', N'Sociology', N'Arts & Sciences', 300, 3, N'SOC 201'),
  ('Fall26', N'EXS 238: Exercise Physiology', N'A study of the body''s physiological responses and adaptations to exercise. Topics include energy metabolism, cardiovascular and respiratory responses, neuromuscular adaptations, thermoregulation, and the physiological basis of training principles.', N'Exercise Science', N'Health Sciences', 200, 4, N'BIO 101 and EXS 101'),
  ('Spring28', N'CSC 454: Natural Language Processing', N'Advanced study of computational methods for analyzing and generating human language. Topics include tokenization, word embeddings, transformer architectures, sentiment analysis, and text classification. Students build NLP pipelines using modern frameworks and evaluate model performance on benchmark datasets.', N'Computer Science', N'Arts & Sciences', 400, 3, N'CSC 341 or CSC 345'),
  ('Spring28', N'EXS 347: Research Methods in Exercise Science', N'An introduction to research design and methods in exercise science. Topics include literature review, hypothesis formation, experimental and observational study designs, data collection, basic statistical analysis, and research ethics.', N'Exercise Science', N'Health Sciences', 300, 2, N'EXS 211 and MTH 110'),
  ('Fall26', N'PHY 105: General Physics I', N'An algebra-based introduction to mechanics, thermodynamics, and waves. Topics include kinematics, Newton''s laws, energy conservation, momentum, rotational motion, and oscillations. Laboratory experiments develop measurement and data analysis skills.', N'Physics', N'Arts & Sciences', 100, 3, NULL),
  ('Fall26', N'EED 583: Graduate Seminar in Curriculum Theory', N'An advanced seminar examining theories of curriculum design, implementation, and evaluation. Students explore perspectives including critical pedagogy, multicultural education, and standards-based reform while developing curriculum for diverse contexts.', N'Elementary Education', N'Education', 500, 3, N'Graduate standing'),
  ('Winter28', N'MKT 387: International Marketing', N'An examination of marketing strategy in global markets. Topics include market entry strategies, cross-cultural consumer behavior, global branding, pricing across markets, and distribution in emerging economies.', N'Marketing', N'Business', 300, 3, N'MKT 201'),
  ('Winter28', N'CPE 362: VLSI Design', N'An introduction to the design of very large scale integrated circuits. Topics include CMOS logic design, layout, verification, timing analysis, and low-power techniques. Students design and simulate circuits using industry CAD tools.', N'Computer Engineering', N'Engineering', 300, 4, N'ELE 202'),
  ('Spring28', N'EED 341: Classroom Management and Community Building', N'A practical course in creating positive, productive classroom environments. Students learn proactive management strategies, restorative practices, culturally responsive approaches, and techniques for building inclusive classroom communities.', N'Elementary Education', N'Education', 300, 3, N'EED 202'),
  ('Spring27', N'THR 136: Acting I', N'A foundational course in acting technique emphasizing relaxation, concentration, imagination, sensory work, and improvisation. Students develop skills in physical and vocal expression through exercises, scene work, and performance projects.', N'Theatre', N'Fine Arts', 100, 3, NULL),
  ('Spring27', N'CHM 251: Organic Chemistry I', N'A systematic study of carbon-based compounds covering nomenclature, stereochemistry, reaction mechanisms, and functional group transformations. Students develop skills in predicting reactivity based on molecular structure and electronic effects.', N'Chemistry', N'Arts & Sciences', 200, 4, N'CHM 102'),
  ('Summer28', N'ECN 272: Intermediate Microeconomics', N'An advanced treatment of microeconomic theory using mathematical tools. Topics include consumer optimization, firm behavior, market equilibrium, game theory, information economics, and welfare analysis. Students solve optimization problems and analyze market outcomes.', N'Economics', N'Business', 200, 3, N'ECN 101 and MTH 131'),
  ('Fall27', N'HLA 401: Healthcare Strategic Management', N'A capstone course in developing and implementing strategic plans for healthcare organizations. Students analyze competitive environments, assess organizational capabilities, develop strategic initiatives, and present recommendations to industry panels.', N'Health Administration', N'Health Sciences', 400, 3, N'Senior standing in HLA'),
  ('Fall26', N'FIN 194: Introduction to Business Finance', N'An overview of fundamental financial concepts including time value of money, risk and return, financial statement analysis, and capital markets. Provides a foundation for understanding how businesses raise and invest capital.', N'Finance', N'Business', 100, 3, NULL),
  ('Winter27', N'BIO 134: Human Biology', N'A survey of human biological systems for non-majors. Covers anatomy and physiology of major organ systems, nutrition, immunology, and genetics as they relate to human health and disease. Emphasizes critical evaluation of health claims in the media.', N'Biology', N'Arts & Sciences', 100, 4, NULL),
  ('Spring28', N'ACC 591: Graduate Seminar in Data Analytics for Accountants', N'An advanced course in applying data analytics to accounting and auditing problems. Students use Python, SQL, and visualization tools to detect anomalies, automate audit procedures, and extract insights from large financial datasets.', N'Accounting', N'Business', 500, 3, N'ACC 303 and graduate standing'),
  ('Fall26', N'WLG 129: Elementary Japanese I', N'An introduction to the Japanese language covering hiragana, katakana, and basic kanji. Students develop conversational skills, learn fundamental grammar patterns, and explore Japanese culture including customs, traditions, and daily life.', N'World Languages', N'Arts & Sciences', 100, 3, NULL),
  ('Fall26', N'PHL 503: Graduate Seminar in Applied Ethics', N'An advanced seminar examining contemporary ethical issues through philosophical analysis. Topics rotate and may include bioethics, technology ethics, business ethics, or environmental justice. Students write a publishable-quality research paper.', N'Philosophy', N'Arts & Sciences', 500, 3, N'Graduate standing'),
  ('Spring28', N'CSC 396: Machine Learning Fundamentals', N'An introduction to machine learning algorithms and their applications. Topics include supervised learning (regression, classification), unsupervised learning (clustering, dimensionality reduction), neural network basics, and model evaluation techniques. Students implement algorithms from scratch and using scikit-learn on real-world datasets.', N'Computer Science', N'Arts & Sciences', 300, 3, N'CSC 231 and MTH 241'),
  ('Fall26', N'CSC 369: Software Engineering', N'A project-based course in software development methodologies. Students work in teams using Agile practices to design, implement, test, and deploy a complete software application. Covers requirements gathering, version control with Git, continuous integration, and technical documentation.', N'Computer Science', N'Arts & Sciences', 300, 3, N'CSC 232'),
  ('Summer27', N'CHM 559: Graduate Research in Chemistry', N'Supervised research in an active faculty research lab. Students conduct original research, participate in group meetings, and present progress reports. Culminates in a thesis or publishable manuscript.', N'Chemistry', N'Arts & Sciences', 500, 3, N'Graduate standing'),
  ('Summer27', N'CPE 531: Graduate Seminar in Hardware Security', N'An advanced seminar on security vulnerabilities and defenses in hardware systems. Topics include side-channel attacks, hardware trojans, secure boot, trusted execution environments, and supply chain security.', N'Computer Engineering', N'Engineering', 500, 3, N'Graduate standing'),
  ('Spring28', N'ARH 185: Art History Survey I', N'A survey of art and architecture from prehistoric times through the medieval period. Students examine works from diverse cultures including Egyptian, Greek, Roman, Byzantine, and Islamic traditions while developing visual analysis skills.', N'Art History', N'Fine Arts', 100, 3, NULL),
  ('Fall26', N'SCM 377: Social Media Strategy', N'An advanced course in developing and executing social media strategies for organizations. Topics include platform selection, content planning, community management, influencer partnerships, paid social advertising, and social media analytics.', N'Strategic Communications', N'Communications', 300, 3, N'SCM 201'),
  ('Summer27', N'BAN 472: Machine Learning for Business', N'An advanced course applying machine learning techniques to business problems. Topics include feature engineering, ensemble methods, gradient boosting, recommendation systems, and model interpretability. Students implement solutions using Python and cloud-based ML platforms.', N'Business Analytics', N'Business', 400, 3, N'BAN 301'),
  ('Fall26', N'BIO 325: Neuroscience', N'An interdisciplinary exploration of the nervous system from molecular to behavioral levels. Topics include neuronal signaling, synaptic transmission, sensory systems, motor control, learning and memory, and neurological disorders. Bridges biology and psychology perspectives.', N'Biology', N'Arts & Sciences', 300, 3, N'BIO 211 or PSY 201'),
  ('Fall27', N'PBH 357: Global Health', N'An examination of health challenges in a global context. Topics include infectious disease control, maternal and child health, nutrition, health systems strengthening, global health governance, and the social determinants of health across nations.', N'Public Health', N'Health Sciences', 300, 3, N'PBH 201'),
  ('Summer27', N'NUR 197: Human Anatomy and Physiology for Nurses', N'A comprehensive study of human body structure and function organized by organ system. Integrates anatomical knowledge with clinical relevance. Laboratory work includes models, dissection, and physiological measurements.', N'Nursing', N'Health Sciences', 100, 3, NULL),
  ('Fall26', N'CHM 284: Organic Chemistry I', N'A systematic study of carbon-based compounds covering nomenclature, stereochemistry, reaction mechanisms, and functional group transformations. Students develop skills in predicting reactivity based on molecular structure and electronic effects.', N'Chemistry', N'Arts & Sciences', 200, 4, N'CHM 102'),
  ('Winter27', N'JOU 158: Introduction to Journalism', N'An introduction to the principles and practices of journalism in a multimedia environment. Students learn news gathering, interviewing, writing, and editing across print, broadcast, and digital platforms. Explores press freedom, media ethics, and the role of journalism in democracy.', N'Journalism', N'Communications', 100, 3, NULL),
  ('Fall26', N'ECN 266: Intermediate Macroeconomics', N'An advanced treatment of macroeconomic theory and policy. Topics include national income accounting, IS-LM model, aggregate supply and demand, economic growth models, monetary and fiscal policy analysis, and open economy macroeconomics.', N'Economics', N'Business', 200, 3, N'ECN 102 and MTH 131'),
  ('Spring27', N'HLA 528: Graduate Seminar in Population Health Management', N'An advanced seminar in managing the health of defined populations. Topics include risk stratification, care coordination, social determinants, value-based payment models, and data analytics for population health improvement.', N'Health Administration', N'Health Sciences', 500, 3, N'Graduate standing'),
  ('Spring28', N'BIO 117: General Biology II', N'Continuation of General Biology I focusing on organismal biology, ecology, and evolution. Topics include biodiversity, population genetics, ecosystem dynamics, and phylogenetics. Laboratory work includes field ecology and comparative anatomy.', N'Biology', N'Arts & Sciences', 100, 3, N'BIO 101'),
  ('Winter28', N'CHM 129: Chemistry in Everyday Life', N'A survey course exploring how chemistry impacts daily life. Topics include food chemistry, pharmaceuticals, environmental chemistry, materials science, and energy. Designed for non-science majors to develop scientific literacy.', N'Chemistry', N'Arts & Sciences', 100, 4, NULL);
INSERT INTO dbo.CourseCatalog (TermID, CourseTitle, CourseDescription, Department, College, CourseLevel, Credits, Prerequisites)
VALUES
  ('Fall27', N'MTH 452: Mathematical Modeling', N'Students develop and analyze mathematical models of real-world phenomena from biology, economics, physics, and engineering. Techniques include differential equations, optimization, simulation, and dimensional analysis. Team projects involve formulating problems, building models, and validating results against data.', N'Mathematics', N'Arts & Sciences', 400, 3, N'MTH 302 or MTH 341'),
  ('Spring28', N'ECN 561: Graduate Seminar in Applied Econometrics', N'An advanced course in econometric methods for causal inference. Topics include panel data models, differences-in-differences, regression discontinuity, synthetic controls, and machine learning methods for prediction in economic contexts.', N'Economics', N'Business', 500, 3, N'Graduate standing'),
  ('Spring27', N'WLG 399: Translation Theory and Practice', N'An introduction to the theory and practice of translation between English and Spanish. Students translate a variety of text types including literary, journalistic, technical, and legal documents while exploring the cultural and linguistic challenges of translation.', N'World Languages', N'Arts & Sciences', 300, 3, N'WLG 202'),
  ('Summer27', N'POL 116: Introduction to American Government', N'An overview of the American political system including the Constitution, federalism, civil liberties, political parties, elections, Congress, the presidency, and the judiciary. Students analyze current political events using foundational concepts in political science.', N'Political Science', N'Arts & Sciences', 100, 3, NULL),
  ('Fall26', N'ELE 444: Senior Design in Electrical Engineering', N'A capstone project in which student teams design and build an electrical or computer engineering system. Projects address real-world problems and include requirements specification, prototyping, testing, and documentation.', N'Electrical Engineering', N'Engineering', 400, 3, N'Senior standing in ELE'),
  ('Fall27', N'BAN 541: Graduate Seminar in Big Data Analytics', N'An advanced seminar in large-scale data processing and analytics. Topics include distributed computing frameworks, real-time stream processing, graph analytics, and building scalable machine learning pipelines. Students work with Spark, Kafka, and cloud data platforms.', N'Business Analytics', N'Business', 500, 3, N'Graduate standing'),
  ('Winter28', N'ENG 356: Literary Theory and Criticism', N'An introduction to major schools of literary criticism including formalism, structuralism, poststructuralism, feminism, postcolonialism, and cultural studies. Students apply theoretical frameworks to literary texts and develop skills in critical argumentation.', N'English', N'Arts & Sciences', 300, 3, N'Two 200-level ENG courses'),
  ('Fall26', N'CSC 262: Data Structures and Algorithms', N'A study of fundamental data structures including arrays, linked lists, stacks, queues, trees, and graphs. Students analyze algorithm efficiency using Big-O notation and implement sorting and searching algorithms. Prerequisite concepts from introductory programming are extended to handle complex data organization challenges.', N'Computer Science', N'Arts & Sciences', 200, 3, N'CSC 131 or equivalent programming experience'),
  ('Summer28', N'PSY 119: Psychology of Adjustment', N'An exploration of how individuals cope with life challenges including stress, relationships, career decisions, and mental health. Students apply psychological research to understand personal growth and develop evidence-based strategies for well-being.', N'Psychology', N'Arts & Sciences', 100, 3, NULL),
  ('Summer27', N'POL 226: Comparative Politics', N'A comparative study of political systems across democratic and authoritarian regimes. Topics include regime types, electoral systems, political parties, civil society, economic development, and democratization. Case studies draw from Europe, Latin America, Africa, and Asia.', N'Political Science', N'Arts & Sciences', 200, 3, N'POL 101 or POL 102'),
  ('Winter28', N'ACC 192: Principles of Managerial Accounting', N'An introduction to accounting for internal decision-making. Topics include cost behavior analysis, budgeting, variance analysis, capital budgeting, and performance evaluation. Students learn to use accounting information for planning, controlling, and evaluating business operations.', N'Accounting', N'Business', 100, 3, N'ACC 101'),
  ('Winter28', N'MTH 302: Abstract Algebra', N'An introduction to algebraic structures including groups, rings, and fields. Students study concepts of homomorphism, isomorphism, and quotient structures while developing skills in abstract mathematical reasoning and proof construction.', N'Mathematics', N'Arts & Sciences', 300, 3, N'MTH 244'),
  ('Spring27', N'WLG 198: Elementary Spanish I', N'An introduction to the Spanish language emphasizing communication skills in listening, speaking, reading, and writing. Students learn basic vocabulary, grammar, and pronunciation while exploring diverse Spanish-speaking cultures through authentic materials.', N'World Languages', N'Arts & Sciences', 100, 3, NULL),
  ('Winter28', N'BAN 216: Data Management for Business', N'A practical course in managing and querying business data. Students learn relational database concepts, SQL query writing, data cleaning and transformation techniques, and basic data warehousing principles. Applications focus on marketing, finance, and operations datasets.', N'Business Analytics', N'Business', 200, 3, N'BAN 101'),
  ('Winter28', N'JOU 198: Introduction to Journalism', N'An introduction to the principles and practices of journalism in a multimedia environment. Students learn news gathering, interviewing, writing, and editing across print, broadcast, and digital platforms. Explores press freedom, media ethics, and the role of journalism in democracy.', N'Journalism', N'Communications', 100, 3, NULL),
  ('Spring27', N'MEC 337: Fluid Mechanics', N'A study of fluid behavior and its engineering applications. Topics include fluid statics, conservation laws, Bernoulli equation, viscous flow, pipe systems, boundary layers, and an introduction to computational fluid dynamics.', N'Mechanical Engineering', N'Engineering', 300, 4, N'MEC 201 and MTH 302'),
  ('Winter27', N'NUR 233: Health Assessment', N'A course in the systematic collection of patient health data through interviewing, history-taking, and physical examination techniques. Students practice assessment skills in laboratory settings and learn to document findings using standardized frameworks.', N'Nursing', N'Health Sciences', 200, 2, N'NUR 102'),
  ('Fall26', N'SOC 177: Social Problems', N'An examination of major social problems including poverty, crime, substance abuse, healthcare access, environmental degradation, and educational inequality. Students analyze the structural causes of social problems and evaluate proposed solutions using sociological frameworks.', N'Sociology', N'Arts & Sciences', 100, 3, NULL),
  ('Fall27', N'ENG 239: World Literature', N'A comparative study of literary traditions from Africa, Asia, Latin America, the Middle East, and Europe. Students read works in translation and explore themes of identity, migration, colonialism, and cultural exchange across global literary traditions.', N'English', N'Arts & Sciences', 200, 3, N'ENG 103'),
  ('Fall26', N'ELE 507: Graduate Seminar in IoT and Edge Computing', N'An advanced seminar on Internet of Things architectures and edge computing. Topics include sensor networks, low-power design, edge AI, security in IoT systems, and applications in smart infrastructure.', N'Electrical Engineering', N'Engineering', 500, 3, N'Graduate standing'),
  ('Fall26', N'CSC 357: Computer Networks', N'A study of network architectures, protocols, and communication fundamentals. Topics include the OSI model, TCP/IP, routing algorithms, network security basics, and socket programming. Students build simple client-server applications and analyze network traffic.', N'Computer Science', N'Arts & Sciences', 300, 3, N'CSC 231'),
  ('Winter28', N'CIV 365: Transportation Engineering', N'A study of the planning, design, and operation of transportation systems. Topics include highway geometric design, traffic flow theory, intersection design, pavement materials, and sustainable transportation planning.', N'Civil Engineering', N'Engineering', 300, 3, N'CIV 101 and MTH 242'),
  ('Fall26', N'CHM 553: Graduate Research in Chemistry', N'Supervised research in an active faculty research lab. Students conduct original research, participate in group meetings, and present progress reports. Culminates in a thesis or publishable manuscript.', N'Chemistry', N'Arts & Sciences', 500, 4, N'Graduate standing'),
  ('Winter28', N'PBH 252: Epidemiology', N'A study of disease distribution and determinants in populations. Topics include study designs, measures of disease frequency and association, outbreak investigation, screening, and the application of epidemiological methods to public health practice.', N'Public Health', N'Health Sciences', 200, 3, N'PBH 101 and MTH 110'),
  ('Winter27', N'JOU 297: Broadcast Journalism', N'An introduction to television and radio journalism. Students learn to write broadcast scripts, operate cameras and editing equipment, conduct on-camera interviews, and produce news packages for air. Covers live reporting and breaking news situations.', N'Journalism', N'Communications', 200, 3, N'JOU 101'),
  ('Spring27', N'MEC 246: Engineering Materials', N'An introduction to the structure, properties, and processing of engineering materials including metals, ceramics, polymers, and composites. Students learn how material selection affects design, manufacturing, and performance of engineering systems.', N'Mechanical Engineering', N'Engineering', 200, 3, N'CHM 101 and PHY 211'),
  ('Winter27', N'POL 382: Constitutional Law', N'An in-depth study of U.S. constitutional interpretation focusing on landmark Supreme Court decisions. Topics include judicial review, separation of powers, federalism, equal protection, due process, and First Amendment freedoms.', N'Political Science', N'Arts & Sciences', 300, 3, N'POL 101'),
  ('Winter27', N'MEC 356: Heat Transfer', N'A study of heat transfer by conduction, convection, and radiation. Topics include steady and transient conduction, forced and natural convection, heat exchangers, and thermal radiation. Applications include HVAC, electronics cooling, and energy systems.', N'Mechanical Engineering', N'Engineering', 300, 4, N'MEC 202 and MEC 311'),
  ('Fall27', N'ARH 124: Art History Survey I', N'A survey of art and architecture from prehistoric times through the medieval period. Students examine works from diverse cultures including Egyptian, Greek, Roman, Byzantine, and Islamic traditions while developing visual analysis skills.', N'Art History', N'Fine Arts', 100, 4, NULL),
  ('Winter27', N'CHM 223: Analytical Chemistry', N'A study of quantitative and qualitative analytical methods including gravimetry, titrimetry, spectrophotometry, chromatography, and electroanalytical techniques. Emphasizes method validation, error analysis, and quality assurance in chemical measurements.', N'Chemistry', N'Arts & Sciences', 200, 3, N'CHM 102'),
  ('Summer28', N'HLA 278: Healthcare Finance', N'A study of financial management in healthcare organizations. Topics include healthcare accounting, budgeting, reimbursement systems, cost analysis, capital planning, and financial decision-making in hospitals and health systems.', N'Health Administration', N'Health Sciences', 200, 3, N'HLA 101 and ACC 101'),
  ('Summer27', N'CIV 296: Mechanics of Materials', N'A study of the behavior of solid materials under various loading conditions. Topics include stress, strain, beam deflection, torsion, column buckling, and material failure theories. Applications to structural engineering design.', N'Civil Engineering', N'Engineering', 200, 4, N'MEC 201'),
  ('Spring27', N'PBH 378: Environmental Health', N'A study of environmental factors affecting human health. Topics include water quality, air pollution, toxic substances, food safety, occupational health, climate change, and environmental justice. Students conduct a community environmental health assessment.', N'Public Health', N'Health Sciences', 300, 3, N'PBH 201 and CHM 101'),
  ('Spring28', N'PBH 591: Graduate Seminar in Health Equity', N'An advanced seminar examining the root causes of health disparities and strategies for achieving health equity. Topics include structural racism, social determinants of health, community-based participatory research, and policy interventions.', N'Public Health', N'Health Sciences', 500, 3, N'Graduate standing'),
  ('Spring27', N'MGT 171: Introduction to Management', N'An overview of management theory and practice covering planning, organizing, leading, and controlling functions. Students explore classical and contemporary management approaches, ethical leadership, and the changing nature of work in a globalized economy.', N'Management', N'Business', 100, 3, NULL),
  ('Spring27', N'MTH 419: Real Analysis', N'An advanced course in the rigorous foundations of calculus. Topics include the completeness of the real numbers, sequences and series of functions, metric spaces, continuity, differentiability, and Riemann integration. Emphasizes epsilon-delta proofs and mathematical rigor.', N'Mathematics', N'Arts & Sciences', 400, 3, N'MTH 341'),
  ('Fall27', N'MKT 308: Brand Management', N'A study of how brands are created, positioned, and managed over time. Topics include brand equity measurement, brand architecture, brand extensions, brand revitalization, and global branding strategies. Students develop a comprehensive brand strategy.', N'Marketing', N'Business', 300, 3, N'MKT 201'),
  ('Winter27', N'CIV 398: Geotechnical Engineering', N'A study of soil mechanics and foundation engineering. Topics include soil classification, effective stress, seepage, consolidation, shear strength, bearing capacity, and slope stability analysis.', N'Civil Engineering', N'Engineering', 300, 4, N'CIV 201 and geology course'),
  ('Fall26', N'SPE 316: Inclusive Instructional Strategies', N'An advanced methods course in adapting instruction for students with diverse learning needs. Topics include universal design for learning, differentiated instruction, assistive technology, co-teaching models, and evidence-based practices for students with specific disabilities.', N'Special Education', N'Education', 300, 3, N'SPE 201 and EED 202'),
  ('Fall27', N'ART 204: Photography I', N'An introduction to photography as an art form. Students learn camera operations, digital workflow, composition, lighting, and post-processing techniques while developing a personal artistic vision through photo-based projects.', N'Studio Art', N'Fine Arts', 200, 3, NULL),
  ('Spring27', N'ART 183: Foundations of Design', N'An introduction to the principles and elements of visual design including line, shape, color, texture, balance, rhythm, and hierarchy. Students complete projects exploring two-dimensional and three-dimensional design concepts.', N'Studio Art', N'Fine Arts', 100, 3, NULL),
  ('Spring27', N'MGT 366: Project Management', N'A practical course in planning, executing, and controlling projects. Topics include scope management, scheduling, budgeting, risk management, team leadership, and Agile methodologies. Students use project management software to plan and track a real project.', N'Management', N'Business', 300, 3, N'MGT 201'),
  ('Spring28', N'MUS 352: Composition', N'A creative course in composing music for various ensembles and instruments. Students develop compositional techniques including melody, harmony, counterpoint, orchestration, and formal design while finding their personal artistic voice.', N'Music', N'Fine Arts', 300, 3, N'MUS 201'),
  ('Fall27', N'ACC 565: Graduate Seminar in Data Analytics for Accountants', N'An advanced course in applying data analytics to accounting and auditing problems. Students use Python, SQL, and visualization tools to detect anomalies, automate audit procedures, and extract insights from large financial datasets.', N'Accounting', N'Business', 500, 3, N'ACC 303 and graduate standing'),
  ('Fall27', N'SOC 193: Introduction to Sociology', N'An introduction to sociological perspectives on human society. Topics include social structure, culture, socialization, inequality, race and ethnicity, gender, deviance, and institutions. Students develop the ability to see personal experiences within broader social patterns.', N'Sociology', N'Arts & Sciences', 100, 3, NULL),
  ('Fall27', N'FIN 155: Introduction to Business Finance', N'An overview of fundamental financial concepts including time value of money, risk and return, financial statement analysis, and capital markets. Provides a foundation for understanding how businesses raise and invest capital.', N'Finance', N'Business', 100, 3, NULL),
  ('Spring27', N'HLA 292: Healthcare Finance', N'A study of financial management in healthcare organizations. Topics include healthcare accounting, budgeting, reimbursement systems, cost analysis, capital planning, and financial decision-making in hospitals and health systems.', N'Health Administration', N'Health Sciences', 200, 3, N'HLA 101 and ACC 101'),
  ('Fall27', N'ACC 153: Principles of Financial Accounting', N'An introduction to the fundamental concepts and practices of financial accounting. Topics include the accounting cycle, financial statement preparation, revenue recognition, asset valuation, and analysis of financial reports. Students develop skills in recording and interpreting business transactions.', N'Accounting', N'Business', 100, 3, NULL),
  ('Summer28', N'MUS 182: Applied Music: Beginning Piano', N'Individual or small-group piano instruction for beginning students. Covers music reading, technique, scales, chords, and repertoire from classical and popular traditions. Develops both performance skills and musical understanding.', N'Music', N'Fine Arts', 100, 3, NULL),
  ('Fall27', N'EXS 306: Clinical Exercise Physiology', N'A study of exercise prescription for individuals with chronic diseases and special conditions including cardiovascular disease, diabetes, obesity, pulmonary disease, and musculoskeletal disorders. Prepares students for clinical exercise testing certification.', N'Exercise Science', N'Health Sciences', 300, 3, N'EXS 211');
INSERT INTO dbo.CourseCatalog (TermID, CourseTitle, CourseDescription, Department, College, CourseLevel, Credits, Prerequisites)
VALUES
  ('Winter27', N'ACC 174: Principles of Financial Accounting', N'An introduction to the fundamental concepts and practices of financial accounting. Topics include the accounting cycle, financial statement preparation, revenue recognition, asset valuation, and analysis of financial reports. Students develop skills in recording and interpreting business transactions.', N'Accounting', N'Business', 100, 3, NULL),
  ('Fall26', N'POL 342: Political Psychology', N'An exploration of psychological factors in political behavior including public opinion formation, voting behavior, political socialization, propaganda, conspiracy thinking, and the psychology of leadership. Integrates psychological research with political analysis.', N'Political Science', N'Arts & Sciences', 300, 4, N'POL 101 and PSY 101'),
  ('Fall27', N'SPE 593: Graduate Seminar in Learning Disabilities', N'An advanced seminar examining current research on learning disabilities. Topics include neurological bases, evidence-based interventions, response to intervention, and the intersection of learning disabilities with cultural and linguistic diversity.', N'Special Education', N'Education', 500, 3, N'Graduate standing'),
  ('Fall26', N'NUR 193: Human Anatomy and Physiology for Nurses', N'A comprehensive study of human body structure and function organized by organ system. Integrates anatomical knowledge with clinical relevance. Laboratory work includes models, dissection, and physiological measurements.', N'Nursing', N'Health Sciences', 100, 3, NULL),
  ('Spring27', N'ART 338: Art and Social Practice', N'An exploration of art as a tool for community engagement and social change. Students develop collaborative projects addressing social issues, working with communities to create participatory artworks that challenge traditional gallery-based models.', N'Studio Art', N'Fine Arts', 300, 3, N'One 200-level ART course'),
  ('Winter28', N'NUR 474: Leadership and Management in Nursing', N'A course in nursing leadership including healthcare systems, quality improvement, patient safety, team management, ethical decision-making, and healthcare policy advocacy. Prepares students for professional leadership roles.', N'Nursing', N'Health Sciences', 400, 3, N'Senior standing in NUR'),
  ('Spring27', N'MEC 474: Senior Design Project', N'A two-semester capstone experience in which student teams design, build, and test a mechanical system or device. Teams work with industry sponsors, manage budgets and schedules, and present their work at the engineering design showcase.', N'Mechanical Engineering', N'Engineering', 400, 3, N'Senior standing in MEC'),
  ('Fall27', N'MGT 378: Operations Management', N'A study of how organizations design, operate, and improve production systems. Topics include process analysis, quality management, inventory control, supply chain management, lean operations, and capacity planning. Students apply analytical tools to real operational challenges.', N'Management', N'Business', 300, 3, N'MGT 101 and MTH 110'),
  ('Fall27', N'WLG 263: Language and Culture', N'An interdisciplinary exploration of the relationship between language, thought, and culture. Topics include linguistic relativity, bilingualism, language and identity, translation, and the cultural dimensions of communication. Taught in English; no language prerequisite.', N'World Languages', N'Arts & Sciences', 200, 3, NULL),
  ('Fall26', N'HIS 341: Historical Research Methods', N'A hands-on course in the methods and practices of historical research. Students learn to locate and evaluate primary sources, construct historical arguments, navigate archives, and write research papers that meet professional standards in the discipline.', N'History', N'Arts & Sciences', 300, 3, N'Two 200-level HIS courses'),
  ('Spring27', N'EXS 219: Nutrition for Sport and Health', N'A study of nutritional principles as they apply to physical performance and health. Topics include macronutrient and micronutrient requirements, hydration, supplementation, body composition assessment, and nutrition strategies for athletes and active individuals.', N'Exercise Science', N'Health Sciences', 200, 3, N'BIO 101 or EXS 101'),
  ('Fall26', N'PHY 225: University Physics II', N'A calculus-based treatment of electromagnetism including electric fields, Gauss''s law, capacitance, DC circuits, magnetic fields, Faraday''s law, and electromagnetic waves. Laboratory emphasizes precision measurement and circuit analysis.', N'Physics', N'Arts & Sciences', 200, 4, N'PHY 211 and MTH 242'),
  ('Fall26', N'SCM 162: Introduction to Strategic Communications', N'An overview of the strategic communications field including public relations, advertising, and integrated marketing communications. Students learn campaign planning, message development, media relations, and the role of communication in organizational strategy.', N'Strategic Communications', N'Communications', 100, 4, NULL),
  ('Spring28', N'POL 307: Constitutional Law', N'An in-depth study of U.S. constitutional interpretation focusing on landmark Supreme Court decisions. Topics include judicial review, separation of powers, federalism, equal protection, due process, and First Amendment freedoms.', N'Political Science', N'Arts & Sciences', 300, 3, N'POL 101'),
  ('Spring27', N'MTH 362: Differential Equations', N'A study of ordinary differential equations and their applications. Topics include first-order equations, linear systems, Laplace transforms, numerical methods, and modeling of physical and biological systems. Emphasizes both analytical solutions and qualitative behavior analysis.', N'Mathematics', N'Arts & Sciences', 300, 3, N'MTH 242'),
  ('Fall26', N'MGT 516: Graduate Seminar in Organizational Leadership', N'An advanced seminar exploring contemporary challenges in organizational leadership. Topics include leading distributed teams, managing organizational change, innovation management, and ethical leadership in complex organizations.', N'Management', N'Business', 500, 3, N'Graduate standing'),
  ('Spring27', N'PSY 273: Developmental Psychology', N'A lifespan approach to human development from conception through aging. Covers physical, cognitive, and psychosocial development with attention to cultural contexts, individual differences, and applications to parenting, education, and healthcare.', N'Psychology', N'Arts & Sciences', 200, 3, N'PSY 101'),
  ('Fall27', N'ART 111: Foundations of Drawing', N'A foundational course developing observational drawing skills. Students work with a variety of media including graphite, charcoal, ink, and mixed media while exploring line, value, form, composition, and perspective through still life, figure, and landscape subjects.', N'Studio Art', N'Fine Arts', 100, 3, NULL),
  ('Fall26', N'SOC 299: Research Methods in Sociology', N'An introduction to qualitative and quantitative research methods in sociology. Topics include survey design, interviewing, ethnography, content analysis, and statistical techniques. Students design and execute a small-scale research project.', N'Sociology', N'Arts & Sciences', 200, 3, N'SOC 101'),
  ('Spring27', N'BAN 342: Text Analytics and NLP for Business', N'An applied course in extracting insights from unstructured text data. Topics include text preprocessing, sentiment analysis, topic modeling, named entity recognition, and building text classification systems. Applications include customer review analysis, social media monitoring, and document categorization.', N'Business Analytics', N'Business', 300, 3, N'BAN 301 and programming experience'),
  ('Fall27', N'MTH 298: Discrete Mathematics', N'An introduction to mathematical structures and reasoning fundamental to computer science. Topics include logic, set theory, combinatorics, graph theory, recursive definitions, and proof techniques. Students develop skills in abstract reasoning and formal argumentation.', N'Mathematics', N'Arts & Sciences', 200, 3, N'MTH 131 or CSC 131'),
  ('Spring28', N'MTH 579: Graduate Seminar in Applied Mathematics', N'An advanced seminar exploring current research topics in applied mathematics. Students read recent publications, present findings, and develop original research questions. Topics rotate and may include mathematical biology, computational fluid dynamics, or network analysis.', N'Mathematics', N'Arts & Sciences', 500, 3, N'Graduate standing in MTH'),
  ('Fall27', N'CSC 325: Software Engineering', N'A project-based course in software development methodologies. Students work in teams using Agile practices to design, implement, test, and deploy a complete software application. Covers requirements gathering, version control with Git, continuous integration, and technical documentation.', N'Computer Science', N'Arts & Sciences', 300, 3, N'CSC 232'),
  ('Fall27', N'BAN 537: Graduate Seminar in Big Data Analytics', N'An advanced seminar in large-scale data processing and analytics. Topics include distributed computing frameworks, real-time stream processing, graph analytics, and building scalable machine learning pipelines. Students work with Spark, Kafka, and cloud data platforms.', N'Business Analytics', N'Business', 500, 3, N'Graduate standing'),
  ('Fall27', N'ENG 552: Graduate Seminar in Rhetoric and Composition', N'An advanced seminar examining theories of writing, rhetoric, and literacy. Students explore how writing functions in academic, professional, and public contexts while developing skills in qualitative research methods applicable to writing studies.', N'English', N'Arts & Sciences', 500, 3, N'Graduate standing'),
  ('Fall27', N'MEC 389: Fluid Mechanics', N'A study of fluid behavior and its engineering applications. Topics include fluid statics, conservation laws, Bernoulli equation, viscous flow, pipe systems, boundary layers, and an introduction to computational fluid dynamics.', N'Mechanical Engineering', N'Engineering', 300, 4, N'MEC 201 and MTH 302'),
  ('Summer27', N'CSC 366: Operating Systems', N'An examination of operating system design principles including process management, memory allocation, file systems, and concurrency. Students explore scheduling algorithms, virtual memory, deadlock prevention, and implement system-level programs that interact with OS services.', N'Computer Science', N'Arts & Sciences', 300, 3, N'CSC 231'),
  ('Spring27', N'SOC 116: Introduction to Sociology', N'An introduction to sociological perspectives on human society. Topics include social structure, culture, socialization, inequality, race and ethnicity, gender, deviance, and institutions. Students develop the ability to see personal experiences within broader social patterns.', N'Sociology', N'Arts & Sciences', 100, 3, NULL),
  ('Fall27', N'PHL 296: Political Philosophy', N'An examination of theories of justice, liberty, equality, and political obligation. Students read foundational texts from Plato, Locke, Mill, Marx, and Rawls alongside contemporary debates about democracy, multiculturalism, and global justice.', N'Philosophy', N'Arts & Sciences', 200, 3, N'PHL 101'),
  ('Fall27', N'PHY 428: Electrodynamics', N'An advanced study of electromagnetic theory based on Maxwell''s equations. Topics include boundary value problems, electromagnetic waves, radiation, and special relativity. Students develop skills in vector calculus and mathematical physics.', N'Physics', N'Arts & Sciences', 400, 2, N'PHY 312 and MTH 302'),
  ('Winter27', N'THR 322: Directing', N'A study of the art and practice of theatrical direction. Topics include script analysis, concept development, staging, working with actors, and production management. Students direct scenes and one-act plays for public performance.', N'Theatre', N'Fine Arts', 300, 3, N'THR 102 and THR 211'),
  ('Summer27', N'ART 244: Printmaking', N'An introduction to printmaking techniques including relief, intaglio, screen printing, and monotype. Students explore the unique aesthetic possibilities of each process while developing technical skills and artistic concepts.', N'Studio Art', N'Fine Arts', 200, 3, N'ART 101'),
  ('Spring28', N'MTH 255: Calculus II', N'Continuation of Calculus I covering integration techniques, applications of the definite integral, sequences, series, and Taylor polynomials. Students develop skills in analytical problem-solving and mathematical reasoning that serve as a foundation for advanced mathematics and scientific applications.', N'Mathematics', N'Arts & Sciences', 200, 3, N'MTH 241'),
  ('Spring28', N'EDL 475: Educational Policy and Reform', N'An analysis of education policy at local, state, and federal levels. Students examine policy formation, implementation, and evaluation with attention to equity, accountability, school choice, and the politics of education reform.', N'Educational Leadership', N'Education', 400, 3, N'EDL 301'),
  ('Winter27', N'MTH 151: College Algebra', N'A foundational course covering algebraic concepts including linear and quadratic equations, polynomial functions, rational expressions, and systems of equations. Emphasizes analytical thinking and problem-solving techniques that prepare students for calculus and quantitative reasoning across disciplines.', N'Mathematics', N'Arts & Sciences', 100, 3, NULL),
  ('Fall26', N'HLA 257: Healthcare Finance', N'A study of financial management in healthcare organizations. Topics include healthcare accounting, budgeting, reimbursement systems, cost analysis, capital planning, and financial decision-making in hospitals and health systems.', N'Health Administration', N'Health Sciences', 200, 3, N'HLA 101 and ACC 101'),
  ('Spring28', N'ECN 266: Intermediate Macroeconomics', N'An advanced treatment of macroeconomic theory and policy. Topics include national income accounting, IS-LM model, aggregate supply and demand, economic growth models, monetary and fiscal policy analysis, and open economy macroeconomics.', N'Economics', N'Business', 200, 3, N'ECN 102 and MTH 131'),
  ('Winter28', N'ENG 559: Graduate Seminar in Rhetoric and Composition', N'An advanced seminar examining theories of writing, rhetoric, and literacy. Students explore how writing functions in academic, professional, and public contexts while developing skills in qualitative research methods applicable to writing studies.', N'English', N'Arts & Sciences', 500, 4, N'Graduate standing'),
  ('Winter28', N'SOC 317: Data Analysis for Social Science', N'A practical course in statistical analysis for sociological research. Students learn to use R and SPSS to manage data, conduct descriptive and inferential analyses, and create visualizations. Covers regression, ANOVA, and introduction to multilevel modeling.', N'Sociology', N'Arts & Sciences', 300, 3, N'SOC 201 and MTH 110'),
  ('Winter27', N'NUR 246: Pathophysiology', N'A study of the physiological changes associated with disease processes across the lifespan. Topics include cellular injury, inflammation, immune dysfunction, cardiovascular disease, endocrine disorders, and neurological conditions.', N'Nursing', N'Health Sciences', 200, 4, N'NUR 102'),
  ('Spring27', N'CHM 245: Analytical Chemistry', N'A study of quantitative and qualitative analytical methods including gravimetry, titrimetry, spectrophotometry, chromatography, and electroanalytical techniques. Emphasizes method validation, error analysis, and quality assurance in chemical measurements.', N'Chemistry', N'Arts & Sciences', 200, 3, N'CHM 102'),
  ('Spring27', N'JOU 476: Senior Capstone in Journalism', N'A culminating project in which students produce a substantial piece of original journalism — investigative report, documentary, multimedia project, or podcast series. Students pitch, research, produce, and present their work.', N'Journalism', N'Communications', 400, 3, N'Senior standing in JOU'),
  ('Spring28', N'JOU 457: Senior Capstone in Journalism', N'A culminating project in which students produce a substantial piece of original journalism — investigative report, documentary, multimedia project, or podcast series. Students pitch, research, produce, and present their work.', N'Journalism', N'Communications', 400, 2, N'Senior standing in JOU'),
  ('Spring28', N'WLG 102: Elementary French I', N'An introduction to the French language developing foundational skills in listening, speaking, reading, and writing. Students learn essential vocabulary and grammar while exploring Francophone cultures through films, music, and literature.', N'World Languages', N'Arts & Sciences', 100, 3, NULL),
  ('Spring27', N'MUS 121: Applied Music: Beginning Piano', N'Individual or small-group piano instruction for beginning students. Covers music reading, technique, scales, chords, and repertoire from classical and popular traditions. Develops both performance skills and musical understanding.', N'Music', N'Fine Arts', 100, 3, NULL),
  ('Winter28', N'PSY 271: Research Methods in Psychology', N'An introduction to the scientific methods used in psychological research. Topics include experimental design, survey methodology, observational techniques, ethical considerations, and basic statistical analysis using SPSS. Students design and conduct an original study.', N'Psychology', N'Arts & Sciences', 200, 3, N'PSY 101'),
  ('Winter27', N'PHY 256: Modern Physics', N'An introduction to twentieth-century physics including special relativity, quantum mechanics, atomic structure, nuclear physics, and particle physics. Students explore the experimental evidence and mathematical frameworks that revolutionized our understanding of nature.', N'Physics', N'Arts & Sciences', 200, 3, N'PHY 212 and MTH 242'),
  ('Fall26', N'MKT 328: Brand Management', N'A study of how brands are created, positioned, and managed over time. Topics include brand equity measurement, brand architecture, brand extensions, brand revitalization, and global branding strategies. Students develop a comprehensive brand strategy.', N'Marketing', N'Business', 300, 4, N'MKT 201'),
  ('Winter28', N'MGT 493: Senior Capstone in Management', N'A capstone course integrating management concepts through a comprehensive business simulation or consulting project. Students make strategic decisions under uncertainty, analyze performance outcomes, and present recommendations to stakeholders.', N'Management', N'Business', 400, 3, N'Senior standing in MGT'),
  ('Spring27', N'MEC 344: Heat Transfer', N'A study of heat transfer by conduction, convection, and radiation. Topics include steady and transient conduction, forced and natural convection, heat exchangers, and thermal radiation. Applications include HVAC, electronics cooling, and energy systems.', N'Mechanical Engineering', N'Engineering', 300, 3, N'MEC 202 and MEC 311');
INSERT INTO dbo.CourseCatalog (TermID, CourseTitle, CourseDescription, Department, College, CourseLevel, Credits, Prerequisites)
VALUES
  ('Winter28', N'CHM 579: Graduate Research in Chemistry', N'Supervised research in an active faculty research lab. Students conduct original research, participate in group meetings, and present progress reports. Culminates in a thesis or publishable manuscript.', N'Chemistry', N'Arts & Sciences', 500, 3, N'Graduate standing'),
  ('Fall26', N'MKT 348: International Marketing', N'An examination of marketing strategy in global markets. Topics include market entry strategies, cross-cultural consumer behavior, global branding, pricing across markets, and distribution in emerging economies.', N'Marketing', N'Business', 300, 4, N'MKT 201'),
  ('Spring27', N'POL 174: Introduction to International Relations', N'A survey of theories and issues in international relations including realism, liberalism, constructivism, security studies, international organizations, globalization, human rights, and environmental politics. Students analyze contemporary global challenges.', N'Political Science', N'Arts & Sciences', 100, 4, NULL),
  ('Spring28', N'PHY 273: University Physics I', N'A calculus-based treatment of classical mechanics including kinematics, dynamics, work-energy theorems, conservation laws, rigid body motion, and oscillations. Designed for physics and engineering majors.', N'Physics', N'Arts & Sciences', 200, 3, N'MTH 241 or concurrent enrollment'),
  ('Fall26', N'ART 256: Photography I', N'An introduction to photography as an art form. Students learn camera operations, digital workflow, composition, lighting, and post-processing techniques while developing a personal artistic vision through photo-based projects.', N'Studio Art', N'Fine Arts', 200, 3, NULL),
  ('Fall27', N'ART 243: Painting I', N'An introduction to painting techniques and concepts. Students work in oil and acrylic to develop skills in color mixing, composition, surface quality, and visual expression. Subjects include still life, landscape, and the figure.', N'Studio Art', N'Fine Arts', 200, 2, N'ART 101'),
  ('Winter28', N'ART 226: Sculpture I', N'An introduction to three-dimensional art-making using a variety of materials and processes including clay, wood, metal, and found objects. Students explore form, space, texture, and conceptual approaches to sculptural practice.', N'Studio Art', N'Fine Arts', 200, 3, N'ART 102'),
  ('Summer28', N'EDL 224: Foundations of Educational Leadership', N'An introduction to leadership theories and their application in educational settings. Students explore transformational, distributed, and servant leadership models while examining the roles and responsibilities of school administrators.', N'Educational Leadership', N'Education', 200, 3, N'EED 101 or SPE 101'),
  ('Spring27', N'EED 596: Graduate Seminar in Curriculum Theory', N'An advanced seminar examining theories of curriculum design, implementation, and evaluation. Students explore perspectives including critical pedagogy, multicultural education, and standards-based reform while developing curriculum for diverse contexts.', N'Elementary Education', N'Education', 500, 3, N'Graduate standing'),
  ('Fall27', N'CTV 292: Screenwriting', N'A workshop course in writing for film and television. Students learn story structure, character development, dialogue, and visual storytelling through writing exercises, script analysis, and production of an original short screenplay.', N'Cinema & Television', N'Communications', 200, 3, N'CTV 101'),
  ('Spring27', N'BIO 179: General Biology I', N'An introduction to cellular and molecular biology covering cell structure, metabolism, genetics, and molecular biology. Laboratory sessions reinforce lecture concepts through microscopy, gel electrophoresis, and experimental design. Intended for science majors.', N'Biology', N'Arts & Sciences', 100, 4, NULL),
  ('Spring28', N'ECN 513: Graduate Seminar in Applied Econometrics', N'An advanced course in econometric methods for causal inference. Topics include panel data models, differences-in-differences, regression discontinuity, synthetic controls, and machine learning methods for prediction in economic contexts.', N'Economics', N'Business', 500, 4, N'Graduate standing'),
  ('Summer27', N'ACC 286: Cost Accounting', N'A comprehensive study of cost accounting systems and techniques. Topics include job-order costing, process costing, activity-based costing, standard costing, and cost-volume-profit analysis. Students use accounting data to support management decision-making.', N'Accounting', N'Business', 200, 3, N'ACC 102'),
  ('Spring28', N'PHY 393: Quantum Mechanics', N'A rigorous treatment of quantum theory including the Schrodinger equation, angular momentum, spin, perturbation theory, and the hydrogen atom. Students develop mathematical and conceptual tools for understanding quantum phenomena in atoms, molecules, and solids.', N'Physics', N'Arts & Sciences', 300, 4, N'PHY 221 and MTH 302'),
  ('Spring28', N'PHY 302: Classical Mechanics', N'An advanced treatment of Newtonian mechanics using Lagrangian and Hamiltonian formalisms. Topics include central force motion, rigid body dynamics, coupled oscillations, and an introduction to chaos and nonlinear dynamics.', N'Physics', N'Arts & Sciences', 300, 3, N'PHY 211 and MTH 302'),
  ('Spring27', N'MEC 126: Introduction to Engineering', N'A broad introduction to engineering disciplines and the engineering design process. Students work in teams to solve open-ended design challenges using computer-aided design tools, prototyping, and iterative testing. Develops creative problem-solving and communication skills.', N'Mechanical Engineering', N'Engineering', 100, 3, NULL),
  ('Summer28', N'ART 285: Painting I', N'An introduction to painting techniques and concepts. Students work in oil and acrylic to develop skills in color mixing, composition, surface quality, and visual expression. Subjects include still life, landscape, and the figure.', N'Studio Art', N'Fine Arts', 200, 3, N'ART 101'),
  ('Fall27', N'BIO 385: Molecular Biology', N'Advanced study of gene structure, expression, and regulation at the molecular level. Topics include genome organization, epigenetics, RNA processing, protein folding, and CRISPR-based gene editing technologies. Students read and critique primary research literature.', N'Biology', N'Arts & Sciences', 300, 3, N'BIO 211 and CHM 201'),
  ('Spring27', N'PHY 282: Modern Physics', N'An introduction to twentieth-century physics including special relativity, quantum mechanics, atomic structure, nuclear physics, and particle physics. Students explore the experimental evidence and mathematical frameworks that revolutionized our understanding of nature.', N'Physics', N'Arts & Sciences', 200, 4, N'PHY 212 and MTH 242'),
  ('Fall27', N'SPE 393: Transition Planning and Life Skills', N'A course focused on preparing students with disabilities for post-secondary education, employment, and independent living. Topics include self-determination, vocational assessment, community-based instruction, and interagency collaboration.', N'Special Education', N'Education', 300, 3, N'SPE 201'),
  ('Winter28', N'ENG 296: Creative Writing: Fiction', N'A workshop-based course in short fiction writing. Students produce original stories, participate in peer critique sessions, and study published works as models for craft elements including characterization, plot structure, point of view, and dialogue.', N'English', N'Arts & Sciences', 200, 3, N'ENG 101'),
  ('Spring28', N'CIV 202: Mechanics of Materials', N'A study of the behavior of solid materials under various loading conditions. Topics include stress, strain, beam deflection, torsion, column buckling, and material failure theories. Applications to structural engineering design.', N'Civil Engineering', N'Engineering', 200, 3, N'MEC 201'),
  ('Winter28', N'MTH 244: Linear Algebra', N'A study of vector spaces, linear transformations, matrices, determinants, eigenvalues, and eigenvectors. Applications include systems of linear equations, least-squares approximation, and Markov chains. This course provides essential mathematical foundations for machine learning, data science, and engineering.', N'Mathematics', N'Arts & Sciences', 200, 4, N'MTH 241'),
  ('Fall27', N'CIV 308: Geotechnical Engineering', N'A study of soil mechanics and foundation engineering. Topics include soil classification, effective stress, seepage, consolidation, shear strength, bearing capacity, and slope stability analysis.', N'Civil Engineering', N'Engineering', 300, 3, N'CIV 201 and geology course'),
  ('Fall27', N'PBH 348: Environmental Health', N'A study of environmental factors affecting human health. Topics include water quality, air pollution, toxic substances, food safety, occupational health, climate change, and environmental justice. Students conduct a community environmental health assessment.', N'Public Health', N'Health Sciences', 300, 3, N'PBH 201 and CHM 101'),
  ('Winter28', N'PHL 348: Ethics of Artificial Intelligence', N'A philosophical examination of ethical issues raised by artificial intelligence and autonomous systems. Topics include algorithmic bias, accountability for AI decisions, privacy, the future of work, machine consciousness, and the alignment problem in advanced AI systems.', N'Philosophy', N'Arts & Sciences', 300, 3, N'PHL 102 or CSC 131'),
  ('Fall26', N'BIO 277: Ecology', N'An examination of the interactions between organisms and their environment. Topics include population dynamics, community structure, ecosystem energetics, biogeochemical cycles, and conservation biology. Field trips and laboratory work emphasize data collection and ecological analysis.', N'Biology', N'Arts & Sciences', 200, 4, N'BIO 102'),
  ('Spring27', N'EED 226: Curriculum and Instructional Design', N'An introduction to designing effective instruction for diverse learners. Students learn to develop lesson plans, align objectives with assessments, differentiate instruction, and integrate technology meaningfully into teaching practice.', N'Elementary Education', N'Education', 200, 3, N'EED 101'),
  ('Summer28', N'ART 357: Painting II: Advanced Concepts', N'A continuation of Painting I focusing on the development of a personal body of work. Students investigate contemporary painting practices, experiment with materials and scale, and engage in critical dialogue about their work.', N'Studio Art', N'Fine Arts', 300, 3, N'ART 211'),
  ('Fall27', N'PHY 316: Classical Mechanics', N'An advanced treatment of Newtonian mechanics using Lagrangian and Hamiltonian formalisms. Topics include central force motion, rigid body dynamics, coupled oscillations, and an introduction to chaos and nonlinear dynamics.', N'Physics', N'Arts & Sciences', 300, 3, N'PHY 211 and MTH 302'),
  ('Winter27', N'PHL 233: Political Philosophy', N'An examination of theories of justice, liberty, equality, and political obligation. Students read foundational texts from Plato, Locke, Mill, Marx, and Rawls alongside contemporary debates about democracy, multiculturalism, and global justice.', N'Philosophy', N'Arts & Sciences', 200, 3, N'PHL 101'),
  ('Spring27', N'CHM 167: Chemistry in Everyday Life', N'A survey course exploring how chemistry impacts daily life. Topics include food chemistry, pharmaceuticals, environmental chemistry, materials science, and energy. Designed for non-science majors to develop scientific literacy.', N'Chemistry', N'Arts & Sciences', 100, 3, NULL),
  ('Spring28', N'PHL 456: Senior Thesis in Philosophy', N'An independent research project resulting in a substantial philosophical essay. Students work with a faculty advisor to develop an original argument, engage with scholarly literature, and present their thesis at the departmental colloquium.', N'Philosophy', N'Arts & Sciences', 400, 4, N'Senior standing in PHL'),
  ('Summer27', N'HIS 188: World Civilizations II', N'A survey of global history from the early modern period to the present. Topics include colonialism, industrialization, nationalism, world wars, decolonization, the Cold War, and globalization. Emphasizes diverse perspectives and primary source analysis.', N'History', N'Arts & Sciences', 100, 3, NULL),
  ('Summer27', N'SPE 217: Behavior Support and Intervention', N'A practical course in understanding and addressing challenging behaviors in educational settings. Students learn functional behavior assessment, positive behavior interventions, de-escalation strategies, and ethical considerations in behavior management.', N'Special Education', N'Education', 200, 4, N'SPE 101'),
  ('Winter27', N'SPE 496: Advanced Practicum in Special Education', N'A culminating clinical experience in which students plan and deliver instruction to students with disabilities in school settings. Includes assessment, IEP implementation, collaboration with general educators, and reflective practice.', N'Special Education', N'Education', 400, 3, N'Senior standing in SPE'),
  ('Summer27', N'MTH 275: Discrete Mathematics', N'An introduction to mathematical structures and reasoning fundamental to computer science. Topics include logic, set theory, combinatorics, graph theory, recursive definitions, and proof techniques. Students develop skills in abstract reasoning and formal argumentation.', N'Mathematics', N'Arts & Sciences', 200, 2, N'MTH 131 or CSC 131'),
  ('Spring28', N'MEC 463: Finite Element Analysis', N'An advanced course in computational methods for structural and thermal analysis. Students learn the mathematical foundations of the finite element method and apply commercial FEA software to solve complex engineering problems.', N'Mechanical Engineering', N'Engineering', 400, 3, N'MEC 312'),
  ('Winter28', N'SOC 351: Sociology of Education', N'An examination of educational institutions through sociological lenses. Topics include educational inequality, school segregation, cultural capital, hidden curriculum, standardized testing, and the role of education in social mobility and social reproduction.', N'Sociology', N'Arts & Sciences', 300, 3, N'SOC 201'),
  ('Fall27', N'ECN 259: Econometrics', N'An introduction to statistical methods for economic analysis. Topics include regression analysis, hypothesis testing, model specification, time series analysis, and instrumental variables. Students use Stata or R to analyze economic datasets.', N'Economics', N'Business', 200, 2, N'ECN 201 and MTH 110'),
  ('Fall27', N'WLG 385: Translation Theory and Practice', N'An introduction to the theory and practice of translation between English and Spanish. Students translate a variety of text types including literary, journalistic, technical, and legal documents while exploring the cultural and linguistic challenges of translation.', N'World Languages', N'Arts & Sciences', 300, 3, N'WLG 202'),
  ('Fall26', N'PBH 317: Global Health', N'An examination of health challenges in a global context. Topics include infectious disease control, maternal and child health, nutrition, health systems strengthening, global health governance, and the social determinants of health across nations.', N'Public Health', N'Health Sciences', 300, 3, N'PBH 201'),
  ('Fall27', N'MGT 553: Graduate Seminar in Organizational Leadership', N'An advanced seminar exploring contemporary challenges in organizational leadership. Topics include leading distributed teams, managing organizational change, innovation management, and ethical leadership in complex organizations.', N'Management', N'Business', 500, 3, N'Graduate standing'),
  ('Spring27', N'HIS 201: History of Science and Technology', N'An exploration of how scientific knowledge and technological innovation have shaped human societies. Topics include the Scientific Revolution, industrialization, the atomic age, the digital revolution, and ethical debates surrounding emerging technologies.', N'History', N'Arts & Sciences', 200, 3, NULL),
  ('Spring27', N'MTH 179: Introduction to Statistics', N'An introductory course in descriptive and inferential statistics. Students learn to collect, organize, and interpret data using measures of central tendency, probability distributions, hypothesis testing, and confidence intervals. Real-world datasets from health, business, and social sciences are used throughout.', N'Mathematics', N'Arts & Sciences', 100, 3, NULL),
  ('Spring28', N'SCM 326: Crisis Communications', N'An examination of communication strategies during organizational crises. Students analyze real crisis cases, develop crisis communication plans, conduct media training exercises, and learn to manage reputation in the social media age.', N'Strategic Communications', N'Communications', 300, 3, N'SCM 201'),
  ('Spring27', N'NUR 495: Capstone Clinical Practicum', N'An intensive preceptored clinical experience in which senior students practice in a specialty area. Students demonstrate competence in clinical judgment, interprofessional collaboration, and evidence-based practice.', N'Nursing', N'Health Sciences', 400, 3, N'Senior standing in NUR and all clinical courses'),
  ('Fall27', N'CPE 589: Graduate Seminar in Hardware Security', N'An advanced seminar on security vulnerabilities and defenses in hardware systems. Topics include side-channel attacks, hardware trojans, secure boot, trusted execution environments, and supply chain security.', N'Computer Engineering', N'Engineering', 500, 3, N'Graduate standing'),
  ('Spring27', N'EED 306: Classroom Management and Community Building', N'A practical course in creating positive, productive classroom environments. Students learn proactive management strategies, restorative practices, culturally responsive approaches, and techniques for building inclusive classroom communities.', N'Elementary Education', N'Education', 300, 3, N'EED 202'),
  ('Summer28', N'FIN 195: Personal Finance', N'A practical course in managing personal financial decisions. Topics include budgeting, saving, investing, credit management, insurance, tax planning, and retirement planning. Students develop a comprehensive personal financial plan using current market data.', N'Finance', N'Business', 100, 3, NULL);
INSERT INTO dbo.CourseCatalog (TermID, CourseTitle, CourseDescription, Department, College, CourseLevel, Credits, Prerequisites)
VALUES
  ('Fall27', N'ART 544: Graduate Seminar in Contemporary Art Practice', N'An advanced seminar exploring current trends and critical frameworks in contemporary art. Students develop studio practice, engage with art theory, and present their work in professional critique settings.', N'Studio Art', N'Fine Arts', 500, 3, N'Graduate standing'),
  ('Summer27', N'ART 387: Art and Social Practice', N'An exploration of art as a tool for community engagement and social change. Students develop collaborative projects addressing social issues, working with communities to create participatory artworks that challenge traditional gallery-based models.', N'Studio Art', N'Fine Arts', 300, 2, N'One 200-level ART course'),
  ('Winter27', N'PSY 292: Social Psychology', N'An examination of how social contexts influence individual thought, feeling, and behavior. Topics include conformity, persuasion, group dynamics, prejudice, attraction, and prosocial behavior. Students critically evaluate classic and contemporary research.', N'Psychology', N'Arts & Sciences', 200, 3, N'PSY 101'),
  ('Spring27', N'HIS 127: World Civilizations II', N'A survey of global history from the early modern period to the present. Topics include colonialism, industrialization, nationalism, world wars, decolonization, the Cold War, and globalization. Emphasizes diverse perspectives and primary source analysis.', N'History', N'Arts & Sciences', 100, 1, NULL),
  ('Fall27', N'THR 198: Acting I', N'A foundational course in acting technique emphasizing relaxation, concentration, imagination, sensory work, and improvisation. Students develop skills in physical and vocal expression through exercises, scene work, and performance projects.', N'Theatre', N'Fine Arts', 100, 3, NULL),
  ('Winter28', N'ARH 384: Contemporary Art Since 1960', N'An examination of art from the 1960s to the present including Pop Art, Minimalism, Conceptual Art, Installation, Performance, and Digital Art. Students analyze how contemporary artists engage with issues of identity, globalization, and technology.', N'Art History', N'Fine Arts', 300, 3, N'ARH 211'),
  ('Summer28', N'CIV 179: Introduction to Civil Engineering', N'An overview of civil engineering sub-disciplines including structural, environmental, geotechnical, transportation, and water resources engineering. Students explore the role of civil engineers in designing sustainable infrastructure and protecting public safety.', N'Civil Engineering', N'Engineering', 100, 3, NULL),
  ('Winter27', N'MKT 186: Principles of Marketing', N'An introduction to marketing concepts and strategies including market segmentation, consumer behavior, product development, pricing, distribution, and promotion. Students develop a marketing plan for a real or simulated product.', N'Marketing', N'Business', 100, 3, NULL),
  ('Winter28', N'ELE 248: Signals and Systems', N'A mathematical treatment of continuous and discrete-time signals and systems. Topics include Fourier analysis, Laplace transforms, z-transforms, sampling theory, and linear time-invariant system analysis.', N'Electrical Engineering', N'Engineering', 200, 3, N'ELE 201 and MTH 302'),
  ('Spring27', N'HIS 144: United States History to 1877', N'An examination of American history from indigenous civilizations through Reconstruction. Topics include colonization, revolution, constitutional development, westward expansion, slavery, and the Civil War. Students analyze primary documents and historiographical debates.', N'History', N'Arts & Sciences', 100, 4, NULL),
  ('Winter28', N'ENV 276: Environmental Policy and Law', N'An examination of the legal and regulatory frameworks governing environmental protection. Topics include the Clean Air Act, Clean Water Act, NEPA, endangered species legislation, and international environmental agreements. Students analyze policy effectiveness and propose improvements.', N'Environmental Science', N'Arts & Sciences', 200, 3, N'ENV 101 or POL 101'),
  ('Spring28', N'EED 145: Introduction to Education', N'An exploration of the foundations of American education including its history, philosophy, and social contexts. Students examine current issues in education reform, observe in local classrooms, and reflect on their motivations for entering the teaching profession.', N'Elementary Education', N'Education', 100, 3, NULL),
  ('Winter28', N'PHY 267: University Physics I', N'A calculus-based treatment of classical mechanics including kinematics, dynamics, work-energy theorems, conservation laws, rigid body motion, and oscillations. Designed for physics and engineering majors.', N'Physics', N'Arts & Sciences', 200, 4, N'MTH 241 or concurrent enrollment'),
  ('Spring28', N'FIN 341: Risk Management', N'An examination of how organizations identify, measure, and manage financial risks. Topics include market risk, credit risk, operational risk, derivatives as hedging instruments, and enterprise risk management frameworks.', N'Finance', N'Business', 300, 4, N'FIN 201 and MTH 110'),
  ('Fall26', N'WLG 375: Translation Theory and Practice', N'An introduction to the theory and practice of translation between English and Spanish. Students translate a variety of text types including literary, journalistic, technical, and legal documents while exploring the cultural and linguistic challenges of translation.', N'World Languages', N'Arts & Sciences', 300, 4, N'WLG 202'),
  ('Spring28', N'EED 149: Introduction to Education', N'An exploration of the foundations of American education including its history, philosophy, and social contexts. Students examine current issues in education reform, observe in local classrooms, and reflect on their motivations for entering the teaching profession.', N'Elementary Education', N'Education', 100, 3, NULL),
  ('Fall26', N'THR 394: Directing', N'A study of the art and practice of theatrical direction. Topics include script analysis, concept development, staging, working with actors, and production management. Students direct scenes and one-act plays for public performance.', N'Theatre', N'Fine Arts', 300, 3, N'THR 102 and THR 211'),
  ('Spring28', N'PHL 334: Philosophy of Science', N'An analysis of the foundations, methods, and implications of scientific inquiry. Topics include the problem of induction, theory change, scientific explanation, realism vs. anti-realism, and the relationship between science and values.', N'Philosophy', N'Arts & Sciences', 300, 2, N'PHL 101 and one science course'),
  ('Spring27', N'MTH 372: Abstract Algebra', N'An introduction to algebraic structures including groups, rings, and fields. Students study concepts of homomorphism, isomorphism, and quotient structures while developing skills in abstract mathematical reasoning and proof construction.', N'Mathematics', N'Arts & Sciences', 300, 3, N'MTH 244'),
  ('Fall26', N'MUS 383: Music Technology and Production', N'An introduction to music technology including digital audio workstations, MIDI sequencing, audio recording and mixing, synthesis, and sound design. Students produce original recordings and learn the technical skills used in modern music production.', N'Music', N'Fine Arts', 300, 3, N'MUS 101'),
  ('Spring28', N'ECN 378: Behavioral Economics', N'An exploration of how psychological insights modify standard economic models. Topics include prospect theory, bounded rationality, time inconsistency, social preferences, and nudge theory. Students design and analyze behavioral experiments.', N'Economics', N'Business', 300, 3, N'ECN 201'),
  ('Winter28', N'EXS 546: Graduate Seminar in Applied Exercise Physiology', N'An advanced seminar examining current research in exercise physiology. Topics may include molecular exercise physiology, cardiovascular rehabilitation, altitude and heat adaptation, or exercise immunology.', N'Exercise Science', N'Health Sciences', 500, 3, N'Graduate standing'),
  ('Spring28', N'WLG 314: Hispanic Literature and Film', N'A study of major works of literature and film from Spain and Latin America in their cultural and historical contexts. Students develop advanced reading and analytical skills while exploring themes of identity, justice, memory, and artistic innovation.', N'World Languages', N'Arts & Sciences', 300, 3, N'WLG 202'),
  ('Winter28', N'MEC 403: Senior Design Project', N'A two-semester capstone experience in which student teams design, build, and test a mechanical system or device. Teams work with industry sponsors, manage budgets and schedules, and present their work at the engineering design showcase.', N'Mechanical Engineering', N'Engineering', 400, 4, N'Senior standing in MEC'),
  ('Winter27', N'BAN 207: Business Statistics', N'A rigorous course in statistical methods for business decision-making. Topics include probability, sampling distributions, confidence intervals, hypothesis testing, regression analysis, and time series forecasting. Students use R or Python for statistical computing.', N'Business Analytics', N'Business', 200, 4, N'BAN 101 and MTH 110'),
  ('Winter28', N'SPE 141: Introduction to Special Education', N'An overview of the field of special education including disability categories, legal foundations (IDEA, Section 504, ADA), inclusive practices, and the continuum of services. Students develop an understanding of diverse learner needs and strengths.', N'Special Education', N'Education', 100, 3, NULL),
  ('Fall27', N'CSC 255: Object-Oriented Programming', N'An in-depth study of object-oriented design principles including encapsulation, inheritance, polymorphism, and abstraction. Students build multi-class applications in Java, learning design patterns and unit testing practices that form the foundation of modern software engineering.', N'Computer Science', N'Arts & Sciences', 200, 3, N'CSC 131'),
  ('Fall27', N'SCM 273: Advertising and Campaign Planning', N'A study of advertising strategy from creative concept through media planning and execution. Students learn to develop creative briefs, design campaigns across multiple channels, and measure campaign effectiveness using marketing metrics.', N'Strategic Communications', N'Communications', 200, 4, N'SCM 101'),
  ('Winter27', N'SPE 416: Advanced Practicum in Special Education', N'A culminating clinical experience in which students plan and deliver instruction to students with disabilities in school settings. Includes assessment, IEP implementation, collaboration with general educators, and reflective practice.', N'Special Education', N'Education', 400, 3, N'Senior standing in SPE'),
  ('Fall27', N'PSY 521: Graduate Seminar in Cognitive Science', N'An interdisciplinary seminar exploring the intersection of psychology, neuroscience, computer science, and philosophy in understanding the mind. Students examine current debates about consciousness, artificial intelligence, and embodied cognition.', N'Psychology', N'Arts & Sciences', 500, 4, N'Graduate standing'),
  ('Spring27', N'ARH 333: Museum Studies', N'A practical course in museum theory and practice. Topics include collection management, exhibition design, interpretation, conservation ethics, and the evolving role of museums in society. Includes field experiences at local and regional museums.', N'Art History', N'Fine Arts', 300, 3, N'One 200-level ARH course'),
  ('Spring28', N'NUR 469: Leadership and Management in Nursing', N'A course in nursing leadership including healthcare systems, quality improvement, patient safety, team management, ethical decision-making, and healthcare policy advocacy. Prepares students for professional leadership roles.', N'Nursing', N'Health Sciences', 400, 3, N'Senior standing in NUR'),
  ('Winter28', N'ACC 423: Forensic Accounting and Fraud Examination', N'A study of fraud detection, investigation, and prevention techniques. Topics include financial statement fraud, asset misappropriation, corruption, digital forensics, and expert witness testimony. Students analyze real fraud cases and develop investigative skills.', N'Accounting', N'Business', 400, 3, N'ACC 301'),
  ('Spring28', N'CTV 505: Graduate Seminar in Digital Storytelling', N'An advanced seminar exploring emerging forms of storytelling including interactive narratives, virtual reality, web series, and transmedia franchises. Students produce original work that pushes the boundaries of traditional screen media.', N'Cinema & Television', N'Communications', 500, 3, N'Graduate standing'),
  ('Winter28', N'MKT 355: Brand Management', N'A study of how brands are created, positioned, and managed over time. Topics include brand equity measurement, brand architecture, brand extensions, brand revitalization, and global branding strategies. Students develop a comprehensive brand strategy.', N'Marketing', N'Business', 300, 3, N'MKT 201'),
  ('Fall27', N'CPE 246: Introduction to Computer Networks', N'A practical introduction to computer networking concepts and protocols. Topics include the Internet protocol stack, Ethernet, WiFi, IP addressing, routing, transport protocols, and network security fundamentals.', N'Computer Engineering', N'Engineering', 200, 4, N'CSC 231'),
  ('Winter28', N'THR 275: Stagecraft and Technical Production', N'A practical course in the technical aspects of theatre production including set construction, scenic painting, rigging, properties, and stage management. Students gain hands-on experience through crew assignments on departmental productions.', N'Theatre', N'Fine Arts', 200, 3, N'THR 101'),
  ('Fall27', N'PSY 442: Senior Seminar in Psychology', N'A capstone seminar requiring an original research project or comprehensive literature review. Students develop a research question, collect or analyze data, write a manuscript following APA format, and present findings at a departmental symposium.', N'Psychology', N'Arts & Sciences', 400, 3, N'Senior standing in PSY and PSY 201'),
  ('Spring27', N'EXS 294: Kinesiology and Biomechanics', N'An analysis of human movement using principles of physics and anatomy. Topics include joint mechanics, muscle function, gait analysis, ergonomics, and injury mechanisms. Students conduct biomechanical analyses using video and motion capture technology.', N'Exercise Science', N'Health Sciences', 200, 4, N'BIO 101 and PHY 101'),
  ('Summer27', N'POL 276: Public Policy Analysis', N'An examination of the policy-making process from agenda-setting through implementation and evaluation. Students analyze policies in areas such as healthcare, education, the environment, and criminal justice using frameworks from policy analysis.', N'Political Science', N'Arts & Sciences', 200, 4, N'POL 101'),
  ('Spring28', N'BAN 284: Data Management for Business', N'A practical course in managing and querying business data. Students learn relational database concepts, SQL query writing, data cleaning and transformation techniques, and basic data warehousing principles. Applications focus on marketing, finance, and operations datasets.', N'Business Analytics', N'Business', 200, 3, N'BAN 101'),
  ('Fall27', N'PHL 319: Existentialism', N'A study of existentialist philosophy through works of Kierkegaard, Nietzsche, Heidegger, Sartre, Beauvoir, and Camus. Students explore themes of freedom, anxiety, authenticity, absurdity, and the construction of meaning in a seemingly indifferent universe.', N'Philosophy', N'Arts & Sciences', 300, 3, N'PHL 101'),
  ('Spring27', N'JOU 492: Senior Capstone in Journalism', N'A culminating project in which students produce a substantial piece of original journalism — investigative report, documentary, multimedia project, or podcast series. Students pitch, research, produce, and present their work.', N'Journalism', N'Communications', 400, 3, N'Senior standing in JOU'),
  ('Spring28', N'MTH 439: Topology', N'An introduction to point-set topology covering topological spaces, continuous functions, connectedness, compactness, and separation axioms. Students develop abstract mathematical reasoning skills applicable to analysis, geometry, and theoretical computer science.', N'Mathematics', N'Arts & Sciences', 400, 3, N'MTH 441'),
  ('Spring28', N'PSY 272: Biological Psychology', N'A study of the biological bases of behavior including neuroanatomy, neurotransmitter systems, sensory processing, motivation, emotion, learning, and psychopharmacology. Bridges neuroscience and psychological perspectives on mind-brain relationships.', N'Psychology', N'Arts & Sciences', 200, 3, N'PSY 101'),
  ('Fall27', N'MUS 319: Music Technology and Production', N'An introduction to music technology including digital audio workstations, MIDI sequencing, audio recording and mixing, synthesis, and sound design. Students produce original recordings and learn the technical skills used in modern music production.', N'Music', N'Fine Arts', 300, 3, N'MUS 101'),
  ('Summer27', N'JOU 487: Senior Capstone in Journalism', N'A culminating project in which students produce a substantial piece of original journalism — investigative report, documentary, multimedia project, or podcast series. Students pitch, research, produce, and present their work.', N'Journalism', N'Communications', 400, 3, N'Senior standing in JOU'),
  ('Fall27', N'SCM 341: Crisis Communications', N'An examination of communication strategies during organizational crises. Students analyze real crisis cases, develop crisis communication plans, conduct media training exercises, and learn to manage reputation in the social media age.', N'Strategic Communications', N'Communications', 300, 3, N'SCM 201'),
  ('Fall26', N'ECN 132: Principles of Macroeconomics', N'An introduction to macroeconomic theory including GDP, inflation, unemployment, monetary and fiscal policy, international trade, and economic growth. Students analyze current economic conditions and evaluate policy responses.', N'Economics', N'Business', 100, 3, NULL),
  ('Winter28', N'MTH 281: Linear Algebra', N'A study of vector spaces, linear transformations, matrices, determinants, eigenvalues, and eigenvectors. Applications include systems of linear equations, least-squares approximation, and Markov chains. This course provides essential mathematical foundations for machine learning, data science, and engineering.', N'Mathematics', N'Arts & Sciences', 200, 3, N'MTH 241');
INSERT INTO dbo.CourseCatalog (TermID, CourseTitle, CourseDescription, Department, College, CourseLevel, Credits, Prerequisites)
VALUES
  ('Fall26', N'BIO 163: Human Biology', N'A survey of human biological systems for non-majors. Covers anatomy and physiology of major organ systems, nutrition, immunology, and genetics as they relate to human health and disease. Emphasizes critical evaluation of health claims in the media.', N'Biology', N'Arts & Sciences', 100, 4, NULL),
  ('Summer28', N'PHY 466: Senior Thesis in Physics', N'Independent research culminating in a written thesis and public presentation. Students work closely with a faculty advisor on an original project in experimental or theoretical physics.', N'Physics', N'Arts & Sciences', 400, 3, N'Senior standing in PHY'),
  ('Spring28', N'MKT 267: Marketing Research', N'An introduction to marketing research methods including survey design, focus groups, experimental research, and secondary data analysis. Students learn to use data analytics tools to derive actionable marketing insights from consumer and market data.', N'Marketing', N'Business', 200, 3, N'MKT 101 and MTH 110'),
  ('Fall27', N'BIO 383: Neuroscience', N'An interdisciplinary exploration of the nervous system from molecular to behavioral levels. Topics include neuronal signaling, synaptic transmission, sensory systems, motor control, learning and memory, and neurological disorders. Bridges biology and psychology perspectives.', N'Biology', N'Arts & Sciences', 300, 3, N'BIO 211 or PSY 201'),
  ('Fall26', N'HLA 187: Introduction to Health Administration', N'An overview of the U.S. healthcare system including its organization, financing, delivery, and governance. Students explore the roles of hospitals, insurers, government agencies, and public health organizations in healthcare delivery.', N'Health Administration', N'Health Sciences', 100, 3, NULL),
  ('Winter28', N'MEC 331: Machine Design', N'An applied course in designing mechanical components and systems. Topics include stress analysis, fatigue, bearings, gears, shafts, springs, and bolted connections. Students use CAD software and finite element analysis to design and optimize components.', N'Mechanical Engineering', N'Engineering', 300, 3, N'MEC 201 and MEC 203'),
  ('Summer27', N'CSC 387: Artificial Intelligence', N'A broad survey of AI concepts and techniques including search algorithms, knowledge representation, planning, and natural language processing basics. Students implement intelligent agents and explore ethical considerations surrounding autonomous decision-making systems.', N'Computer Science', N'Arts & Sciences', 300, 4, N'CSC 231 and MTH 241'),
  ('Spring28', N'MEC 338: Control Systems', N'An introduction to feedback control theory for mechanical systems. Topics include system modeling, transfer functions, stability analysis, root locus, frequency response, and PID controller design. Students design and simulate controllers using MATLAB.', N'Mechanical Engineering', N'Engineering', 300, 3, N'MEC 201 and MTH 302'),
  ('Winter27', N'FIN 411: Investment Banking and Valuation', N'An advanced course in corporate valuation and investment banking practices. Topics include DCF analysis, comparable company analysis, LBO modeling, M&A processes, and IPO structuring. Students complete a comprehensive valuation project.', N'Finance', N'Business', 400, 3, N'FIN 301'),
  ('Winter28', N'HLA 304: Healthcare Law and Regulatory Compliance', N'An examination of the legal and regulatory environment of healthcare. Topics include HIPAA, fraud and abuse laws, medical malpractice, informed consent, accreditation, and regulatory compliance programs.', N'Health Administration', N'Health Sciences', 300, 3, N'HLA 101'),
  ('Fall27', N'HIS 471: Senior Seminar in History', N'A capstone seminar in which students produce an original research paper based on primary source analysis. Topics vary by semester. Students develop expertise in historical methodology, argumentation, and scholarly writing.', N'History', N'Arts & Sciences', 400, 2, N'HIS 301 and senior standing'),
  ('Spring27', N'PHL 339: Ethics of Artificial Intelligence', N'A philosophical examination of ethical issues raised by artificial intelligence and autonomous systems. Topics include algorithmic bias, accountability for AI decisions, privacy, the future of work, machine consciousness, and the alignment problem in advanced AI systems.', N'Philosophy', N'Arts & Sciences', 300, 3, N'PHL 102 or CSC 131'),
  ('Winter28', N'POL 229: Political Research Methods', N'An introduction to empirical research methods in political science including research design, quantitative and qualitative approaches, survey methods, and statistical analysis. Students complete a research project using real political data.', N'Political Science', N'Arts & Sciences', 200, 3, N'POL 101'),
  ('Spring28', N'WLG 496: Senior Seminar in World Languages', N'A capstone seminar in which students conduct independent research on a topic related to language, linguistics, or culture. Students present their findings in both the target language and English, demonstrating advanced analytical and communication skills.', N'World Languages', N'Arts & Sciences', 400, 3, N'Senior standing in WLG'),
  ('Winter28', N'CIV 454: Construction Project Management', N'An advanced course in managing construction projects. Topics include estimating, scheduling (CPM), contract administration, safety management, quality control, and building information modeling (BIM).', N'Civil Engineering', N'Engineering', 400, 4, N'CIV 301'),
  ('Summer28', N'ENV 384: Climate Change Science and Policy', N'A comprehensive examination of climate change from scientific and policy perspectives. Covers atmospheric physics, climate modeling, observed impacts, mitigation strategies, adaptation planning, and international climate negotiations. Students analyze climate data and evaluate policy proposals.', N'Environmental Science', N'Arts & Sciences', 300, 4, N'ENV 101 and one science elective'),
  ('Fall26', N'BAN 193: Introduction to Business Analytics', N'An overview of how organizations use data to drive decision-making. Topics include descriptive analytics, data visualization, basic statistical analysis, and an introduction to predictive modeling. Students work with real business datasets using Excel and Tableau.', N'Business Analytics', N'Business', 100, 3, NULL),
  ('Fall27', N'PBH 306: Health Policy and Management', N'A study of healthcare organization, financing, and policy in the United States and internationally. Topics include health insurance, managed care, healthcare quality, access disparities, and the policy-making process.', N'Public Health', N'Health Sciences', 300, 3, N'PBH 101'),
  ('Spring28', N'EXS 357: Strength and Conditioning', N'A practical course in designing exercise programs for athletic performance and general fitness. Students learn resistance training techniques, periodization, speed and agility development, and program design for diverse populations.', N'Exercise Science', N'Health Sciences', 300, 3, N'EXS 211'),
  ('Spring27', N'ECN 488: Senior Seminar in Economics', N'A capstone seminar in which students conduct original empirical research on an economic question. Students develop a research proposal, collect and analyze data, and present findings in both written and oral formats.', N'Economics', N'Business', 400, 3, N'ECN 221 and senior standing'),
  ('Spring27', N'PHL 228: Political Philosophy', N'An examination of theories of justice, liberty, equality, and political obligation. Students read foundational texts from Plato, Locke, Mill, Marx, and Rawls alongside contemporary debates about democracy, multiculturalism, and global justice.', N'Philosophy', N'Arts & Sciences', 200, 3, N'PHL 101'),
  ('Summer28', N'MTH 489: Real Analysis', N'An advanced course in the rigorous foundations of calculus. Topics include the completeness of the real numbers, sequences and series of functions, metric spaces, continuity, differentiability, and Riemann integration. Emphasizes epsilon-delta proofs and mathematical rigor.', N'Mathematics', N'Arts & Sciences', 400, 3, N'MTH 341'),
  ('Winter27', N'PHY 452: Electrodynamics', N'An advanced study of electromagnetic theory based on Maxwell''s equations. Topics include boundary value problems, electromagnetic waves, radiation, and special relativity. Students develop skills in vector calculus and mathematical physics.', N'Physics', N'Arts & Sciences', 400, 3, N'PHY 312 and MTH 302'),
  ('Fall26', N'SCM 131: Introduction to Strategic Communications', N'An overview of the strategic communications field including public relations, advertising, and integrated marketing communications. Students learn campaign planning, message development, media relations, and the role of communication in organizational strategy.', N'Strategic Communications', N'Communications', 100, 3, NULL),
  ('Fall27', N'SOC 402: Senior Capstone in Sociology', N'A culminating experience in which students complete an independent research project or community-based applied project. Students present their work at the departmental symposium and produce a portfolio reflecting their sociological learning.', N'Sociology', N'Arts & Sciences', 400, 3, N'Senior standing in SOC and SOC 201'),
  ('Fall27', N'HIS 184: World Civilizations I', N'A survey of global history from ancient civilizations through the early modern period. Examines the development of complex societies, empires, trade networks, religious traditions, and cultural exchanges across Africa, Asia, Europe, and the Americas.', N'History', N'Arts & Sciences', 100, 3, NULL),
  ('Spring28', N'EED 141: Introduction to Education', N'An exploration of the foundations of American education including its history, philosophy, and social contexts. Students examine current issues in education reform, observe in local classrooms, and reflect on their motivations for entering the teaching profession.', N'Elementary Education', N'Education', 100, 3, NULL),
  ('Summer28', N'POL 118: Introduction to American Government', N'An overview of the American political system including the Constitution, federalism, civil liberties, political parties, elections, Congress, the presidency, and the judiciary. Students analyze current political events using foundational concepts in political science.', N'Political Science', N'Arts & Sciences', 100, 4, NULL),
  ('Winter28', N'PHL 364: Philosophy of Science', N'An analysis of the foundations, methods, and implications of scientific inquiry. Topics include the problem of induction, theory change, scientific explanation, realism vs. anti-realism, and the relationship between science and values.', N'Philosophy', N'Arts & Sciences', 300, 3, N'PHL 101 and one science course'),
  ('Winter28', N'ELE 368: Communication Systems', N'An introduction to analog and digital communication systems. Topics include modulation techniques, noise analysis, channel capacity, error correction coding, and an introduction to wireless communications.', N'Electrical Engineering', N'Engineering', 300, 3, N'ELE 203'),
  ('Spring27', N'MEC 446: Senior Design Project', N'A two-semester capstone experience in which student teams design, build, and test a mechanical system or device. Teams work with industry sponsors, manage budgets and schedules, and present their work at the engineering design showcase.', N'Mechanical Engineering', N'Engineering', 400, 4, N'Senior standing in MEC'),
  ('Summer27', N'EDL 376: Instructional Leadership', N'A course in leading curriculum and instruction improvement at the school and district level. Topics include observation and feedback, professional learning communities, data-driven decision-making, and leading collaborative teams.', N'Educational Leadership', N'Education', 300, 4, N'EDL 201'),
  ('Spring27', N'HIS 394: History of the American South', N'An examination of the American South from colonial settlement to the present. Topics include plantation society, the Civil War and Reconstruction, the New South, civil rights activism, and contemporary southern identity. Explores race, class, and gender as analytical categories.', N'History', N'Arts & Sciences', 300, 3, N'One 200-level HIS course'),
  ('Fall26', N'ARH 587: Graduate Seminar in Visual Culture', N'An advanced seminar examining theories of visual culture and their application to art historical analysis. Topics include spectatorship, representation, power, and the relationship between high art and popular visual media.', N'Art History', N'Fine Arts', 500, 3, N'Graduate standing'),
  ('Spring27', N'ENV 164: Sustainability and Society', N'An exploration of sustainability concepts and practices across environmental, economic, and social dimensions. Students examine case studies of sustainable communities, renewable energy, circular economies, and corporate sustainability initiatives.', N'Environmental Science', N'Arts & Sciences', 100, 3, NULL),
  ('Spring28', N'SPE 255: Behavior Support and Intervention', N'A practical course in understanding and addressing challenging behaviors in educational settings. Students learn functional behavior assessment, positive behavior interventions, de-escalation strategies, and ethical considerations in behavior management.', N'Special Education', N'Education', 200, 3, N'SPE 101'),
  ('Fall27', N'EED 378: Classroom Management and Community Building', N'A practical course in creating positive, productive classroom environments. Students learn proactive management strategies, restorative practices, culturally responsive approaches, and techniques for building inclusive classroom communities.', N'Elementary Education', N'Education', 300, 4, N'EED 202'),
  ('Spring27', N'ENG 129: Introduction to Literature', N'An introduction to the major literary genres including fiction, poetry, and drama. Students develop close reading skills and learn to write analytical essays about literary texts. Works are drawn from diverse cultural traditions and historical periods.', N'English', N'Arts & Sciences', 100, 3, NULL),
  ('Spring28', N'EED 309: Classroom Management and Community Building', N'A practical course in creating positive, productive classroom environments. Students learn proactive management strategies, restorative practices, culturally responsive approaches, and techniques for building inclusive classroom communities.', N'Elementary Education', N'Education', 300, 3, N'EED 202'),
  ('Summer28', N'CSC 501: Vector Databases and Semantic Search', N'An exploration of vector database technologies and their role in modern AI applications. Topics include embedding generation, approximate nearest neighbor algorithms, hybrid search combining vector similarity with structured filters, and real-world deployment patterns for semantic search systems in enterprise environments.', N'Computer Science', N'Arts & Sciences', 500, 3, N'CSC 341 or CSC 436 and graduate standing'),
  ('Fall27', N'BAN 113: Introduction to Business Analytics', N'An overview of how organizations use data to drive decision-making. Topics include descriptive analytics, data visualization, basic statistical analysis, and an introduction to predictive modeling. Students work with real business datasets using Excel and Tableau.', N'Business Analytics', N'Business', 100, 3, NULL),
  ('Summer27', N'CSC 208: Object-Oriented Programming', N'An in-depth study of object-oriented design principles including encapsulation, inheritance, polymorphism, and abstraction. Students build multi-class applications in Java, learning design patterns and unit testing practices that form the foundation of modern software engineering.', N'Computer Science', N'Arts & Sciences', 200, 3, N'CSC 131'),
  ('Fall26', N'HLA 387: Healthcare Quality and Patient Safety', N'A study of methods for improving healthcare quality and ensuring patient safety. Topics include quality measurement, performance improvement, root cause analysis, high reliability organizations, and evidence-based management practices.', N'Health Administration', N'Health Sciences', 300, 3, N'HLA 101'),
  ('Winter28', N'CSC 285: Introduction to Web Development', N'A practical course covering full-stack web development fundamentals. Students build interactive web applications using HTML, CSS, JavaScript, and server-side frameworks. Topics include RESTful API design, responsive layouts, and basic deployment practices.', N'Computer Science', N'Arts & Sciences', 200, 1, N'CSC 131'),
  ('Winter28', N'CSC 363: Software Engineering', N'A project-based course in software development methodologies. Students work in teams using Agile practices to design, implement, test, and deploy a complete software application. Covers requirements gathering, version control with Git, continuous integration, and technical documentation.', N'Computer Science', N'Arts & Sciences', 300, 3, N'CSC 232'),
  ('Fall27', N'CHM 334: Physical Chemistry', N'A study of the physical principles underlying chemical phenomena including quantum mechanics, molecular spectroscopy, thermodynamics, and chemical kinetics. Students develop mathematical and computational skills for modeling chemical systems.', N'Chemistry', N'Arts & Sciences', 300, 4, N'CHM 102, MTH 242, and PHY 202'),
  ('Spring28', N'PBH 247: Biostatistics', N'An introduction to statistical methods for public health research. Topics include descriptive statistics, probability, sampling distributions, hypothesis testing, regression, and survival analysis. Students use SAS or R to analyze health datasets.', N'Public Health', N'Health Sciences', 200, 3, N'MTH 110'),
  ('Spring27', N'BIO 394: Molecular Biology', N'Advanced study of gene structure, expression, and regulation at the molecular level. Topics include genome organization, epigenetics, RNA processing, protein folding, and CRISPR-based gene editing technologies. Students read and critique primary research literature.', N'Biology', N'Arts & Sciences', 300, 3, N'BIO 211 and CHM 201'),
  ('Winter28', N'THR 311: Directing', N'A study of the art and practice of theatrical direction. Topics include script analysis, concept development, staging, working with actors, and production management. Students direct scenes and one-act plays for public performance.', N'Theatre', N'Fine Arts', 300, 3, N'THR 102 and THR 211'),
  ('Spring27', N'CHM 188: General Chemistry I', N'Introduction to the fundamental principles of chemistry including atomic structure, chemical bonding, stoichiometry, thermochemistry, and gas laws. Laboratory work develops quantitative measurement skills, safety practices, and scientific reasoning.', N'Chemistry', N'Arts & Sciences', 100, 4, NULL);
INSERT INTO dbo.CourseCatalog (TermID, CourseTitle, CourseDescription, Department, College, CourseLevel, Credits, Prerequisites)
VALUES
  ('Winter28', N'MTH 318: Numerical Analysis', N'A study of computational methods for solving mathematical problems including root finding, interpolation, numerical integration, and numerical solutions of differential equations. Students implement algorithms in Python and analyze convergence, stability, and error propagation.', N'Mathematics', N'Arts & Sciences', 300, 3, N'MTH 242 and programming experience'),
  ('Spring27', N'JOU 219: News Writing and Reporting', N'A practical course in news writing for digital and print media. Students learn to write leads, conduct interviews, cover beats, and produce stories on deadline. Emphasizes accuracy, fairness, AP style, and multimedia storytelling.', N'Journalism', N'Communications', 200, 3, N'JOU 101'),
  ('Spring28', N'MTH 298: Calculus I', N'The first course in a three-semester calculus sequence. Topics include limits, continuity, differentiation of algebraic and transcendental functions, and applications of derivatives including optimization and related rates. Emphasizes both computational techniques and conceptual understanding.', N'Mathematics', N'Arts & Sciences', 200, 3, N'MTH 151 or placement'),
  ('Spring28', N'SOC 549: Graduate Seminar in Social Stratification', N'An advanced seminar examining theories and research on social inequality. Topics include class structure, income and wealth distribution, intergenerational mobility, intersectionality, and comparative stratification systems.', N'Sociology', N'Arts & Sciences', 500, 3, N'Graduate standing'),
  ('Fall26', N'CIV 251: Mechanics of Materials', N'A study of the behavior of solid materials under various loading conditions. Topics include stress, strain, beam deflection, torsion, column buckling, and material failure theories. Applications to structural engineering design.', N'Civil Engineering', N'Engineering', 200, 4, N'MEC 201'),
  ('Winter28', N'HIS 462: Digital Humanities', N'An exploration of how digital tools and methods transform historical research and presentation. Topics include text mining, network analysis, GIS mapping, digital archives, and data visualization applied to humanistic inquiry.', N'History', N'Arts & Sciences', 400, 3, N'HIS 301 or equivalent research methods course'),
  ('Winter27', N'ENV 269: Geographic Information Systems', N'An introduction to GIS technology for spatial analysis and mapping. Students learn to collect, manage, analyze, and visualize geographic data using ArcGIS and open-source tools. Applications include environmental monitoring, urban planning, and natural resource management.', N'Environmental Science', N'Arts & Sciences', 200, 3, NULL),
  ('Winter28', N'FIN 119: Personal Finance', N'A practical course in managing personal financial decisions. Topics include budgeting, saving, investing, credit management, insurance, tax planning, and retirement planning. Students develop a comprehensive personal financial plan using current market data.', N'Finance', N'Business', 100, 3, NULL),
  ('Spring27', N'FIN 416: Investment Banking and Valuation', N'An advanced course in corporate valuation and investment banking practices. Topics include DCF analysis, comparable company analysis, LBO modeling, M&A processes, and IPO structuring. Students complete a comprehensive valuation project.', N'Finance', N'Business', 400, 2, N'FIN 301'),
  ('Summer28', N'NUR 366: Medical-Surgical Nursing', N'Clinical nursing practice focused on adults with acute and chronic health conditions. Students develop skills in assessment, care planning, medication administration, and patient education across hospital and outpatient settings.', N'Nursing', N'Health Sciences', 300, 3, N'NUR 201, NUR 202, NUR 203'),
  ('Spring28', N'CSC 478: Database Administration and Performance', N'Advanced topics in database management including query plan analysis, index tuning, replication, high availability configurations, and disaster recovery planning. Students work with enterprise database systems to diagnose performance bottlenecks and implement optimization strategies.', N'Computer Science', N'Arts & Sciences', 400, 3, N'CSC 236'),
  ('Spring28', N'POL 463: Senior Seminar in Political Science', N'A capstone seminar requiring original research on a topic of the student''s choosing. Students develop a research question, conduct systematic analysis using appropriate methods, and produce a scholarly paper suitable for presentation at an academic conference.', N'Political Science', N'Arts & Sciences', 400, 3, N'POL 202 and senior standing'),
  ('Spring27', N'MUS 395: Music Technology and Production', N'An introduction to music technology including digital audio workstations, MIDI sequencing, audio recording and mixing, synthesis, and sound design. Students produce original recordings and learn the technical skills used in modern music production.', N'Music', N'Fine Arts', 300, 3, N'MUS 101'),
  ('Fall26', N'PHL 327: Existentialism', N'A study of existentialist philosophy through works of Kierkegaard, Nietzsche, Heidegger, Sartre, Beauvoir, and Camus. Students explore themes of freedom, anxiety, authenticity, absurdity, and the construction of meaning in a seemingly indifferent universe.', N'Philosophy', N'Arts & Sciences', 300, 3, N'PHL 101'),
  ('Fall26', N'ART 266: Sculpture I', N'An introduction to three-dimensional art-making using a variety of materials and processes including clay, wood, metal, and found objects. Students explore form, space, texture, and conceptual approaches to sculptural practice.', N'Studio Art', N'Fine Arts', 200, 3, N'ART 102'),
  ('Fall26', N'MGT 248: Business Ethics', N'An examination of ethical issues in business practice. Topics include corporate social responsibility, stakeholder theory, ethical decision-making frameworks, whistleblowing, environmental sustainability, and ethics in global business operations.', N'Management', N'Business', 200, 3, N'MGT 101'),
  ('Fall26', N'MGT 213: Business Ethics', N'An examination of ethical issues in business practice. Topics include corporate social responsibility, stakeholder theory, ethical decision-making frameworks, whistleblowing, environmental sustainability, and ethics in global business operations.', N'Management', N'Business', 200, 3, N'MGT 101'),
  ('Fall27', N'JOU 162: Introduction to Journalism', N'An introduction to the principles and practices of journalism in a multimedia environment. Students learn news gathering, interviewing, writing, and editing across print, broadcast, and digital platforms. Explores press freedom, media ethics, and the role of journalism in democracy.', N'Journalism', N'Communications', 100, 3, NULL),
  ('Fall27', N'CSC 496: Deep Learning and Neural Networks', N'An advanced course covering deep neural network architectures including convolutional networks, recurrent networks, attention mechanisms, and generative models. Students train models using PyTorch on GPU hardware and explore applications in computer vision, natural language processing, and time series prediction.', N'Computer Science', N'Arts & Sciences', 400, 3, N'CSC 341'),
  ('Spring27', N'MKT 319: Marketing Analytics', N'An applied course in using data to inform marketing decisions. Students learn statistical modeling, customer segmentation, predictive analytics, A/B testing, and attribution modeling. Uses R and marketing analytics platforms on real datasets.', N'Marketing', N'Business', 300, 1, N'MKT 203 and MTH 110'),
  ('Winter27', N'PHL 363: Philosophy of Science', N'An analysis of the foundations, methods, and implications of scientific inquiry. Topics include the problem of induction, theory change, scientific explanation, realism vs. anti-realism, and the relationship between science and values.', N'Philosophy', N'Arts & Sciences', 300, 3, N'PHL 101 and one science course'),
  ('Winter27', N'PSY 122: Introduction to Psychology', N'A survey of the major areas of psychological science including cognition, development, social behavior, personality, psychopathology, and neuroscience. Students learn to evaluate psychological claims using scientific evidence and critical thinking skills.', N'Psychology', N'Arts & Sciences', 100, 3, NULL),
  ('Spring27', N'ENG 172: English Composition II', N'A continuation of composition skills with emphasis on research-based writing. Students learn to locate, evaluate, and synthesize scholarly sources while developing longer analytical arguments. Topics include rhetorical analysis, information literacy, and documentation practices.', N'English', N'Arts & Sciences', 100, 3, N'ENG 101'),
  ('Winter27', N'MGT 274: Business Ethics', N'An examination of ethical issues in business practice. Topics include corporate social responsibility, stakeholder theory, ethical decision-making frameworks, whistleblowing, environmental sustainability, and ethics in global business operations.', N'Management', N'Business', 200, 3, N'MGT 101'),
  ('Spring27', N'SCM 366: Social Media Strategy', N'An advanced course in developing and executing social media strategies for organizations. Topics include platform selection, content planning, community management, influencer partnerships, paid social advertising, and social media analytics.', N'Strategic Communications', N'Communications', 300, 3, N'SCM 201'),
  ('Spring28', N'PBH 276: Biostatistics', N'An introduction to statistical methods for public health research. Topics include descriptive statistics, probability, sampling distributions, hypothesis testing, regression, and survival analysis. Students use SAS or R to analyze health datasets.', N'Public Health', N'Health Sciences', 200, 3, N'MTH 110'),
  ('Spring28', N'JOU 193: Introduction to Journalism', N'An introduction to the principles and practices of journalism in a multimedia environment. Students learn news gathering, interviewing, writing, and editing across print, broadcast, and digital platforms. Explores press freedom, media ethics, and the role of journalism in democracy.', N'Journalism', N'Communications', 100, 3, NULL),
  ('Summer28', N'ENV 238: Geographic Information Systems', N'An introduction to GIS technology for spatial analysis and mapping. Students learn to collect, manage, analyze, and visualize geographic data using ArcGIS and open-source tools. Applications include environmental monitoring, urban planning, and natural resource management.', N'Environmental Science', N'Arts & Sciences', 200, 3, NULL),
  ('Spring27', N'ACC 255: Intermediate Accounting I', N'An in-depth study of financial accounting theory and practice. Topics include the conceptual framework, income measurement, balance sheet classification, time value of money, revenue recognition, and accounting for current and long-term assets.', N'Accounting', N'Business', 200, 3, N'ACC 102'),
  ('Summer27', N'ARH 394: Contemporary Art Since 1960', N'An examination of art from the 1960s to the present including Pop Art, Minimalism, Conceptual Art, Installation, Performance, and Digital Art. Students analyze how contemporary artists engage with issues of identity, globalization, and technology.', N'Art History', N'Fine Arts', 300, 3, N'ARH 211'),
  ('Spring28', N'ACC 466: Advanced Accounting', N'A capstone course covering complex accounting topics including business combinations, consolidated financial statements, foreign currency transactions, government and nonprofit accounting, and partnership accounting.', N'Accounting', N'Business', 400, 3, N'ACC 212'),
  ('Fall27', N'CHM 583: Graduate Research in Chemistry', N'Supervised research in an active faculty research lab. Students conduct original research, participate in group meetings, and present progress reports. Culminates in a thesis or publishable manuscript.', N'Chemistry', N'Arts & Sciences', 500, 3, N'Graduate standing'),
  ('Fall26', N'MUS 374: World Music', N'A comparative study of musical traditions from Africa, Asia, Latin America, and indigenous cultures. Students explore the social functions of music, instruments and performance practices, and the impact of globalization on world music traditions.', N'Music', N'Fine Arts', 300, 3, N'MUS 102 or MUS 201'),
  ('Spring28', N'JOU 217: Photojournalism', N'A course in visual storytelling through photography. Students learn composition, lighting, and digital editing techniques while developing the ability to capture news events and human interest stories through compelling images.', N'Journalism', N'Communications', 200, 3, N'JOU 101'),
  ('Fall27', N'MUS 235: Music Theory II', N'Continuation of Music Theory I covering chromatic harmony, modulation, formal analysis, and an introduction to twentieth-century techniques. Students compose short works applying theoretical concepts and analyze works from the Western art music repertoire.', N'Music', N'Fine Arts', 200, 3, N'MUS 101'),
  ('Spring27', N'HLA 362: Healthcare Quality and Patient Safety', N'A study of methods for improving healthcare quality and ensuring patient safety. Topics include quality measurement, performance improvement, root cause analysis, high reliability organizations, and evidence-based management practices.', N'Health Administration', N'Health Sciences', 300, 3, N'HLA 101'),
  ('Fall27', N'JOU 589: Graduate Seminar in Media Ethics and Law', N'An advanced seminar examining legal and ethical frameworks governing journalism and media. Topics include press freedom, defamation, privacy, shield laws, access to information, and ethical dilemmas in the digital age.', N'Journalism', N'Communications', 500, 4, N'Graduate standing'),
  ('Fall26', N'THR 259: Stagecraft and Technical Production', N'A practical course in the technical aspects of theatre production including set construction, scenic painting, rigging, properties, and stage management. Students gain hands-on experience through crew assignments on departmental productions.', N'Theatre', N'Fine Arts', 200, 3, N'THR 101'),
  ('Fall26', N'NUR 136: Introduction to Professional Nursing', N'An overview of the nursing profession including its history, ethical foundations, scope of practice, and the nurse''s role in healthcare delivery. Students explore nursing theory, evidence-based practice, and the impact of healthcare policy on patient care.', N'Nursing', N'Health Sciences', 100, 3, NULL),
  ('Fall26', N'ENG 166: English Composition II', N'A continuation of composition skills with emphasis on research-based writing. Students learn to locate, evaluate, and synthesize scholarly sources while developing longer analytical arguments. Topics include rhetorical analysis, information literacy, and documentation practices.', N'English', N'Arts & Sciences', 100, 3, N'ENG 101'),
  ('Fall26', N'JOU 139: Introduction to Journalism', N'An introduction to the principles and practices of journalism in a multimedia environment. Students learn news gathering, interviewing, writing, and editing across print, broadcast, and digital platforms. Explores press freedom, media ethics, and the role of journalism in democracy.', N'Journalism', N'Communications', 100, 3, NULL),
  ('Fall27', N'MEC 194: Introduction to Engineering', N'A broad introduction to engineering disciplines and the engineering design process. Students work in teams to solve open-ended design challenges using computer-aided design tools, prototyping, and iterative testing. Develops creative problem-solving and communication skills.', N'Mechanical Engineering', N'Engineering', 100, 4, NULL),
  ('Summer27', N'JOU 499: Senior Capstone in Journalism', N'A culminating project in which students produce a substantial piece of original journalism — investigative report, documentary, multimedia project, or podcast series. Students pitch, research, produce, and present their work.', N'Journalism', N'Communications', 400, 3, N'Senior standing in JOU'),
  ('Fall26', N'PSY 315: Cognitive Psychology', N'An in-depth examination of mental processes including attention, perception, memory, language, problem-solving, and decision-making. Students explore computational models of cognition and evaluate evidence from behavioral experiments and brain imaging studies.', N'Psychology', N'Arts & Sciences', 300, 3, N'PSY 201'),
  ('Fall26', N'BAN 226: Data Management for Business', N'A practical course in managing and querying business data. Students learn relational database concepts, SQL query writing, data cleaning and transformation techniques, and basic data warehousing principles. Applications focus on marketing, finance, and operations datasets.', N'Business Analytics', N'Business', 200, 4, N'BAN 101'),
  ('Spring28', N'ACC 188: Principles of Managerial Accounting', N'An introduction to accounting for internal decision-making. Topics include cost behavior analysis, budgeting, variance analysis, capital budgeting, and performance evaluation. Students learn to use accounting information for planning, controlling, and evaluating business operations.', N'Accounting', N'Business', 100, 3, N'ACC 101'),
  ('Spring27', N'FIN 476: Senior Capstone in Finance', N'A capstone experience integrating financial theory and practice. Students complete an applied research project or case competition addressing complex financial problems. Develops skills in financial analysis, communication, and professional judgment.', N'Finance', N'Business', 400, 3, N'Senior standing in FIN'),
  ('Fall26', N'BIO 111: General Biology II', N'Continuation of General Biology I focusing on organismal biology, ecology, and evolution. Topics include biodiversity, population genetics, ecosystem dynamics, and phylogenetics. Laboratory work includes field ecology and comparative anatomy.', N'Biology', N'Arts & Sciences', 100, 4, N'BIO 101'),
  ('Winter28', N'FIN 324: International Finance', N'A study of financial management in a global context. Topics include exchange rate determination, currency risk management, international capital budgeting, cross-border investment, and the global financial system.', N'Finance', N'Business', 300, 3, N'FIN 201'),
  ('Fall27', N'EDL 559: Graduate Seminar in Educational Administration', N'An advanced seminar preparing aspiring school administrators. Topics include strategic planning, school finance, human resource management, community engagement, and leading organizational change in complex educational environments.', N'Educational Leadership', N'Education', 500, 3, N'Graduate standing and teaching experience');
INSERT INTO dbo.CourseCatalog (TermID, CourseTitle, CourseDescription, Department, College, CourseLevel, Credits, Prerequisites)
VALUES
  ('Winter27', N'BAN 463: Machine Learning for Business', N'An advanced course applying machine learning techniques to business problems. Topics include feature engineering, ensemble methods, gradient boosting, recommendation systems, and model interpretability. Students implement solutions using Python and cloud-based ML platforms.', N'Business Analytics', N'Business', 400, 4, N'BAN 301'),
  ('Spring27', N'ENG 594: Graduate Seminar in Rhetoric and Composition', N'An advanced seminar examining theories of writing, rhetoric, and literacy. Students explore how writing functions in academic, professional, and public contexts while developing skills in qualitative research methods applicable to writing studies.', N'English', N'Arts & Sciences', 500, 4, N'Graduate standing'),
  ('Spring27', N'SCM 134: Introduction to Strategic Communications', N'An overview of the strategic communications field including public relations, advertising, and integrated marketing communications. Students learn campaign planning, message development, media relations, and the role of communication in organizational strategy.', N'Strategic Communications', N'Communications', 100, 3, NULL),
  ('Spring28', N'WLG 212: Intermediate Spanish', N'A continuation of language study that deepens communicative competence through reading, writing, speaking, and listening activities. Students engage with authentic texts and media from the Spanish-speaking world while expanding grammatical accuracy and cultural understanding.', N'World Languages', N'Arts & Sciences', 200, 3, N'WLG 102 or placement'),
  ('Spring27', N'MEC 438: Finite Element Analysis', N'An advanced course in computational methods for structural and thermal analysis. Students learn the mathematical foundations of the finite element method and apply commercial FEA software to solve complex engineering problems.', N'Mechanical Engineering', N'Engineering', 400, 3, N'MEC 312'),
  ('Winter28', N'CHM 579: Graduate Research in Chemistry', N'Supervised research in an active faculty research lab. Students conduct original research, participate in group meetings, and present progress reports. Culminates in a thesis or publishable manuscript.', N'Chemistry', N'Arts & Sciences', 500, 3, N'Graduate standing'),
  ('Spring27', N'EXS 262: Kinesiology and Biomechanics', N'An analysis of human movement using principles of physics and anatomy. Topics include joint mechanics, muscle function, gait analysis, ergonomics, and injury mechanisms. Students conduct biomechanical analyses using video and motion capture technology.', N'Exercise Science', N'Health Sciences', 200, 3, N'BIO 101 and PHY 101'),
  ('Summer27', N'FIN 425: Senior Capstone in Finance', N'A capstone experience integrating financial theory and practice. Students complete an applied research project or case competition addressing complex financial problems. Develops skills in financial analysis, communication, and professional judgment.', N'Finance', N'Business', 400, 3, N'Senior standing in FIN'),
  ('Winter28', N'NUR 552: Graduate Seminar in Advanced Practice Nursing', N'An advanced seminar exploring the expanding roles of nurse practitioners, clinical nurse specialists, and nurse educators. Topics include advanced health assessment, clinical decision-making, prescriptive authority, and healthcare system leadership.', N'Nursing', N'Health Sciences', 500, 3, N'Graduate standing in nursing'),
  ('Winter27', N'PHL 229: Environmental Ethics', N'A philosophical examination of human relationships with the natural world. Topics include intrinsic value of nature, animal rights, environmental justice, climate change ethics, and sustainability. Students evaluate competing ethical frameworks for environmental decision-making.', N'Philosophy', N'Arts & Sciences', 200, 3, N'PHL 101 or PHL 102'),
  ('Fall26', N'MKT 367: International Marketing', N'An examination of marketing strategy in global markets. Topics include market entry strategies, cross-cultural consumer behavior, global branding, pricing across markets, and distribution in emerging economies.', N'Marketing', N'Business', 300, 3, N'MKT 201'),
  ('Fall27', N'ENG 529: Graduate Seminar in Rhetoric and Composition', N'An advanced seminar examining theories of writing, rhetoric, and literacy. Students explore how writing functions in academic, professional, and public contexts while developing skills in qualitative research methods applicable to writing studies.', N'English', N'Arts & Sciences', 500, 4, N'Graduate standing'),
  ('Fall26', N'ENG 158: English Composition II', N'A continuation of composition skills with emphasis on research-based writing. Students learn to locate, evaluate, and synthesize scholarly sources while developing longer analytical arguments. Topics include rhetorical analysis, information literacy, and documentation practices.', N'English', N'Arts & Sciences', 100, 3, N'ENG 101'),
  ('Spring27', N'PBH 208: Biostatistics', N'An introduction to statistical methods for public health research. Topics include descriptive statistics, probability, sampling distributions, hypothesis testing, regression, and survival analysis. Students use SAS or R to analyze health datasets.', N'Public Health', N'Health Sciences', 200, 2, N'MTH 110'),
  ('Spring27', N'PHY 489: Senior Thesis in Physics', N'Independent research culminating in a written thesis and public presentation. Students work closely with a faculty advisor on an original project in experimental or theoretical physics.', N'Physics', N'Arts & Sciences', 400, 3, N'Senior standing in PHY'),
  ('Winter28', N'HLA 168: Introduction to Health Administration', N'An overview of the U.S. healthcare system including its organization, financing, delivery, and governance. Students explore the roles of hospitals, insurers, government agencies, and public health organizations in healthcare delivery.', N'Health Administration', N'Health Sciences', 100, 3, NULL),
  ('Fall27', N'EED 335: Classroom Management and Community Building', N'A practical course in creating positive, productive classroom environments. Students learn proactive management strategies, restorative practices, culturally responsive approaches, and techniques for building inclusive classroom communities.', N'Elementary Education', N'Education', 300, 3, N'EED 202'),
  ('Winter27', N'CSC 543: Advanced Topics in Machine Learning', N'Graduate-level study of cutting-edge machine learning research including deep reinforcement learning, graph neural networks, federated learning, and large language models. Students read and present current research papers and complete an original research project demonstrating novel application of ML techniques.', N'Computer Science', N'Arts & Sciences', 500, 3, N'CSC 341 and graduate standing'),
  ('Winter28', N'SCM 379: Social Media Strategy', N'An advanced course in developing and executing social media strategies for organizations. Topics include platform selection, content planning, community management, influencer partnerships, paid social advertising, and social media analytics.', N'Strategic Communications', N'Communications', 300, 3, N'SCM 201'),
  ('Fall26', N'EDL 386: School Law and Ethics', N'A study of legal and ethical issues facing school leaders. Topics include student rights, employment law, special education law, First Amendment issues, liability, and ethical decision-making frameworks for educational administrators.', N'Educational Leadership', N'Education', 300, 3, N'EDL 201'),
  ('Winter28', N'ELE 279: Circuit Analysis', N'A study of linear electrical circuits including DC and AC analysis, Kirchhoff''s laws, Thevenin and Norton equivalents, operational amplifiers, and transient response. Laboratory work reinforces analytical techniques with practical circuit construction.', N'Electrical Engineering', N'Engineering', 200, 3, N'PHY 212 and MTH 242'),
  ('Fall26', N'POL 235: Political Research Methods', N'An introduction to empirical research methods in political science including research design, quantitative and qualitative approaches, survey methods, and statistical analysis. Students complete a research project using real political data.', N'Political Science', N'Arts & Sciences', 200, 4, N'POL 101'),
  ('Winter27', N'CSC 518: Advanced Topics in Machine Learning', N'Graduate-level study of cutting-edge machine learning research including deep reinforcement learning, graph neural networks, federated learning, and large language models. Students read and present current research papers and complete an original research project demonstrating novel application of ML techniques.', N'Computer Science', N'Arts & Sciences', 500, 4, N'CSC 341 and graduate standing'),
  ('Winter27', N'PHY 196: General Physics II', N'Continuation of General Physics I covering electricity, magnetism, optics, and modern physics. Topics include electric fields, circuits, electromagnetic waves, geometric optics, and an introduction to quantum phenomena.', N'Physics', N'Arts & Sciences', 100, 3, N'PHY 101'),
  ('Spring27', N'ART 293: Painting I', N'An introduction to painting techniques and concepts. Students work in oil and acrylic to develop skills in color mixing, composition, surface quality, and visual expression. Subjects include still life, landscape, and the figure.', N'Studio Art', N'Fine Arts', 200, 3, N'ART 101'),
  ('Spring28', N'HIS 496: Senior Seminar in History', N'A capstone seminar in which students produce an original research paper based on primary source analysis. Topics vary by semester. Students develop expertise in historical methodology, argumentation, and scholarly writing.', N'History', N'Arts & Sciences', 400, 3, N'HIS 301 and senior standing'),
  ('Fall27', N'MEC 326: Control Systems', N'An introduction to feedback control theory for mechanical systems. Topics include system modeling, transfer functions, stability analysis, root locus, frequency response, and PID controller design. Students design and simulate controllers using MATLAB.', N'Mechanical Engineering', N'Engineering', 300, 3, N'MEC 201 and MTH 302'),
  ('Spring27', N'THR 549: Graduate Seminar in Contemporary Performance', N'An advanced seminar examining experimental and contemporary performance practices. Students engage with devised theatre, performance art, immersive theatre, and interdisciplinary performance while developing original work.', N'Theatre', N'Fine Arts', 500, 3, N'Graduate standing'),
  ('Fall26', N'MUS 361: Composition', N'A creative course in composing music for various ensembles and instruments. Students develop compositional techniques including melody, harmony, counterpoint, orchestration, and formal design while finding their personal artistic voice.', N'Music', N'Fine Arts', 300, 3, N'MUS 201'),
  ('Fall26', N'WLG 124: Elementary Japanese I', N'An introduction to the Japanese language covering hiragana, katakana, and basic kanji. Students develop conversational skills, learn fundamental grammar patterns, and explore Japanese culture including customs, traditions, and daily life.', N'World Languages', N'Arts & Sciences', 100, 3, NULL),
  ('Spring28', N'PSY 268: Developmental Psychology', N'A lifespan approach to human development from conception through aging. Covers physical, cognitive, and psychosocial development with attention to cultural contexts, individual differences, and applications to parenting, education, and healthcare.', N'Psychology', N'Arts & Sciences', 200, 3, N'PSY 101'),
  ('Winter27', N'PSY 167: Psychology of Adjustment', N'An exploration of how individuals cope with life challenges including stress, relationships, career decisions, and mental health. Students apply psychological research to understand personal growth and develop evidence-based strategies for well-being.', N'Psychology', N'Arts & Sciences', 100, 3, NULL),
  ('Spring28', N'SCM 217: Public Relations Writing', N'A practical course in writing for public relations including press releases, media pitches, feature articles, speeches, and social media content. Students develop a professional portfolio demonstrating mastery of various PR writing formats.', N'Strategic Communications', N'Communications', 200, 3, N'SCM 101'),
  ('Winter28', N'EDL 458: Educational Policy and Reform', N'An analysis of education policy at local, state, and federal levels. Students examine policy formation, implementation, and evaluation with attention to equity, accountability, school choice, and the politics of education reform.', N'Educational Leadership', N'Education', 400, 3, N'EDL 301'),
  ('Fall26', N'EED 318: Teaching Mathematics in Elementary Schools', N'A methods course in teaching mathematics to children in grades K-6. Students explore mathematical content knowledge, research-based instructional strategies, manipulative use, problem-solving approaches, and assessment techniques for diverse learners.', N'Elementary Education', N'Education', 300, 3, N'EED 202 and MTH 131'),
  ('Spring27', N'EXS 119: Foundations of Health and Wellness', N'A survey of the dimensions of health and wellness including physical fitness, nutrition, stress management, mental health, substance use, and chronic disease prevention. Students develop a personal wellness plan based on evidence-based guidelines.', N'Exercise Science', N'Health Sciences', 100, 3, NULL),
  ('Spring27', N'ECN 238: Intermediate Microeconomics', N'An advanced treatment of microeconomic theory using mathematical tools. Topics include consumer optimization, firm behavior, market equilibrium, game theory, information economics, and welfare analysis. Students solve optimization problems and analyze market outcomes.', N'Economics', N'Business', 200, 3, N'ECN 101 and MTH 131'),
  ('Spring27', N'SOC 483: Senior Capstone in Sociology', N'A culminating experience in which students complete an independent research project or community-based applied project. Students present their work at the departmental symposium and produce a portfolio reflecting their sociological learning.', N'Sociology', N'Arts & Sciences', 400, 3, N'Senior standing in SOC and SOC 201'),
  ('Spring28', N'CIV 201: Surveying and Geomatics', N'An introduction to land surveying techniques and geospatial data collection. Topics include measuring distances and angles, leveling, GPS surveying, coordinate systems, and GIS applications in civil engineering.', N'Civil Engineering', N'Engineering', 200, 3, N'MTH 241'),
  ('Spring28', N'CHM 271: Organic Chemistry I', N'A systematic study of carbon-based compounds covering nomenclature, stereochemistry, reaction mechanisms, and functional group transformations. Students develop skills in predicting reactivity based on molecular structure and electronic effects.', N'Chemistry', N'Arts & Sciences', 200, 4, N'CHM 102'),
  ('Spring27', N'PHY 207: University Physics II', N'A calculus-based treatment of electromagnetism including electric fields, Gauss''s law, capacitance, DC circuits, magnetic fields, Faraday''s law, and electromagnetic waves. Laboratory emphasizes precision measurement and circuit analysis.', N'Physics', N'Arts & Sciences', 200, 3, N'PHY 211 and MTH 242'),
  ('Spring28', N'HIS 343: Public History', N'An exploration of how history is presented and interpreted outside the academy. Topics include museums, historic preservation, documentary film, digital archives, oral history, and community-based historical projects. Students complete a public history project.', N'History', N'Arts & Sciences', 300, 4, N'HIS 301'),
  ('Spring27', N'WLG 116: Elementary French I', N'An introduction to the French language developing foundational skills in listening, speaking, reading, and writing. Students learn essential vocabulary and grammar while exploring Francophone cultures through films, music, and literature.', N'World Languages', N'Arts & Sciences', 100, 3, NULL),
  ('Fall26', N'HLA 544: Graduate Seminar in Population Health Management', N'An advanced seminar in managing the health of defined populations. Topics include risk stratification, care coordination, social determinants, value-based payment models, and data analytics for population health improvement.', N'Health Administration', N'Health Sciences', 500, 3, N'Graduate standing'),
  ('Winter28', N'BAN 504: Graduate Seminar in Big Data Analytics', N'An advanced seminar in large-scale data processing and analytics. Topics include distributed computing frameworks, real-time stream processing, graph analytics, and building scalable machine learning pipelines. Students work with Spark, Kafka, and cloud data platforms.', N'Business Analytics', N'Business', 500, 3, N'Graduate standing'),
  ('Fall26', N'CTV 539: Graduate Seminar in Digital Storytelling', N'An advanced seminar exploring emerging forms of storytelling including interactive narratives, virtual reality, web series, and transmedia franchises. Students produce original work that pushes the boundaries of traditional screen media.', N'Cinema & Television', N'Communications', 500, 3, N'Graduate standing'),
  ('Fall26', N'MUS 352: Music Technology and Production', N'An introduction to music technology including digital audio workstations, MIDI sequencing, audio recording and mixing, synthesis, and sound design. Students produce original recordings and learn the technical skills used in modern music production.', N'Music', N'Fine Arts', 300, 3, N'MUS 101'),
  ('Summer27', N'BAN 337: Text Analytics and NLP for Business', N'An applied course in extracting insights from unstructured text data. Topics include text preprocessing, sentiment analysis, topic modeling, named entity recognition, and building text classification systems. Applications include customer review analysis, social media monitoring, and document categorization.', N'Business Analytics', N'Business', 300, 3, N'BAN 301 and programming experience'),
  ('Fall26', N'BIO 456: Advanced Genomics and Proteomics', N'A capstone course examining high-throughput technologies for genome and proteome analysis. Topics include next-generation sequencing, transcriptomics, mass spectrometry-based proteomics, and integrative bioinformatics approaches. Students complete a data analysis project using publicly available datasets.', N'Biology', N'Arts & Sciences', 400, 3, N'BIO 311 or BIO 313'),
  ('Winter28', N'ENV 223: Geographic Information Systems', N'An introduction to GIS technology for spatial analysis and mapping. Students learn to collect, manage, analyze, and visualize geographic data using ArcGIS and open-source tools. Applications include environmental monitoring, urban planning, and natural resource management.', N'Environmental Science', N'Arts & Sciences', 200, 3, NULL);
INSERT INTO dbo.CourseCatalog (TermID, CourseTitle, CourseDescription, Department, College, CourseLevel, Credits, Prerequisites)
VALUES
  ('Fall27', N'BIO 193: Human Biology', N'A survey of human biological systems for non-majors. Covers anatomy and physiology of major organ systems, nutrition, immunology, and genetics as they relate to human health and disease. Emphasizes critical evaluation of health claims in the media.', N'Biology', N'Arts & Sciences', 100, 4, NULL),
  ('Winter27', N'JOU 327: Data Journalism', N'An advanced course in using data to find and tell stories. Students learn to obtain public records, analyze datasets using spreadsheets and programming tools, create data visualizations, and produce data-driven investigative reports.', N'Journalism', N'Communications', 300, 3, N'JOU 201 and basic statistics'),
  ('Spring28', N'PBH 112: Introduction to Public Health', N'An overview of public health principles including epidemiology, health promotion, disease prevention, environmental health, and health policy. Students explore how public health systems address population-level health challenges including infectious disease, chronic conditions, and health disparities.', N'Public Health', N'Health Sciences', 100, 3, NULL),
  ('Fall27', N'PSY 166: Introduction to Psychology', N'A survey of the major areas of psychological science including cognition, development, social behavior, personality, psychopathology, and neuroscience. Students learn to evaluate psychological claims using scientific evidence and critical thinking skills.', N'Psychology', N'Arts & Sciences', 100, 3, NULL),
  ('Spring28', N'BAN 535: Graduate Seminar in Big Data Analytics', N'An advanced seminar in large-scale data processing and analytics. Topics include distributed computing frameworks, real-time stream processing, graph analytics, and building scalable machine learning pipelines. Students work with Spark, Kafka, and cloud data platforms.', N'Business Analytics', N'Business', 500, 3, N'Graduate standing'),
  ('Fall27', N'EXS 395: Clinical Exercise Physiology', N'A study of exercise prescription for individuals with chronic diseases and special conditions including cardiovascular disease, diabetes, obesity, pulmonary disease, and musculoskeletal disorders. Prepares students for clinical exercise testing certification.', N'Exercise Science', N'Health Sciences', 300, 3, N'EXS 211'),
  ('Spring28', N'THR 144: Acting I', N'A foundational course in acting technique emphasizing relaxation, concentration, imagination, sensory work, and improvisation. Students develop skills in physical and vocal expression through exercises, scene work, and performance projects.', N'Theatre', N'Fine Arts', 100, 2, NULL),
  ('Fall27', N'MEC 165: Introduction to Engineering', N'A broad introduction to engineering disciplines and the engineering design process. Students work in teams to solve open-ended design challenges using computer-aided design tools, prototyping, and iterative testing. Develops creative problem-solving and communication skills.', N'Mechanical Engineering', N'Engineering', 100, 4, NULL),
  ('Spring28', N'EXS 338: Clinical Exercise Physiology', N'A study of exercise prescription for individuals with chronic diseases and special conditions including cardiovascular disease, diabetes, obesity, pulmonary disease, and musculoskeletal disorders. Prepares students for clinical exercise testing certification.', N'Exercise Science', N'Health Sciences', 300, 2, N'EXS 211'),
  ('Summer27', N'MKT 392: Marketing Analytics', N'An applied course in using data to inform marketing decisions. Students learn statistical modeling, customer segmentation, predictive analytics, A/B testing, and attribution modeling. Uses R and marketing analytics platforms on real datasets.', N'Marketing', N'Business', 300, 3, N'MKT 203 and MTH 110'),
  ('Summer28', N'MEC 353: Machine Design', N'An applied course in designing mechanical components and systems. Topics include stress analysis, fatigue, bearings, gears, shafts, springs, and bolted connections. Students use CAD software and finite element analysis to design and optimize components.', N'Mechanical Engineering', N'Engineering', 300, 3, N'MEC 201 and MEC 203'),
  ('Fall27', N'MKT 359: International Marketing', N'An examination of marketing strategy in global markets. Topics include market entry strategies, cross-cultural consumer behavior, global branding, pricing across markets, and distribution in emerging economies.', N'Marketing', N'Business', 300, 3, N'MKT 201'),
  ('Summer27', N'MUS 311: World Music', N'A comparative study of musical traditions from Africa, Asia, Latin America, and indigenous cultures. Students explore the social functions of music, instruments and performance practices, and the impact of globalization on world music traditions.', N'Music', N'Fine Arts', 300, 3, N'MUS 102 or MUS 201'),
  ('Fall26', N'CPE 331: VLSI Design', N'An introduction to the design of very large scale integrated circuits. Topics include CMOS logic design, layout, verification, timing analysis, and low-power techniques. Students design and simulate circuits using industry CAD tools.', N'Computer Engineering', N'Engineering', 300, 3, N'ELE 202'),
  ('Spring27', N'MTH 449: Mathematical Modeling', N'Students develop and analyze mathematical models of real-world phenomena from biology, economics, physics, and engineering. Techniques include differential equations, optimization, simulation, and dimensional analysis. Team projects involve formulating problems, building models, and validating results against data.', N'Mathematics', N'Arts & Sciences', 400, 4, N'MTH 302 or MTH 341'),
  ('Spring27', N'BAN 289: Data Management for Business', N'A practical course in managing and querying business data. Students learn relational database concepts, SQL query writing, data cleaning and transformation techniques, and basic data warehousing principles. Applications focus on marketing, finance, and operations datasets.', N'Business Analytics', N'Business', 200, 3, N'BAN 101'),
  ('Fall26', N'PBH 119: Introduction to Public Health', N'An overview of public health principles including epidemiology, health promotion, disease prevention, environmental health, and health policy. Students explore how public health systems address population-level health challenges including infectious disease, chronic conditions, and health disparities.', N'Public Health', N'Health Sciences', 100, 3, NULL),
  ('Fall26', N'HIS 357: History of the American South', N'An examination of the American South from colonial settlement to the present. Topics include plantation society, the Civil War and Reconstruction, the New South, civil rights activism, and contemporary southern identity. Explores race, class, and gender as analytical categories.', N'History', N'Arts & Sciences', 300, 4, N'One 200-level HIS course'),
  ('Winter28', N'CPE 315: VLSI Design', N'An introduction to the design of very large scale integrated circuits. Topics include CMOS logic design, layout, verification, timing analysis, and low-power techniques. Students design and simulate circuits using industry CAD tools.', N'Computer Engineering', N'Engineering', 300, 4, N'ELE 202'),
  ('Summer28', N'THR 331: Playwriting', N'A workshop course in dramatic writing. Students study dramatic structure, create original short and full-length plays, participate in peer critique, and hear their work read by student actors. Explores diverse storytelling traditions and voices.', N'Theatre', N'Fine Arts', 300, 3, N'THR 101 or ENG 211'),
  ('Spring27', N'PHL 371: Ethics of Artificial Intelligence', N'A philosophical examination of ethical issues raised by artificial intelligence and autonomous systems. Topics include algorithmic bias, accountability for AI decisions, privacy, the future of work, machine consciousness, and the alignment problem in advanced AI systems.', N'Philosophy', N'Arts & Sciences', 300, 3, N'PHL 102 or CSC 131'),
  ('Fall27', N'ACC 122: Principles of Financial Accounting', N'An introduction to the fundamental concepts and practices of financial accounting. Topics include the accounting cycle, financial statement preparation, revenue recognition, asset valuation, and analysis of financial reports. Students develop skills in recording and interpreting business transactions.', N'Accounting', N'Business', 100, 3, NULL),
  ('Winter28', N'CSC 228: Introduction to Web Development', N'A practical course covering full-stack web development fundamentals. Students build interactive web applications using HTML, CSS, JavaScript, and server-side frameworks. Topics include RESTful API design, responsive layouts, and basic deployment practices.', N'Computer Science', N'Arts & Sciences', 200, 3, N'CSC 131'),
  ('Spring28', N'FIN 443: Investment Banking and Valuation', N'An advanced course in corporate valuation and investment banking practices. Topics include DCF analysis, comparable company analysis, LBO modeling, M&A processes, and IPO structuring. Students complete a comprehensive valuation project.', N'Finance', N'Business', 400, 3, N'FIN 301'),
  ('Spring28', N'MGT 442: Negotiations and Conflict Resolution', N'An advanced experiential course in negotiation theory and practice. Students participate in simulated negotiations, analyze bargaining strategies, and develop skills in mediation and dispute resolution applicable to business, legal, and interpersonal contexts.', N'Management', N'Business', 400, 3, N'MGT 201'),
  ('Spring27', N'CSC 482: Database Administration and Performance', N'Advanced topics in database management including query plan analysis, index tuning, replication, high availability configurations, and disaster recovery planning. Students work with enterprise database systems to diagnose performance bottlenecks and implement optimization strategies.', N'Computer Science', N'Arts & Sciences', 400, 3, N'CSC 236'),
  ('Fall27', N'SOC 318: Urban Sociology', N'A study of cities and urban life from sociological perspectives. Topics include urbanization, spatial inequality, gentrification, neighborhood effects, immigration and urban diversity, community organizing, and urban policy. Includes a community-based research component.', N'Sociology', N'Arts & Sciences', 300, 3, N'SOC 201'),
  ('Fall26', N'SCM 393: Crisis Communications', N'An examination of communication strategies during organizational crises. Students analyze real crisis cases, develop crisis communication plans, conduct media training exercises, and learn to manage reputation in the social media age.', N'Strategic Communications', N'Communications', 300, 3, N'SCM 201'),
  ('Winter28', N'MGT 392: Operations Management', N'A study of how organizations design, operate, and improve production systems. Topics include process analysis, quality management, inventory control, supply chain management, lean operations, and capacity planning. Students apply analytical tools to real operational challenges.', N'Management', N'Business', 300, 3, N'MGT 101 and MTH 110'),
  ('Fall26', N'POL 404: Senior Seminar in Political Science', N'A capstone seminar requiring original research on a topic of the student''s choosing. Students develop a research question, conduct systematic analysis using appropriate methods, and produce a scholarly paper suitable for presentation at an academic conference.', N'Political Science', N'Arts & Sciences', 400, 3, N'POL 202 and senior standing'),
  ('Spring27', N'MTH 223: Linear Algebra', N'A study of vector spaces, linear transformations, matrices, determinants, eigenvalues, and eigenvectors. Applications include systems of linear equations, least-squares approximation, and Markov chains. This course provides essential mathematical foundations for machine learning, data science, and engineering.', N'Mathematics', N'Arts & Sciences', 200, 3, N'MTH 241'),
  ('Spring28', N'MTH 164: College Algebra', N'A foundational course covering algebraic concepts including linear and quadratic equations, polynomial functions, rational expressions, and systems of equations. Emphasizes analytical thinking and problem-solving techniques that prepare students for calculus and quantitative reasoning across disciplines.', N'Mathematics', N'Arts & Sciences', 100, 3, NULL),
  ('Spring28', N'ACC 355: Federal Income Taxation', N'A comprehensive study of the federal income tax system for individuals and businesses. Topics include gross income, deductions, credits, property transactions, and tax planning strategies. Students prepare tax returns and analyze tax policy implications.', N'Accounting', N'Business', 300, 3, N'ACC 211'),
  ('Spring27', N'BIO 281: Cell Biology', N'An in-depth study of eukaryotic cell structure and function. Topics include membrane biology, intracellular trafficking, signal transduction, cytoskeleton dynamics, and cell division. Students analyze primary research literature and develop scientific communication skills.', N'Biology', N'Arts & Sciences', 200, 4, N'BIO 101 and CHM 101'),
  ('Fall27', N'ENG 307: Technical and Professional Writing', N'A practical course in writing for professional contexts including reports, proposals, instructions, and digital content. Students learn document design principles, audience analysis, usability testing, and collaborative writing strategies used in workplace environments.', N'English', N'Arts & Sciences', 300, 3, N'ENG 102'),
  ('Spring28', N'BIO 146: Human Biology', N'A survey of human biological systems for non-majors. Covers anatomy and physiology of major organ systems, nutrition, immunology, and genetics as they relate to human health and disease. Emphasizes critical evaluation of health claims in the media.', N'Biology', N'Arts & Sciences', 100, 4, NULL),
  ('Fall26', N'BIO 435: Senior Research in Biology', N'An independent research project conducted under faculty mentorship. Students design experiments, collect and analyze data, and present findings in both written and oral formats following scientific conventions. Develops skills essential for graduate study and careers in research.', N'Biology', N'Arts & Sciences', 400, 3, N'Senior standing in BIO and faculty approval'),
  ('Winter28', N'CIV 238: Mechanics of Materials', N'A study of the behavior of solid materials under various loading conditions. Topics include stress, strain, beam deflection, torsion, column buckling, and material failure theories. Applications to structural engineering design.', N'Civil Engineering', N'Engineering', 200, 3, N'MEC 201'),
  ('Summer27', N'MGT 339: Operations Management', N'A study of how organizations design, operate, and improve production systems. Topics include process analysis, quality management, inventory control, supply chain management, lean operations, and capacity planning. Students apply analytical tools to real operational challenges.', N'Management', N'Business', 300, 3, N'MGT 101 and MTH 110'),
  ('Spring28', N'PHL 304: Ethics of Artificial Intelligence', N'A philosophical examination of ethical issues raised by artificial intelligence and autonomous systems. Topics include algorithmic bias, accountability for AI decisions, privacy, the future of work, machine consciousness, and the alignment problem in advanced AI systems.', N'Philosophy', N'Arts & Sciences', 300, 3, N'PHL 102 or CSC 131'),
  ('Fall27', N'ELE 206: Circuit Analysis', N'A study of linear electrical circuits including DC and AC analysis, Kirchhoff''s laws, Thevenin and Norton equivalents, operational amplifiers, and transient response. Laboratory work reinforces analytical techniques with practical circuit construction.', N'Electrical Engineering', N'Engineering', 200, 3, N'PHY 212 and MTH 242'),
  ('Spring27', N'CSC 142: Introduction to Computer Science', N'An introductory exploration of computational thinking and problem-solving. Students learn fundamental programming concepts including variables, control structures, and functions using Python. Topics include algorithm design, data representation, and the social implications of computing technology.', N'Computer Science', N'Arts & Sciences', 100, 3, NULL),
  ('Winter27', N'HIS 471: Senior Seminar in History', N'A capstone seminar in which students produce an original research paper based on primary source analysis. Topics vary by semester. Students develop expertise in historical methodology, argumentation, and scholarly writing.', N'History', N'Arts & Sciences', 400, 3, N'HIS 301 and senior standing'),
  ('Fall26', N'PSY 139: Psychology of Adjustment', N'An exploration of how individuals cope with life challenges including stress, relationships, career decisions, and mental health. Students apply psychological research to understand personal growth and develop evidence-based strategies for well-being.', N'Psychology', N'Arts & Sciences', 100, 3, NULL),
  ('Spring27', N'BAN 112: Introduction to Business Analytics', N'An overview of how organizations use data to drive decision-making. Topics include descriptive analytics, data visualization, basic statistical analysis, and an introduction to predictive modeling. Students work with real business datasets using Excel and Tableau.', N'Business Analytics', N'Business', 100, 3, NULL),
  ('Spring28', N'SPE 411: Advanced Practicum in Special Education', N'A culminating clinical experience in which students plan and deliver instruction to students with disabilities in school settings. Includes assessment, IEP implementation, collaboration with general educators, and reflective practice.', N'Special Education', N'Education', 400, 3, N'Senior standing in SPE'),
  ('Fall26', N'JOU 245: News Writing and Reporting', N'A practical course in news writing for digital and print media. Students learn to write leads, conduct interviews, cover beats, and produce stories on deadline. Emphasizes accuracy, fairness, AP style, and multimedia storytelling.', N'Journalism', N'Communications', 200, 3, N'JOU 101'),
  ('Spring27', N'ACC 256: Intermediate Accounting II', N'Continuation of Intermediate Accounting I covering accounting for liabilities, stockholders'' equity, investments, leases, pensions, income taxes, and cash flow statements. Emphasizes analysis of complex transactions and financial statement presentation.', N'Accounting', N'Business', 200, 4, N'ACC 211'),
  ('Fall26', N'SCM 233: Public Relations Writing', N'A practical course in writing for public relations including press releases, media pitches, feature articles, speeches, and social media content. Students develop a professional portfolio demonstrating mastery of various PR writing formats.', N'Strategic Communications', N'Communications', 200, 3, N'SCM 101'),
  ('Fall26', N'CPE 328: Operating System Design', N'An examination of operating system internals with emphasis on implementation. Topics include process scheduling, memory management, file systems, device drivers, and system calls. Students implement kernel modules in a Unix-like environment.', N'Computer Engineering', N'Engineering', 300, 3, N'CPE 211 and CSC 231');
INSERT INTO dbo.CourseCatalog (TermID, CourseTitle, CourseDescription, Department, College, CourseLevel, Credits, Prerequisites)
VALUES
  ('Fall26', N'CTV 154: Introduction to Television Production', N'A hands-on introduction to television production techniques including camera operation, lighting, audio recording, directing, and non-linear editing. Students produce short-form video projects across multiple genres.', N'Cinema & Television', N'Communications', 100, 3, NULL),
  ('Winter27', N'SCM 212: Public Relations Writing', N'A practical course in writing for public relations including press releases, media pitches, feature articles, speeches, and social media content. Students develop a professional portfolio demonstrating mastery of various PR writing formats.', N'Strategic Communications', N'Communications', 200, 3, N'SCM 101'),
  ('Spring27', N'PSY 391: Industrial-Organizational Psychology', N'Application of psychological principles to workplace settings. Topics include employee selection, training, performance evaluation, motivation, leadership, team dynamics, and organizational culture. Students conduct applied projects addressing real organizational challenges.', N'Psychology', N'Arts & Sciences', 300, 3, N'PSY 201 and PSY 211'),
  ('Spring27', N'POL 214: Comparative Politics', N'A comparative study of political systems across democratic and authoritarian regimes. Topics include regime types, electoral systems, political parties, civil society, economic development, and democratization. Case studies draw from Europe, Latin America, Africa, and Asia.', N'Political Science', N'Arts & Sciences', 200, 3, N'POL 101 or POL 102'),
  ('Fall26', N'MGT 245: Organizational Behavior', N'A study of human behavior in organizational settings. Topics include motivation, group dynamics, communication, conflict resolution, organizational culture, power and politics, and leadership theories. Students apply behavioral concepts through case analyses and simulations.', N'Management', N'Business', 200, 3, N'MGT 101'),
  ('Spring27', N'ENG 279: World Literature', N'A comparative study of literary traditions from Africa, Asia, Latin America, the Middle East, and Europe. Students read works in translation and explore themes of identity, migration, colonialism, and cultural exchange across global literary traditions.', N'English', N'Arts & Sciences', 200, 2, N'ENG 103'),
  ('Fall26', N'ELE 313: Electronics', N'A study of semiconductor devices and electronic circuit design. Topics include diodes, transistors (BJT and MOSFET), amplifier design, frequency response, feedback, and operational amplifier circuits.', N'Electrical Engineering', N'Engineering', 300, 3, N'ELE 201'),
  ('Fall26', N'PHY 233: University Physics I', N'A calculus-based treatment of classical mechanics including kinematics, dynamics, work-energy theorems, conservation laws, rigid body motion, and oscillations. Designed for physics and engineering majors.', N'Physics', N'Arts & Sciences', 200, 3, N'MTH 241 or concurrent enrollment'),
  ('Spring27', N'HIS 215: History of Science and Technology', N'An exploration of how scientific knowledge and technological innovation have shaped human societies. Topics include the Scientific Revolution, industrialization, the atomic age, the digital revolution, and ethical debates surrounding emerging technologies.', N'History', N'Arts & Sciences', 200, 3, NULL),
  ('Summer28', N'BIO 238: Microbiology', N'A study of the biology of microorganisms including bacteria, viruses, fungi, and protists. Covers microbial structure, metabolism, genetics, pathogenesis, and immunological responses. Laboratory work includes aseptic technique, staining, culturing, and identification methods.', N'Biology', N'Arts & Sciences', 200, 3, N'BIO 101 and CHM 102'),
  ('Spring28', N'PHY 352: Quantum Mechanics', N'A rigorous treatment of quantum theory including the Schrodinger equation, angular momentum, spin, perturbation theory, and the hydrogen atom. Students develop mathematical and conceptual tools for understanding quantum phenomena in atoms, molecules, and solids.', N'Physics', N'Arts & Sciences', 300, 3, N'PHY 221 and MTH 302'),
  ('Fall26', N'MTH 297: Calculus I', N'The first course in a three-semester calculus sequence. Topics include limits, continuity, differentiation of algebraic and transcendental functions, and applications of derivatives including optimization and related rates. Emphasizes both computational techniques and conceptual understanding.', N'Mathematics', N'Arts & Sciences', 200, 4, N'MTH 151 or placement'),
  ('Fall26', N'ART 463: Senior Exhibition', N'A capstone course in which students develop and present a cohesive body of work in a professional exhibition. Students write an artist statement, install their work, and participate in a public critique and reception.', N'Studio Art', N'Fine Arts', 400, 3, N'Senior standing in ART'),
  ('Winter27', N'MGT 148: Introduction to Entrepreneurship', N'An exploration of the entrepreneurial mindset and new venture creation. Students learn to identify opportunities, develop business models, conduct market analysis, and pitch ideas. Includes case studies of successful startups and social enterprises.', N'Management', N'Business', 100, 3, NULL),
  ('Fall27', N'PSY 235: Biological Psychology', N'A study of the biological bases of behavior including neuroanatomy, neurotransmitter systems, sensory processing, motivation, emotion, learning, and psychopharmacology. Bridges neuroscience and psychological perspectives on mind-brain relationships.', N'Psychology', N'Arts & Sciences', 200, 2, N'PSY 101'),
  ('Fall27', N'SPE 202: Behavior Support and Intervention', N'A practical course in understanding and addressing challenging behaviors in educational settings. Students learn functional behavior assessment, positive behavior interventions, de-escalation strategies, and ethical considerations in behavior management.', N'Special Education', N'Education', 200, 3, N'SPE 101'),
  ('Spring27', N'WLG 284: Intermediate French', N'A continuation that develops communicative competence through engagement with authentic French and Francophone texts, films, and media. Students expand grammatical range and cultural knowledge while developing skills for academic and professional use.', N'World Languages', N'Arts & Sciences', 200, 3, N'WLG 112 or placement'),
  ('Fall27', N'PBH 407: Senior Capstone in Public Health', N'A culminating experience integrating public health knowledge and skills through a practicum with a community health organization. Students design, implement, and evaluate a health program or research project under professional mentorship.', N'Public Health', N'Health Sciences', 400, 4, N'Senior standing in PBH'),
  ('Fall27', N'ART 276: Photography I', N'An introduction to photography as an art form. Students learn camera operations, digital workflow, composition, lighting, and post-processing techniques while developing a personal artistic vision through photo-based projects.', N'Studio Art', N'Fine Arts', 200, 3, NULL),
  ('Spring27', N'CIV 243: Surveying and Geomatics', N'An introduction to land surveying techniques and geospatial data collection. Topics include measuring distances and angles, leveling, GPS surveying, coordinate systems, and GIS applications in civil engineering.', N'Civil Engineering', N'Engineering', 200, 4, N'MTH 241'),
  ('Winter27', N'CSC 441: Deep Learning and Neural Networks', N'An advanced course covering deep neural network architectures including convolutional networks, recurrent networks, attention mechanisms, and generative models. Students train models using PyTorch on GPU hardware and explore applications in computer vision, natural language processing, and time series prediction.', N'Computer Science', N'Arts & Sciences', 400, 3, N'CSC 341'),
  ('Winter28', N'CTV 333: Directing for Screen', N'An advanced production course focusing on the art and craft of directing. Students work with actors, plan shot compositions, manage production teams, and direct short narrative films. Covers both technical skills and the director''s creative vision.', N'Cinema & Television', N'Communications', 300, 3, N'CTV 102 and CTV 211'),
  ('Fall27', N'CHM 249: Organic Chemistry II', N'Continuation of Organic Chemistry I with emphasis on advanced reaction mechanisms, synthesis strategies, aromatic chemistry, and spectroscopic identification methods including NMR, IR, and mass spectrometry.', N'Chemistry', N'Arts & Sciences', 200, 3, N'CHM 201'),
  ('Summer28', N'ARH 337: Museum Studies', N'A practical course in museum theory and practice. Topics include collection management, exhibition design, interpretation, conservation ethics, and the evolving role of museums in society. Includes field experiences at local and regional museums.', N'Art History', N'Fine Arts', 300, 2, N'One 200-level ARH course'),
  ('Summer28', N'MGT 123: Introduction to Entrepreneurship', N'An exploration of the entrepreneurial mindset and new venture creation. Students learn to identify opportunities, develop business models, conduct market analysis, and pitch ideas. Includes case studies of successful startups and social enterprises.', N'Management', N'Business', 100, 4, NULL),
  ('Spring28', N'PHL 251: Philosophy of Mind', N'An examination of fundamental questions about the nature of consciousness, mental representation, personal identity, and the relationship between mind and body. Students explore classic positions and engage with contemporary debates informed by neuroscience and artificial intelligence.', N'Philosophy', N'Arts & Sciences', 200, 3, N'PHL 101'),
  ('Summer28', N'THR 593: Graduate Seminar in Contemporary Performance', N'An advanced seminar examining experimental and contemporary performance practices. Students engage with devised theatre, performance art, immersive theatre, and interdisciplinary performance while developing original work.', N'Theatre', N'Fine Arts', 500, 3, N'Graduate standing'),
  ('Spring28', N'CIV 279: Mechanics of Materials', N'A study of the behavior of solid materials under various loading conditions. Topics include stress, strain, beam deflection, torsion, column buckling, and material failure theories. Applications to structural engineering design.', N'Civil Engineering', N'Engineering', 200, 3, N'MEC 201'),
  ('Fall26', N'ACC 104: Principles of Financial Accounting', N'An introduction to the fundamental concepts and practices of financial accounting. Topics include the accounting cycle, financial statement preparation, revenue recognition, asset valuation, and analysis of financial reports. Students develop skills in recording and interpreting business transactions.', N'Accounting', N'Business', 100, 3, NULL),
  ('Fall27', N'NUR 206: Pathophysiology', N'A study of the physiological changes associated with disease processes across the lifespan. Topics include cellular injury, inflammation, immune dysfunction, cardiovascular disease, endocrine disorders, and neurological conditions.', N'Nursing', N'Health Sciences', 200, 3, N'NUR 102'),
  ('Spring28', N'NUR 553: Graduate Seminar in Advanced Practice Nursing', N'An advanced seminar exploring the expanding roles of nurse practitioners, clinical nurse specialists, and nurse educators. Topics include advanced health assessment, clinical decision-making, prescriptive authority, and healthcare system leadership.', N'Nursing', N'Health Sciences', 500, 3, N'Graduate standing in nursing'),
  ('Fall26', N'ACC 322: Accounting Information Systems', N'An examination of how information technology supports accounting functions. Topics include database design for accounting applications, internal controls for IT systems, enterprise resource planning, data analytics, and cybersecurity considerations in financial reporting.', N'Accounting', N'Business', 300, 2, N'ACC 211 and CSC 131 or BAN 201'),
  ('Summer28', N'MEC 357: Fluid Mechanics', N'A study of fluid behavior and its engineering applications. Topics include fluid statics, conservation laws, Bernoulli equation, viscous flow, pipe systems, boundary layers, and an introduction to computational fluid dynamics.', N'Mechanical Engineering', N'Engineering', 300, 3, N'MEC 201 and MTH 302'),
  ('Spring27', N'CPE 353: VLSI Design', N'An introduction to the design of very large scale integrated circuits. Topics include CMOS logic design, layout, verification, timing analysis, and low-power techniques. Students design and simulate circuits using industry CAD tools.', N'Computer Engineering', N'Engineering', 300, 3, N'ELE 202'),
  ('Spring27', N'PSY 376: Industrial-Organizational Psychology', N'Application of psychological principles to workplace settings. Topics include employee selection, training, performance evaluation, motivation, leadership, team dynamics, and organizational culture. Students conduct applied projects addressing real organizational challenges.', N'Psychology', N'Arts & Sciences', 300, 3, N'PSY 201 and PSY 211'),
  ('Fall27', N'ENG 296: World Literature', N'A comparative study of literary traditions from Africa, Asia, Latin America, the Middle East, and Europe. Students read works in translation and explore themes of identity, migration, colonialism, and cultural exchange across global literary traditions.', N'English', N'Arts & Sciences', 200, 3, N'ENG 103'),
  ('Spring28', N'POL 365: International Political Economy', N'An analysis of the intersection of politics and economics in the global arena. Topics include international trade, monetary systems, development, inequality, multinational corporations, and the politics of globalization.', N'Political Science', N'Arts & Sciences', 300, 3, N'POL 102 or ECN 201'),
  ('Fall26', N'ARH 207: Asian Art and Architecture', N'A survey of the visual arts of East Asia, South Asia, and Southeast Asia from ancient times to the present. Students explore the religious, philosophical, and cultural contexts of art and architecture across diverse Asian traditions.', N'Art History', N'Fine Arts', 200, 3, NULL),
  ('Winter27', N'CIV 254: Environmental Engineering', N'An introduction to environmental engineering principles including water and wastewater treatment, air quality, solid waste management, and environmental impact assessment. Students analyze engineering solutions for environmental protection.', N'Civil Engineering', N'Engineering', 200, 3, N'CHM 101 and MTH 242'),
  ('Spring28', N'EXS 226: Kinesiology and Biomechanics', N'An analysis of human movement using principles of physics and anatomy. Topics include joint mechanics, muscle function, gait analysis, ergonomics, and injury mechanisms. Students conduct biomechanical analyses using video and motion capture technology.', N'Exercise Science', N'Health Sciences', 200, 3, N'BIO 101 and PHY 101'),
  ('Spring27', N'BIO 253: Cell Biology', N'An in-depth study of eukaryotic cell structure and function. Topics include membrane biology, intracellular trafficking, signal transduction, cytoskeleton dynamics, and cell division. Students analyze primary research literature and develop scientific communication skills.', N'Biology', N'Arts & Sciences', 200, 3, N'BIO 101 and CHM 101'),
  ('Fall26', N'EXS 158: Foundations of Health and Wellness', N'A survey of the dimensions of health and wellness including physical fitness, nutrition, stress management, mental health, substance use, and chronic disease prevention. Students develop a personal wellness plan based on evidence-based guidelines.', N'Exercise Science', N'Health Sciences', 100, 4, NULL),
  ('Winter27', N'CSC 216: Database Systems Fundamentals', N'Introduction to relational database concepts including entity-relationship modeling, normalization, and SQL query writing. Students design and implement databases, write complex queries involving joins and subqueries, and explore indexing strategies for query optimization.', N'Computer Science', N'Arts & Sciences', 200, 3, N'CSC 131'),
  ('Winter28', N'SOC 207: Research Methods in Sociology', N'An introduction to qualitative and quantitative research methods in sociology. Topics include survey design, interviewing, ethnography, content analysis, and statistical techniques. Students design and execute a small-scale research project.', N'Sociology', N'Arts & Sciences', 200, 3, N'SOC 101'),
  ('Summer28', N'JOU 268: Photojournalism', N'A course in visual storytelling through photography. Students learn composition, lighting, and digital editing techniques while developing the ability to capture news events and human interest stories through compelling images.', N'Journalism', N'Communications', 200, 3, N'JOU 101'),
  ('Spring27', N'MKT 274: Consumer Behavior', N'An examination of how individuals and groups make purchasing decisions. Topics include motivation, perception, learning, attitude formation, cultural influences, and the decision-making process. Students apply behavioral insights to marketing strategy development.', N'Marketing', N'Business', 200, 3, N'MKT 101'),
  ('Fall26', N'PSY 505: Graduate Seminar in Cognitive Science', N'An interdisciplinary seminar exploring the intersection of psychology, neuroscience, computer science, and philosophy in understanding the mind. Students examine current debates about consciousness, artificial intelligence, and embodied cognition.', N'Psychology', N'Arts & Sciences', 500, 4, N'Graduate standing'),
  ('Summer28', N'CSC 316: Operating Systems', N'An examination of operating system design principles including process management, memory allocation, file systems, and concurrency. Students explore scheduling algorithms, virtual memory, deadlock prevention, and implement system-level programs that interact with OS services.', N'Computer Science', N'Arts & Sciences', 300, 3, N'CSC 231'),
  ('Fall26', N'ENG 219: Creative Writing: Fiction', N'A workshop-based course in short fiction writing. Students produce original stories, participate in peer critique sessions, and study published works as models for craft elements including characterization, plot structure, point of view, and dialogue.', N'English', N'Arts & Sciences', 200, 4, N'ENG 101'),
  ('Fall27', N'CHM 198: General Chemistry I', N'Introduction to the fundamental principles of chemistry including atomic structure, chemical bonding, stoichiometry, thermochemistry, and gas laws. Laboratory work develops quantitative measurement skills, safety practices, and scientific reasoning.', N'Chemistry', N'Arts & Sciences', 100, 4, NULL);
INSERT INTO dbo.CourseCatalog (TermID, CourseTitle, CourseDescription, Department, College, CourseLevel, Credits, Prerequisites)
VALUES
  ('Spring27', N'THR 527: Graduate Seminar in Contemporary Performance', N'An advanced seminar examining experimental and contemporary performance practices. Students engage with devised theatre, performance art, immersive theatre, and interdisciplinary performance while developing original work.', N'Theatre', N'Fine Arts', 500, 3, N'Graduate standing'),
  ('Spring27', N'PSY 337: Industrial-Organizational Psychology', N'Application of psychological principles to workplace settings. Topics include employee selection, training, performance evaluation, motivation, leadership, team dynamics, and organizational culture. Students conduct applied projects addressing real organizational challenges.', N'Psychology', N'Arts & Sciences', 300, 2, N'PSY 201 and PSY 211'),
  ('Spring28', N'THR 385: Directing', N'A study of the art and practice of theatrical direction. Topics include script analysis, concept development, staging, working with actors, and production management. Students direct scenes and one-act plays for public performance.', N'Theatre', N'Fine Arts', 300, 3, N'THR 102 and THR 211'),
  ('Winter27', N'HLA 307: Healthcare Law and Regulatory Compliance', N'An examination of the legal and regulatory environment of healthcare. Topics include HIPAA, fraud and abuse laws, medical malpractice, informed consent, accreditation, and regulatory compliance programs.', N'Health Administration', N'Health Sciences', 300, 3, N'HLA 101'),
  ('Spring28', N'CIV 321: Geotechnical Engineering', N'A study of soil mechanics and foundation engineering. Topics include soil classification, effective stress, seepage, consolidation, shear strength, bearing capacity, and slope stability analysis.', N'Civil Engineering', N'Engineering', 300, 4, N'CIV 201 and geology course'),
  ('Fall26', N'MGT 298: Business Ethics', N'An examination of ethical issues in business practice. Topics include corporate social responsibility, stakeholder theory, ethical decision-making frameworks, whistleblowing, environmental sustainability, and ethics in global business operations.', N'Management', N'Business', 200, 1, N'MGT 101'),
  ('Winter27', N'HIS 342: Historical Research Methods', N'A hands-on course in the methods and practices of historical research. Students learn to locate and evaluate primary sources, construct historical arguments, navigate archives, and write research papers that meet professional standards in the discipline.', N'History', N'Arts & Sciences', 300, 3, N'Two 200-level HIS courses'),
  ('Spring27', N'CTV 368: Film Theory and Criticism', N'An examination of major theoretical approaches to cinema including auteur theory, genre theory, feminist film theory, psychoanalytic criticism, and postcolonial perspectives. Students write critical essays analyzing films through theoretical frameworks.', N'Cinema & Television', N'Communications', 300, 3, N'CTV 101'),
  ('Winter27', N'EED 387: Classroom Management and Community Building', N'A practical course in creating positive, productive classroom environments. Students learn proactive management strategies, restorative practices, culturally responsive approaches, and techniques for building inclusive classroom communities.', N'Elementary Education', N'Education', 300, 4, N'EED 202'),
  ('Spring27', N'ENG 428: Advanced Creative Writing', N'An advanced workshop for students committed to developing their literary craft. Students produce a portfolio of polished work in their chosen genre, engage with visiting writers, and explore the contemporary publishing landscape.', N'English', N'Arts & Sciences', 400, 3, N'ENG 211 or ENG 212'),
  ('Summer27', N'MTH 235: Calculus II', N'Continuation of Calculus I covering integration techniques, applications of the definite integral, sequences, series, and Taylor polynomials. Students develop skills in analytical problem-solving and mathematical reasoning that serve as a foundation for advanced mathematics and scientific applications.', N'Mathematics', N'Arts & Sciences', 200, 3, N'MTH 241'),
  ('Fall26', N'CIV 212: Mechanics of Materials', N'A study of the behavior of solid materials under various loading conditions. Topics include stress, strain, beam deflection, torsion, column buckling, and material failure theories. Applications to structural engineering design.', N'Civil Engineering', N'Engineering', 200, 3, N'MEC 201'),
  ('Fall27', N'MUS 194: Introduction to Music', N'A survey of music for non-majors exploring diverse genres, styles, and historical periods. Students develop active listening skills and learn to articulate their responses to music through guided analysis of representative works.', N'Music', N'Fine Arts', 100, 3, NULL),
  ('Spring28', N'ELE 387: Power Systems', N'A study of electric power generation, transmission, and distribution. Topics include three-phase systems, transformers, synchronous generators, power flow analysis, stability, and an introduction to renewable energy integration.', N'Electrical Engineering', N'Engineering', 300, 3, N'ELE 201'),
  ('Spring28', N'MEC 474: Finite Element Analysis', N'An advanced course in computational methods for structural and thermal analysis. Students learn the mathematical foundations of the finite element method and apply commercial FEA software to solve complex engineering problems.', N'Mechanical Engineering', N'Engineering', 400, 4, N'MEC 312'),
  ('Spring27', N'CTV 409: Senior Film Project', N'A capstone production course in which students write, direct, and produce a short film or television pilot. Students manage all aspects of production from development through post-production and festival submission.', N'Cinema & Television', N'Communications', 400, 3, N'Senior standing in CTV'),
  ('Spring28', N'CIV 393: Geotechnical Engineering', N'A study of soil mechanics and foundation engineering. Topics include soil classification, effective stress, seepage, consolidation, shear strength, bearing capacity, and slope stability analysis.', N'Civil Engineering', N'Engineering', 300, 4, N'CIV 201 and geology course'),
  ('Winter27', N'PHY 124: Astronomy and the Universe', N'A survey of modern astronomy for non-science majors. Topics include the solar system, stellar evolution, galaxies, cosmology, and the search for extraterrestrial life. Includes observatory sessions and analysis of astronomical data.', N'Physics', N'Arts & Sciences', 100, 4, NULL),
  ('Spring27', N'HIS 164: United States History to 1877', N'An examination of American history from indigenous civilizations through Reconstruction. Topics include colonization, revolution, constitutional development, westward expansion, slavery, and the Civil War. Students analyze primary documents and historiographical debates.', N'History', N'Arts & Sciences', 100, 3, NULL),
  ('Fall27', N'PBH 352: Environmental Health', N'A study of environmental factors affecting human health. Topics include water quality, air pollution, toxic substances, food safety, occupational health, climate change, and environmental justice. Students conduct a community environmental health assessment.', N'Public Health', N'Health Sciences', 300, 3, N'PBH 201 and CHM 101'),
  ('Spring27', N'BIO 455: Senior Research in Biology', N'An independent research project conducted under faculty mentorship. Students design experiments, collect and analyze data, and present findings in both written and oral formats following scientific conventions. Develops skills essential for graduate study and careers in research.', N'Biology', N'Arts & Sciences', 400, 3, N'Senior standing in BIO and faculty approval'),
  ('Spring28', N'MEC 209: Statics and Dynamics', N'A study of forces acting on rigid bodies in equilibrium (statics) and in motion (dynamics). Topics include free body diagrams, trusses, friction, kinematics, kinetics, energy methods, and momentum. Fundamental to all branches of engineering.', N'Mechanical Engineering', N'Engineering', 200, 3, N'PHY 211 and MTH 242'),
  ('Fall26', N'BAN 392: Predictive Analytics', N'An applied course in building predictive models for business applications. Topics include linear and logistic regression, decision trees, random forests, and neural network basics. Students develop end-to-end predictive analytics workflows from data preparation through model deployment.', N'Business Analytics', N'Business', 300, 3, N'BAN 202 and BAN 201'),
  ('Fall26', N'CHM 349: Physical Chemistry', N'A study of the physical principles underlying chemical phenomena including quantum mechanics, molecular spectroscopy, thermodynamics, and chemical kinetics. Students develop mathematical and computational skills for modeling chemical systems.', N'Chemistry', N'Arts & Sciences', 300, 3, N'CHM 102, MTH 242, and PHY 202'),
  ('Winter27', N'FIN 378: Risk Management', N'An examination of how organizations identify, measure, and manage financial risks. Topics include market risk, credit risk, operational risk, derivatives as hedging instruments, and enterprise risk management frameworks.', N'Finance', N'Business', 300, 4, N'FIN 201 and MTH 110'),
  ('Spring27', N'MTH 197: Introduction to Statistics', N'An introductory course in descriptive and inferential statistics. Students learn to collect, organize, and interpret data using measures of central tendency, probability distributions, hypothesis testing, and confidence intervals. Real-world datasets from health, business, and social sciences are used throughout.', N'Mathematics', N'Arts & Sciences', 100, 3, NULL),
  ('Spring28', N'MTH 131: Introduction to Statistics', N'An introductory course in descriptive and inferential statistics. Students learn to collect, organize, and interpret data using measures of central tendency, probability distributions, hypothesis testing, and confidence intervals. Real-world datasets from health, business, and social sciences are used throughout.', N'Mathematics', N'Arts & Sciences', 100, 3, NULL),
  ('Spring28', N'CTV 406: Senior Film Project', N'A capstone production course in which students write, direct, and produce a short film or television pilot. Students manage all aspects of production from development through post-production and festival submission.', N'Cinema & Television', N'Communications', 400, 4, N'Senior standing in CTV'),
  ('Spring28', N'ENV 314: Conservation Biology', N'A study of the science behind biodiversity conservation. Topics include extinction patterns, habitat fragmentation, population viability analysis, reserve design, restoration ecology, and the intersection of conservation with human communities and economic development.', N'Environmental Science', N'Arts & Sciences', 300, 3, N'BIO 102 or ENV 101'),
  ('Winter28', N'PHY 455: Electrodynamics', N'An advanced study of electromagnetic theory based on Maxwell''s equations. Topics include boundary value problems, electromagnetic waves, radiation, and special relativity. Students develop skills in vector calculus and mathematical physics.', N'Physics', N'Arts & Sciences', 400, 3, N'PHY 312 and MTH 302'),
  ('Fall27', N'ARH 138: Art History Survey II', N'A survey of art and architecture from the Renaissance to the present. Students examine major movements including Renaissance, Baroque, Impressionism, Modernism, and Contemporary art in their cultural and historical contexts.', N'Art History', N'Fine Arts', 100, 3, NULL),
  ('Spring27', N'POL 179: Introduction to American Government', N'An overview of the American political system including the Constitution, federalism, civil liberties, political parties, elections, Congress, the presidency, and the judiciary. Students analyze current political events using foundational concepts in political science.', N'Political Science', N'Arts & Sciences', 100, 4, NULL),
  ('Fall27', N'MGT 522: Graduate Seminar in Organizational Leadership', N'An advanced seminar exploring contemporary challenges in organizational leadership. Topics include leading distributed teams, managing organizational change, innovation management, and ethical leadership in complex organizations.', N'Management', N'Business', 500, 3, N'Graduate standing'),
  ('Spring27', N'ACC 181: Principles of Managerial Accounting', N'An introduction to accounting for internal decision-making. Topics include cost behavior analysis, budgeting, variance analysis, capital budgeting, and performance evaluation. Students learn to use accounting information for planning, controlling, and evaluating business operations.', N'Accounting', N'Business', 100, 3, N'ACC 101'),
  ('Spring28', N'ENG 204: American Literature Survey', N'A survey of American literature from the colonial period to the present. Examines major movements including Romanticism, Realism, Modernism, and Postmodernism through representative works of fiction, poetry, and nonfiction. Contextualizes literature within social and historical frameworks.', N'English', N'Arts & Sciences', 200, 3, N'ENG 103'),
  ('Fall26', N'CSC 554: Advanced Topics in Machine Learning', N'Graduate-level study of cutting-edge machine learning research including deep reinforcement learning, graph neural networks, federated learning, and large language models. Students read and present current research papers and complete an original research project demonstrating novel application of ML techniques.', N'Computer Science', N'Arts & Sciences', 500, 4, N'CSC 341 and graduate standing'),
  ('Summer27', N'WLG 162: Elementary French I', N'An introduction to the French language developing foundational skills in listening, speaking, reading, and writing. Students learn essential vocabulary and grammar while exploring Francophone cultures through films, music, and literature.', N'World Languages', N'Arts & Sciences', 100, 3, NULL),
  ('Spring27', N'MUS 398: Music Technology and Production', N'An introduction to music technology including digital audio workstations, MIDI sequencing, audio recording and mixing, synthesis, and sound design. Students produce original recordings and learn the technical skills used in modern music production.', N'Music', N'Fine Arts', 300, 2, N'MUS 101'),
  ('Summer27', N'ENG 386: Shakespeare', N'An intensive study of Shakespeare''s major plays including comedies, tragedies, histories, and romances. Students examine dramatic structure, language, performance history, and critical interpretations while considering Shakespeare''s lasting influence on literature and culture.', N'English', N'Arts & Sciences', 300, 4, N'ENG 103'),
  ('Spring28', N'FIN 315: Risk Management', N'An examination of how organizations identify, measure, and manage financial risks. Topics include market risk, credit risk, operational risk, derivatives as hedging instruments, and enterprise risk management frameworks.', N'Finance', N'Business', 300, 3, N'FIN 201 and MTH 110'),
  ('Fall26', N'CSC 494: Capstone Project in Computer Science', N'A year-long capstone experience where students design and implement a significant software project addressing a real-world problem. Teams work with external clients or research advisors, applying the full software development lifecycle from requirements analysis through deployment and maintenance.', N'Computer Science', N'Arts & Sciences', 400, 3, N'Senior standing in CSC'),
  ('Winter28', N'POL 347: Constitutional Law', N'An in-depth study of U.S. constitutional interpretation focusing on landmark Supreme Court decisions. Topics include judicial review, separation of powers, federalism, equal protection, due process, and First Amendment freedoms.', N'Political Science', N'Arts & Sciences', 300, 3, N'POL 101'),
  ('Spring28', N'EDL 308: Instructional Leadership', N'A course in leading curriculum and instruction improvement at the school and district level. Topics include observation and feedback, professional learning communities, data-driven decision-making, and leading collaborative teams.', N'Educational Leadership', N'Education', 300, 2, N'EDL 201'),
  ('Fall27', N'PHY 304: Thermodynamics and Statistical Mechanics', N'A study of thermal physics from both macroscopic and microscopic perspectives. Topics include the laws of thermodynamics, entropy, ensembles, partition functions, quantum statistics, and phase transitions.', N'Physics', N'Arts & Sciences', 300, 3, N'PHY 221 and MTH 302'),
  ('Spring28', N'SOC 147: Introduction to Sociology', N'An introduction to sociological perspectives on human society. Topics include social structure, culture, socialization, inequality, race and ethnicity, gender, deviance, and institutions. Students develop the ability to see personal experiences within broader social patterns.', N'Sociology', N'Arts & Sciences', 100, 3, NULL),
  ('Summer27', N'MKT 138: Principles of Marketing', N'An introduction to marketing concepts and strategies including market segmentation, consumer behavior, product development, pricing, distribution, and promotion. Students develop a marketing plan for a real or simulated product.', N'Marketing', N'Business', 100, 3, NULL),
  ('Spring28', N'ENV 362: Climate Change Science and Policy', N'A comprehensive examination of climate change from scientific and policy perspectives. Covers atmospheric physics, climate modeling, observed impacts, mitigation strategies, adaptation planning, and international climate negotiations. Students analyze climate data and evaluate policy proposals.', N'Environmental Science', N'Arts & Sciences', 300, 3, N'ENV 101 and one science elective'),
  ('Fall27', N'CSC 259: Data Structures and Algorithms', N'A study of fundamental data structures including arrays, linked lists, stacks, queues, trees, and graphs. Students analyze algorithm efficiency using Big-O notation and implement sorting and searching algorithms. Prerequisite concepts from introductory programming are extended to handle complex data organization challenges.', N'Computer Science', N'Arts & Sciences', 200, 3, N'CSC 131 or equivalent programming experience'),
  ('Spring27', N'EXS 318: Research Methods in Exercise Science', N'An introduction to research design and methods in exercise science. Topics include literature review, hypothesis formation, experimental and observational study designs, data collection, basic statistical analysis, and research ethics.', N'Exercise Science', N'Health Sciences', 300, 3, N'EXS 211 and MTH 110'),
  ('Summer28', N'MTH 555: Graduate Seminar in Applied Mathematics', N'An advanced seminar exploring current research topics in applied mathematics. Students read recent publications, present findings, and develop original research questions. Topics rotate and may include mathematical biology, computational fluid dynamics, or network analysis.', N'Mathematics', N'Arts & Sciences', 500, 3, N'Graduate standing in MTH');
INSERT INTO dbo.CourseCatalog (TermID, CourseTitle, CourseDescription, Department, College, CourseLevel, Credits, Prerequisites)
VALUES
  ('Summer28', N'SOC 244: Sociology of Health and Illness', N'An examination of social factors influencing health, illness, and healthcare delivery. Topics include social determinants of health, health disparities, medicalization, patient-provider relationships, and healthcare systems in comparative perspective.', N'Sociology', N'Arts & Sciences', 200, 3, N'SOC 101'),
  ('Winter27', N'PSY 207: Biological Psychology', N'A study of the biological bases of behavior including neuroanatomy, neurotransmitter systems, sensory processing, motivation, emotion, learning, and psychopharmacology. Bridges neuroscience and psychological perspectives on mind-brain relationships.', N'Psychology', N'Arts & Sciences', 200, 3, N'PSY 101'),
  ('Fall26', N'HLA 308: Healthcare Law and Regulatory Compliance', N'An examination of the legal and regulatory environment of healthcare. Topics include HIPAA, fraud and abuse laws, medical malpractice, informed consent, accreditation, and regulatory compliance programs.', N'Health Administration', N'Health Sciences', 300, 3, N'HLA 101'),
  ('Spring27', N'ENV 161: Sustainability and Society', N'An exploration of sustainability concepts and practices across environmental, economic, and social dimensions. Students examine case studies of sustainable communities, renewable energy, circular economies, and corporate sustainability initiatives.', N'Environmental Science', N'Arts & Sciences', 100, 3, NULL),
  ('Summer28', N'CPE 236: Introduction to Computer Networks', N'A practical introduction to computer networking concepts and protocols. Topics include the Internet protocol stack, Ethernet, WiFi, IP addressing, routing, transport protocols, and network security fundamentals.', N'Computer Engineering', N'Engineering', 200, 4, N'CSC 231'),
  ('Winter28', N'ART 576: Graduate Seminar in Contemporary Art Practice', N'An advanced seminar exploring current trends and critical frameworks in contemporary art. Students develop studio practice, engage with art theory, and present their work in professional critique settings.', N'Studio Art', N'Fine Arts', 500, 3, N'Graduate standing'),
  ('Spring28', N'SPE 583: Graduate Seminar in Learning Disabilities', N'An advanced seminar examining current research on learning disabilities. Topics include neurological bases, evidence-based interventions, response to intervention, and the intersection of learning disabilities with cultural and linguistic diversity.', N'Special Education', N'Education', 500, 3, N'Graduate standing'),
  ('Fall26', N'ENV 149: Introduction to Environmental Science', N'A multidisciplinary survey of environmental issues including climate change, biodiversity loss, pollution, resource depletion, and sustainable development. Integrates concepts from biology, chemistry, geology, and policy to understand human impacts on natural systems.', N'Environmental Science', N'Arts & Sciences', 100, 3, NULL),
  ('Spring28', N'ENG 414: Senior Thesis in English', N'An independent research project resulting in a substantial critical essay or creative work. Students work with a faculty advisor to develop an original argument or creative vision, conduct research, and present their work at the departmental colloquium.', N'English', N'Arts & Sciences', 400, 4, N'Senior standing in ENG'),
  ('Spring28', N'MGT 166: Introduction to Entrepreneurship', N'An exploration of the entrepreneurial mindset and new venture creation. Students learn to identify opportunities, develop business models, conduct market analysis, and pitch ideas. Includes case studies of successful startups and social enterprises.', N'Management', N'Business', 100, 3, NULL),
  ('Spring27', N'MGT 418: Negotiations and Conflict Resolution', N'An advanced experiential course in negotiation theory and practice. Students participate in simulated negotiations, analyze bargaining strategies, and develop skills in mediation and dispute resolution applicable to business, legal, and interpersonal contexts.', N'Management', N'Business', 400, 3, N'MGT 201'),
  ('Fall27', N'MTH 392: Differential Equations', N'A study of ordinary differential equations and their applications. Topics include first-order equations, linear systems, Laplace transforms, numerical methods, and modeling of physical and biological systems. Emphasizes both analytical solutions and qualitative behavior analysis.', N'Mathematics', N'Arts & Sciences', 300, 3, N'MTH 242'),
  ('Fall27', N'CTV 369: Directing for Screen', N'An advanced production course focusing on the art and craft of directing. Students work with actors, plan shot compositions, manage production teams, and direct short narrative films. Covers both technical skills and the director''s creative vision.', N'Cinema & Television', N'Communications', 300, 4, N'CTV 102 and CTV 211'),
  ('Spring28', N'ENV 223: Environmental Policy and Law', N'An examination of the legal and regulatory frameworks governing environmental protection. Topics include the Clean Air Act, Clean Water Act, NEPA, endangered species legislation, and international environmental agreements. Students analyze policy effectiveness and propose improvements.', N'Environmental Science', N'Arts & Sciences', 200, 3, N'ENV 101 or POL 101'),
  ('Summer28', N'HIS 373: Historical Research Methods', N'A hands-on course in the methods and practices of historical research. Students learn to locate and evaluate primary sources, construct historical arguments, navigate archives, and write research papers that meet professional standards in the discipline.', N'History', N'Arts & Sciences', 300, 3, N'Two 200-level HIS courses'),
  ('Winter27', N'ACC 218: Intermediate Accounting II', N'Continuation of Intermediate Accounting I covering accounting for liabilities, stockholders'' equity, investments, leases, pensions, income taxes, and cash flow statements. Emphasizes analysis of complex transactions and financial statement presentation.', N'Accounting', N'Business', 200, 3, N'ACC 211'),
  ('Winter27', N'FIN 101: Introduction to Business Finance', N'An overview of fundamental financial concepts including time value of money, risk and return, financial statement analysis, and capital markets. Provides a foundation for understanding how businesses raise and invest capital.', N'Finance', N'Business', 100, 3, NULL),
  ('Winter28', N'SCM 223: Public Relations Writing', N'A practical course in writing for public relations including press releases, media pitches, feature articles, speeches, and social media content. Students develop a professional portfolio demonstrating mastery of various PR writing formats.', N'Strategic Communications', N'Communications', 200, 3, N'SCM 101'),
  ('Spring28', N'EED 327: Classroom Management and Community Building', N'A practical course in creating positive, productive classroom environments. Students learn proactive management strategies, restorative practices, culturally responsive approaches, and techniques for building inclusive classroom communities.', N'Elementary Education', N'Education', 300, 3, N'EED 202'),
  ('Spring27', N'EXS 177: Introduction to Exercise Science', N'An overview of the scientific study of human movement and physical activity. Topics include exercise physiology, biomechanics, motor learning, sport psychology, and the role of physical activity in health promotion and disease prevention.', N'Exercise Science', N'Health Sciences', 100, 3, NULL),
  ('Winter27', N'CSC 151: Introduction to Programming', N'A hands-on first course in programming using Python. Students develop skills in writing, testing, and debugging programs while exploring fundamental concepts such as data types, loops, conditionals, and functions. Emphasis on solving real-world problems through code.', N'Computer Science', N'Arts & Sciences', 100, 2, NULL),
  ('Fall27', N'ACC 301: Federal Income Taxation', N'A comprehensive study of the federal income tax system for individuals and businesses. Topics include gross income, deductions, credits, property transactions, and tax planning strategies. Students prepare tax returns and analyze tax policy implications.', N'Accounting', N'Business', 300, 3, N'ACC 211'),
  ('Winter27', N'PBH 355: Health Policy and Management', N'A study of healthcare organization, financing, and policy in the United States and internationally. Topics include health insurance, managed care, healthcare quality, access disparities, and the policy-making process.', N'Public Health', N'Health Sciences', 300, 3, N'PBH 101'),
  ('Fall27', N'PHY 343: Classical Mechanics', N'An advanced treatment of Newtonian mechanics using Lagrangian and Hamiltonian formalisms. Topics include central force motion, rigid body dynamics, coupled oscillations, and an introduction to chaos and nonlinear dynamics.', N'Physics', N'Arts & Sciences', 300, 3, N'PHY 211 and MTH 302'),
  ('Spring27', N'BIO 148: General Biology I', N'An introduction to cellular and molecular biology covering cell structure, metabolism, genetics, and molecular biology. Laboratory sessions reinforce lecture concepts through microscopy, gel electrophoresis, and experimental design. Intended for science majors.', N'Biology', N'Arts & Sciences', 100, 3, NULL),
  ('Fall27', N'ARH 163: Art History Survey I', N'A survey of art and architecture from prehistoric times through the medieval period. Students examine works from diverse cultures including Egyptian, Greek, Roman, Byzantine, and Islamic traditions while developing visual analysis skills.', N'Art History', N'Fine Arts', 100, 3, NULL),
  ('Summer27', N'FIN 333: International Finance', N'A study of financial management in a global context. Topics include exchange rate determination, currency risk management, international capital budgeting, cross-border investment, and the global financial system.', N'Finance', N'Business', 300, 4, N'FIN 201'),
  ('Winter27', N'ECN 324: Labor Economics', N'An analysis of labor markets including labor supply and demand, human capital theory, wage determination, discrimination, unions, unemployment, and labor market policy. Students use data to analyze trends in employment and earnings.', N'Economics', N'Business', 300, 1, N'ECN 201'),
  ('Fall27', N'ARH 216: Asian Art and Architecture', N'A survey of the visual arts of East Asia, South Asia, and Southeast Asia from ancient times to the present. Students explore the religious, philosophical, and cultural contexts of art and architecture across diverse Asian traditions.', N'Art History', N'Fine Arts', 200, 2, NULL),
  ('Fall26', N'ART 249: Sculpture I', N'An introduction to three-dimensional art-making using a variety of materials and processes including clay, wood, metal, and found objects. Students explore form, space, texture, and conceptual approaches to sculptural practice.', N'Studio Art', N'Fine Arts', 200, 3, N'ART 102'),
  ('Summer28', N'PBH 311: Global Health', N'An examination of health challenges in a global context. Topics include infectious disease control, maternal and child health, nutrition, health systems strengthening, global health governance, and the social determinants of health across nations.', N'Public Health', N'Health Sciences', 300, 2, N'PBH 201'),
  ('Spring27', N'MTH 262: Discrete Mathematics', N'An introduction to mathematical structures and reasoning fundamental to computer science. Topics include logic, set theory, combinatorics, graph theory, recursive definitions, and proof techniques. Students develop skills in abstract reasoning and formal argumentation.', N'Mathematics', N'Arts & Sciences', 200, 3, N'MTH 131 or CSC 131'),
  ('Summer27', N'ELE 324: Embedded Systems', N'A practical course in designing microcontroller-based systems. Students program ARM-based processors, interface with sensors and actuators, implement communication protocols, and develop real-time embedded applications.', N'Electrical Engineering', N'Engineering', 300, 3, N'ELE 202 and programming experience'),
  ('Fall26', N'THR 262: Acting II: Scene Study', N'A continuation of Acting I focusing on scene analysis, character development, and performance technique. Students rehearse and perform scenes from contemporary and classical dramatic literature while developing their artistic process.', N'Theatre', N'Fine Arts', 200, 3, N'THR 102'),
  ('Fall27', N'HLA 427: Healthcare Strategic Management', N'A capstone course in developing and implementing strategic plans for healthcare organizations. Students analyze competitive environments, assess organizational capabilities, develop strategic initiatives, and present recommendations to industry panels.', N'Health Administration', N'Health Sciences', 400, 3, N'Senior standing in HLA'),
  ('Fall27', N'CHM 342: Biochemistry', N'An exploration of the chemistry of living systems covering amino acids, protein structure, enzyme kinetics, carbohydrate and lipid metabolism, and nucleic acid chemistry. Integrates organic chemistry and biology to understand molecular mechanisms of life.', N'Chemistry', N'Arts & Sciences', 300, 3, N'CHM 202 and BIO 101'),
  ('Fall27', N'CHM 349: Physical Chemistry', N'A study of the physical principles underlying chemical phenomena including quantum mechanics, molecular spectroscopy, thermodynamics, and chemical kinetics. Students develop mathematical and computational skills for modeling chemical systems.', N'Chemistry', N'Arts & Sciences', 300, 3, N'CHM 102, MTH 242, and PHY 202'),
  ('Spring27', N'HIS 321: Public History', N'An exploration of how history is presented and interpreted outside the academy. Topics include museums, historic preservation, documentary film, digital archives, oral history, and community-based historical projects. Students complete a public history project.', N'History', N'Arts & Sciences', 300, 3, N'HIS 301'),
  ('Spring28', N'ELE 376: Embedded Systems', N'A practical course in designing microcontroller-based systems. Students program ARM-based processors, interface with sensors and actuators, implement communication protocols, and develop real-time embedded applications.', N'Electrical Engineering', N'Engineering', 300, 3, N'ELE 202 and programming experience'),
  ('Winter28', N'PHL 118: Logic and Critical Thinking', N'A practical course in formal and informal logic. Students learn to identify argument structures, detect fallacies, evaluate evidence, and construct sound arguments. Develops analytical reasoning skills applicable across academic disciplines and everyday decision-making.', N'Philosophy', N'Arts & Sciences', 100, 1, NULL),
  ('Spring28', N'PSY 212: Biological Psychology', N'A study of the biological bases of behavior including neuroanatomy, neurotransmitter systems, sensory processing, motivation, emotion, learning, and psychopharmacology. Bridges neuroscience and psychological perspectives on mind-brain relationships.', N'Psychology', N'Arts & Sciences', 200, 4, N'PSY 101'),
  ('Summer27', N'SOC 245: Research Methods in Sociology', N'An introduction to qualitative and quantitative research methods in sociology. Topics include survey design, interviewing, ethnography, content analysis, and statistical techniques. Students design and execute a small-scale research project.', N'Sociology', N'Arts & Sciences', 200, 3, N'SOC 101'),
  ('Spring28', N'CTV 105: Introduction to Film Studies', N'An exploration of cinema as an art form and cultural practice. Students learn the language of film including cinematography, editing, sound design, and narrative structure while analyzing works from diverse national cinemas and historical periods.', N'Cinema & Television', N'Communications', 100, 2, NULL),
  ('Spring27', N'MGT 212: Business Ethics', N'An examination of ethical issues in business practice. Topics include corporate social responsibility, stakeholder theory, ethical decision-making frameworks, whistleblowing, environmental sustainability, and ethics in global business operations.', N'Management', N'Business', 200, 3, N'MGT 101'),
  ('Fall26', N'MTH 226: Linear Algebra', N'A study of vector spaces, linear transformations, matrices, determinants, eigenvalues, and eigenvectors. Applications include systems of linear equations, least-squares approximation, and Markov chains. This course provides essential mathematical foundations for machine learning, data science, and engineering.', N'Mathematics', N'Arts & Sciences', 200, 1, N'MTH 241'),
  ('Summer28', N'MGT 242: Human Resource Management', N'An introduction to the strategic management of human capital. Topics include recruitment, selection, training, performance management, compensation, labor relations, and diversity management. Students analyze HRM practices in contemporary organizations.', N'Management', N'Business', 200, 4, N'MGT 101'),
  ('Winter27', N'MGT 467: Negotiations and Conflict Resolution', N'An advanced experiential course in negotiation theory and practice. Students participate in simulated negotiations, analyze bargaining strategies, and develop skills in mediation and dispute resolution applicable to business, legal, and interpersonal contexts.', N'Management', N'Business', 400, 3, N'MGT 201'),
  ('Spring27', N'SCM 377: Crisis Communications', N'An examination of communication strategies during organizational crises. Students analyze real crisis cases, develop crisis communication plans, conduct media training exercises, and learn to manage reputation in the social media age.', N'Strategic Communications', N'Communications', 300, 3, N'SCM 201'),
  ('Winter27', N'EXS 421: Senior Research Project in Exercise Science', N'An independent research project in exercise science conducted under faculty mentorship. Students design a study, collect and analyze data, and present findings in both written and oral formats at the departmental research symposium.', N'Exercise Science', N'Health Sciences', 400, 4, N'EXS 331 and senior standing'),
  ('Spring28', N'PSY 478: Senior Seminar in Psychology', N'A capstone seminar requiring an original research project or comprehensive literature review. Students develop a research question, collect or analyze data, write a manuscript following APA format, and present findings at a departmental symposium.', N'Psychology', N'Arts & Sciences', 400, 3, N'Senior standing in PSY and PSY 201');
INSERT INTO dbo.CourseCatalog (TermID, CourseTitle, CourseDescription, Department, College, CourseLevel, Credits, Prerequisites)
VALUES
  ('Spring28', N'ENG 391: Literary Theory and Criticism', N'An introduction to major schools of literary criticism including formalism, structuralism, poststructuralism, feminism, postcolonialism, and cultural studies. Students apply theoretical frameworks to literary texts and develop skills in critical argumentation.', N'English', N'Arts & Sciences', 300, 3, N'Two 200-level ENG courses'),
  ('Winter28', N'MUS 428: Senior Recital', N'A capstone performance experience in which students prepare and perform a full-length recital. Students select repertoire, write program notes, and demonstrate advanced musical and technical skills developed through their course of study.', N'Music', N'Fine Arts', 400, 4, N'Senior standing in MUS and faculty approval'),
  ('Spring27', N'EED 302: Teaching Mathematics in Elementary Schools', N'A methods course in teaching mathematics to children in grades K-6. Students explore mathematical content knowledge, research-based instructional strategies, manipulative use, problem-solving approaches, and assessment techniques for diverse learners.', N'Elementary Education', N'Education', 300, 3, N'EED 202 and MTH 131'),
  ('Fall26', N'SOC 284: Sociology of Health and Illness', N'An examination of social factors influencing health, illness, and healthcare delivery. Topics include social determinants of health, health disparities, medicalization, patient-provider relationships, and healthcare systems in comparative perspective.', N'Sociology', N'Arts & Sciences', 200, 3, N'SOC 101'),
  ('Fall27', N'MUS 192: Introduction to Music', N'A survey of music for non-majors exploring diverse genres, styles, and historical periods. Students develop active listening skills and learn to articulate their responses to music through guided analysis of representative works.', N'Music', N'Fine Arts', 100, 4, NULL),
  ('Winter27', N'JOU 157: Media and Society', N'An examination of the role of media in shaping public opinion, culture, and political discourse. Topics include media ownership, media literacy, representation, propaganda, the digital transformation of news, and the economics of the media industry.', N'Journalism', N'Communications', 100, 3, NULL),
  ('Fall27', N'PSY 291: Biological Psychology', N'A study of the biological bases of behavior including neuroanatomy, neurotransmitter systems, sensory processing, motivation, emotion, learning, and psychopharmacology. Bridges neuroscience and psychological perspectives on mind-brain relationships.', N'Psychology', N'Arts & Sciences', 200, 3, N'PSY 101'),
  ('Fall26', N'CSC 278: Database Systems Fundamentals', N'Introduction to relational database concepts including entity-relationship modeling, normalization, and SQL query writing. Students design and implement databases, write complex queries involving joins and subqueries, and explore indexing strategies for query optimization.', N'Computer Science', N'Arts & Sciences', 200, 3, N'CSC 131'),
  ('Summer27', N'ENG 136: English Composition I', N'A foundational course in academic writing focusing on thesis development, evidence-based argumentation, source integration, and revision strategies. Students write multiple essays exploring topics in the humanities and social sciences while developing a flexible writing process.', N'English', N'Arts & Sciences', 100, 3, NULL),
  ('Winter27', N'WLG 267: Intermediate Spanish', N'A continuation of language study that deepens communicative competence through reading, writing, speaking, and listening activities. Students engage with authentic texts and media from the Spanish-speaking world while expanding grammatical accuracy and cultural understanding.', N'World Languages', N'Arts & Sciences', 200, 2, N'WLG 102 or placement'),
  ('Spring27', N'PHL 198: Logic and Critical Thinking', N'A practical course in formal and informal logic. Students learn to identify argument structures, detect fallacies, evaluate evidence, and construct sound arguments. Develops analytical reasoning skills applicable across academic disciplines and everyday decision-making.', N'Philosophy', N'Arts & Sciences', 100, 3, NULL),
  ('Summer27', N'BIO 418: Advanced Genomics and Proteomics', N'A capstone course examining high-throughput technologies for genome and proteome analysis. Topics include next-generation sequencing, transcriptomics, mass spectrometry-based proteomics, and integrative bioinformatics approaches. Students complete a data analysis project using publicly available datasets.', N'Biology', N'Arts & Sciences', 400, 3, N'BIO 311 or BIO 313'),
  ('Spring27', N'HLA 109: Introduction to Health Administration', N'An overview of the U.S. healthcare system including its organization, financing, delivery, and governance. Students explore the roles of hospitals, insurers, government agencies, and public health organizations in healthcare delivery.', N'Health Administration', N'Health Sciences', 100, 1, NULL),
  ('Spring28', N'ELE 395: Electronics', N'A study of semiconductor devices and electronic circuit design. Topics include diodes, transistors (BJT and MOSFET), amplifier design, frequency response, feedback, and operational amplifier circuits.', N'Electrical Engineering', N'Engineering', 300, 3, N'ELE 201'),
  ('Fall27', N'EDL 276: Foundations of Educational Leadership', N'An introduction to leadership theories and their application in educational settings. Students explore transformational, distributed, and servant leadership models while examining the roles and responsibilities of school administrators.', N'Educational Leadership', N'Education', 200, 3, N'EED 101 or SPE 101'),
  ('Spring28', N'MGT 376: Project Management', N'A practical course in planning, executing, and controlling projects. Topics include scope management, scheduling, budgeting, risk management, team leadership, and Agile methodologies. Students use project management software to plan and track a real project.', N'Management', N'Business', 300, 3, N'MGT 201'),
  ('Winter28', N'ELE 558: Graduate Seminar in IoT and Edge Computing', N'An advanced seminar on Internet of Things architectures and edge computing. Topics include sensor networks, low-power design, edge AI, security in IoT systems, and applications in smart infrastructure.', N'Electrical Engineering', N'Engineering', 500, 4, N'Graduate standing'),
  ('Winter28', N'CHM 531: Graduate Research in Chemistry', N'Supervised research in an active faculty research lab. Students conduct original research, participate in group meetings, and present progress reports. Culminates in a thesis or publishable manuscript.', N'Chemistry', N'Arts & Sciences', 500, 3, N'Graduate standing'),
  ('Fall27', N'FIN 349: Financial Modeling', N'A hands-on course in building financial models using Excel and Python. Students develop models for valuation, forecasting, M&A analysis, and risk assessment. Emphasis on best practices in model design, documentation, and presentation.', N'Finance', N'Business', 300, 3, N'FIN 201 and ACC 102'),
  ('Winter28', N'MEC 203: Thermodynamics', N'A study of energy, heat, work, and their transformation in engineering systems. Topics include the first and second laws, entropy, properties of pure substances, power and refrigeration cycles, and energy efficiency analysis.', N'Mechanical Engineering', N'Engineering', 200, 3, N'PHY 211 and MTH 242'),
  ('Spring28', N'EED 562: Graduate Seminar in Curriculum Theory', N'An advanced seminar examining theories of curriculum design, implementation, and evaluation. Students explore perspectives including critical pedagogy, multicultural education, and standards-based reform while developing curriculum for diverse contexts.', N'Elementary Education', N'Education', 500, 3, N'Graduate standing'),
  ('Winter27', N'SOC 164: Social Problems', N'An examination of major social problems including poverty, crime, substance abuse, healthcare access, environmental degradation, and educational inequality. Students analyze the structural causes of social problems and evaluate proposed solutions using sociological frameworks.', N'Sociology', N'Arts & Sciences', 100, 3, NULL),
  ('Winter27', N'SCM 352: Social Media Strategy', N'An advanced course in developing and executing social media strategies for organizations. Topics include platform selection, content planning, community management, influencer partnerships, paid social advertising, and social media analytics.', N'Strategic Communications', N'Communications', 300, 3, N'SCM 201'),
  ('Fall27', N'BAN 292: Data Management for Business', N'A practical course in managing and querying business data. Students learn relational database concepts, SQL query writing, data cleaning and transformation techniques, and basic data warehousing principles. Applications focus on marketing, finance, and operations datasets.', N'Business Analytics', N'Business', 200, 2, N'BAN 101'),
  ('Fall27', N'SCM 183: Introduction to Strategic Communications', N'An overview of the strategic communications field including public relations, advertising, and integrated marketing communications. Students learn campaign planning, message development, media relations, and the role of communication in organizational strategy.', N'Strategic Communications', N'Communications', 100, 3, NULL),
  ('Winter28', N'SPE 287: Behavior Support and Intervention', N'A practical course in understanding and addressing challenging behaviors in educational settings. Students learn functional behavior assessment, positive behavior interventions, de-escalation strategies, and ethical considerations in behavior management.', N'Special Education', N'Education', 200, 1, N'SPE 101'),
  ('Spring28', N'CPE 323: Operating System Design', N'An examination of operating system internals with emphasis on implementation. Topics include process scheduling, memory management, file systems, device drivers, and system calls. Students implement kernel modules in a Unix-like environment.', N'Computer Engineering', N'Engineering', 300, 3, N'CPE 211 and CSC 231'),
  ('Fall26', N'ARH 296: Modern Art: 1860-1960', N'A study of the development of modern art from Impressionism through Abstract Expressionism. Students examine how artists responded to industrialization, urbanization, world wars, and new philosophical ideas through innovative visual forms.', N'Art History', N'Fine Arts', 200, 3, N'ARH 102'),
  ('Spring27', N'SPE 494: Advanced Practicum in Special Education', N'A culminating clinical experience in which students plan and deliver instruction to students with disabilities in school settings. Includes assessment, IEP implementation, collaboration with general educators, and reflective practice.', N'Special Education', N'Education', 400, 4, N'Senior standing in SPE'),
  ('Spring27', N'WLG 148: Elementary French I', N'An introduction to the French language developing foundational skills in listening, speaking, reading, and writing. Students learn essential vocabulary and grammar while exploring Francophone cultures through films, music, and literature.', N'World Languages', N'Arts & Sciences', 100, 3, NULL),
  ('Fall27', N'PHY 485: Electrodynamics', N'An advanced study of electromagnetic theory based on Maxwell''s equations. Topics include boundary value problems, electromagnetic waves, radiation, and special relativity. Students develop skills in vector calculus and mathematical physics.', N'Physics', N'Arts & Sciences', 400, 3, N'PHY 312 and MTH 302'),
  ('Spring27', N'THR 484: Senior Production Project', N'A capstone experience in which students serve in a major production role — director, designer, stage manager, or lead performer — on a departmental production. Students demonstrate professional-level competence in their area of concentration.', N'Theatre', N'Fine Arts', 400, 3, N'Senior standing in THR'),
  ('Winter28', N'HIS 353: Historical Research Methods', N'A hands-on course in the methods and practices of historical research. Students learn to locate and evaluate primary sources, construct historical arguments, navigate archives, and write research papers that meet professional standards in the discipline.', N'History', N'Arts & Sciences', 300, 3, N'Two 200-level HIS courses'),
  ('Summer28', N'ART 289: Painting I', N'An introduction to painting techniques and concepts. Students work in oil and acrylic to develop skills in color mixing, composition, surface quality, and visual expression. Subjects include still life, landscape, and the figure.', N'Studio Art', N'Fine Arts', 200, 3, N'ART 101'),
  ('Winter28', N'THR 259: Acting II: Scene Study', N'A continuation of Acting I focusing on scene analysis, character development, and performance technique. Students rehearse and perform scenes from contemporary and classical dramatic literature while developing their artistic process.', N'Theatre', N'Fine Arts', 200, 3, N'THR 102'),
  ('Spring28', N'EED 169: Introduction to Education', N'An exploration of the foundations of American education including its history, philosophy, and social contexts. Students examine current issues in education reform, observe in local classrooms, and reflect on their motivations for entering the teaching profession.', N'Elementary Education', N'Education', 100, 3, NULL),
  ('Spring27', N'WLG 309: Hispanic Literature and Film', N'A study of major works of literature and film from Spain and Latin America in their cultural and historical contexts. Students develop advanced reading and analytical skills while exploring themes of identity, justice, memory, and artistic innovation.', N'World Languages', N'Arts & Sciences', 300, 4, N'WLG 202'),
  ('Fall26', N'CHM 304: Physical Chemistry', N'A study of the physical principles underlying chemical phenomena including quantum mechanics, molecular spectroscopy, thermodynamics, and chemical kinetics. Students develop mathematical and computational skills for modeling chemical systems.', N'Chemistry', N'Arts & Sciences', 300, 2, N'CHM 102, MTH 242, and PHY 202'),
  ('Fall26', N'SOC 345: Data Analysis for Social Science', N'A practical course in statistical analysis for sociological research. Students learn to use R and SPSS to manage data, conduct descriptive and inferential analyses, and create visualizations. Covers regression, ANOVA, and introduction to multilevel modeling.', N'Sociology', N'Arts & Sciences', 300, 3, N'SOC 201 and MTH 110'),
  ('Winter28', N'PSY 244: Developmental Psychology', N'A lifespan approach to human development from conception through aging. Covers physical, cognitive, and psychosocial development with attention to cultural contexts, individual differences, and applications to parenting, education, and healthcare.', N'Psychology', N'Arts & Sciences', 200, 3, N'PSY 101'),
  ('Spring27', N'ELE 272: Circuit Analysis', N'A study of linear electrical circuits including DC and AC analysis, Kirchhoff''s laws, Thevenin and Norton equivalents, operational amplifiers, and transient response. Laboratory work reinforces analytical techniques with practical circuit construction.', N'Electrical Engineering', N'Engineering', 200, 3, N'PHY 212 and MTH 242'),
  ('Winter28', N'PBH 139: Introduction to Public Health', N'An overview of public health principles including epidemiology, health promotion, disease prevention, environmental health, and health policy. Students explore how public health systems address population-level health challenges including infectious disease, chronic conditions, and health disparities.', N'Public Health', N'Health Sciences', 100, 3, NULL),
  ('Spring28', N'MKT 441: Strategic Marketing Management', N'A capstone course integrating marketing concepts in strategic decision-making. Students analyze complex marketing cases, develop comprehensive go-to-market strategies, and present recommendations to industry panels.', N'Marketing', N'Business', 400, 3, N'Senior standing in MKT'),
  ('Summer28', N'MKT 259: Marketing Research', N'An introduction to marketing research methods including survey design, focus groups, experimental research, and secondary data analysis. Students learn to use data analytics tools to derive actionable marketing insights from consumer and market data.', N'Marketing', N'Business', 200, 3, N'MKT 101 and MTH 110'),
  ('Winter27', N'MTH 398: Differential Equations', N'A study of ordinary differential equations and their applications. Topics include first-order equations, linear systems, Laplace transforms, numerical methods, and modeling of physical and biological systems. Emphasizes both analytical solutions and qualitative behavior analysis.', N'Mathematics', N'Arts & Sciences', 300, 1, N'MTH 242'),
  ('Winter28', N'POL 359: Political Psychology', N'An exploration of psychological factors in political behavior including public opinion formation, voting behavior, political socialization, propaganda, conspiracy thinking, and the psychology of leadership. Integrates psychological research with political analysis.', N'Political Science', N'Arts & Sciences', 300, 4, N'POL 101 and PSY 101'),
  ('Winter28', N'ARH 435: Senior Seminar in Art History', N'A capstone seminar in which students conduct original research on a topic in art history. Students develop research skills, write a scholarly paper, and present their findings at the departmental symposium.', N'Art History', N'Fine Arts', 400, 3, N'Senior standing in ARH'),
  ('Summer28', N'JOU 513: Graduate Seminar in Media Ethics and Law', N'An advanced seminar examining legal and ethical frameworks governing journalism and media. Topics include press freedom, defamation, privacy, shield laws, access to information, and ethical dilemmas in the digital age.', N'Journalism', N'Communications', 500, 3, N'Graduate standing'),
  ('Fall26', N'ENG 207: American Literature Survey', N'A survey of American literature from the colonial period to the present. Examines major movements including Romanticism, Realism, Modernism, and Postmodernism through representative works of fiction, poetry, and nonfiction. Contextualizes literature within social and historical frameworks.', N'English', N'Arts & Sciences', 200, 3, N'ENG 103'),
  ('Fall26', N'WLG 295: Intermediate Spanish', N'A continuation of language study that deepens communicative competence through reading, writing, speaking, and listening activities. Students engage with authentic texts and media from the Spanish-speaking world while expanding grammatical accuracy and cultural understanding.', N'World Languages', N'Arts & Sciences', 200, 3, N'WLG 102 or placement');
INSERT INTO dbo.CourseCatalog (TermID, CourseTitle, CourseDescription, Department, College, CourseLevel, Credits, Prerequisites)
VALUES
  ('Winter28', N'CSC 121: Introduction to Programming', N'A hands-on first course in programming using Python. Students develop skills in writing, testing, and debugging programs while exploring fundamental concepts such as data types, loops, conditionals, and functions. Emphasis on solving real-world problems through code.', N'Computer Science', N'Arts & Sciences', 100, 3, NULL),
  ('Fall27', N'PSY 395: Abnormal Psychology', N'A comprehensive survey of psychological disorders including their classification, etiology, assessment, and treatment. Covers anxiety, mood, psychotic, personality, and neurodevelopmental disorders with attention to cultural and ethical considerations in diagnosis.', N'Psychology', N'Arts & Sciences', 300, 4, N'PSY 201'),
  ('Fall27', N'EED 416: Student Teaching Seminar', N'A capstone seminar accompanying the student teaching experience. Students reflect on their practice, analyze student learning data, develop a professional portfolio, and engage in collaborative problem-solving around challenges encountered during their teaching placement.', N'Elementary Education', N'Education', 400, 3, N'Senior standing in EED and all methods courses'),
  ('Summer28', N'MEC 382: Fluid Mechanics', N'A study of fluid behavior and its engineering applications. Topics include fluid statics, conservation laws, Bernoulli equation, viscous flow, pipe systems, boundary layers, and an introduction to computational fluid dynamics.', N'Mechanical Engineering', N'Engineering', 300, 3, N'MEC 201 and MTH 302'),
  ('Fall27', N'SPE 462: Advanced Practicum in Special Education', N'A culminating clinical experience in which students plan and deliver instruction to students with disabilities in school settings. Includes assessment, IEP implementation, collaboration with general educators, and reflective practice.', N'Special Education', N'Education', 400, 3, N'Senior standing in SPE'),
  ('Winter27', N'FIN 456: Senior Capstone in Finance', N'A capstone experience integrating financial theory and practice. Students complete an applied research project or case competition addressing complex financial problems. Develops skills in financial analysis, communication, and professional judgment.', N'Finance', N'Business', 400, 3, N'Senior standing in FIN'),
  ('Summer28', N'MGT 299: Business Ethics', N'An examination of ethical issues in business practice. Topics include corporate social responsibility, stakeholder theory, ethical decision-making frameworks, whistleblowing, environmental sustainability, and ethics in global business operations.', N'Management', N'Business', 200, 3, N'MGT 101'),
  ('Spring28', N'CTV 402: Senior Film Project', N'A capstone production course in which students write, direct, and produce a short film or television pilot. Students manage all aspects of production from development through post-production and festival submission.', N'Cinema & Television', N'Communications', 400, 4, N'Senior standing in CTV'),
  ('Winter27', N'MUS 194: Introduction to Music', N'A survey of music for non-majors exploring diverse genres, styles, and historical periods. Students develop active listening skills and learn to articulate their responses to music through guided analysis of representative works.', N'Music', N'Fine Arts', 100, 3, NULL),
  ('Spring27', N'MTH 117: Precalculus', N'A rigorous preparation for calculus covering functions, trigonometry, analytic geometry, and mathematical modeling. Students develop fluency with function transformations, exponential and logarithmic relationships, and trigonometric identities needed for success in the calculus sequence.', N'Mathematics', N'Arts & Sciences', 100, 3, NULL),
  ('Spring27', N'SOC 286: Research Methods in Sociology', N'An introduction to qualitative and quantitative research methods in sociology. Topics include survey design, interviewing, ethnography, content analysis, and statistical techniques. Students design and execute a small-scale research project.', N'Sociology', N'Arts & Sciences', 200, 3, N'SOC 101'),
  ('Summer27', N'EDL 405: Educational Policy and Reform', N'An analysis of education policy at local, state, and federal levels. Students examine policy formation, implementation, and evaluation with attention to equity, accountability, school choice, and the politics of education reform.', N'Educational Leadership', N'Education', 400, 3, N'EDL 301'),
  ('Spring27', N'EXS 512: Graduate Seminar in Applied Exercise Physiology', N'An advanced seminar examining current research in exercise physiology. Topics may include molecular exercise physiology, cardiovascular rehabilitation, altitude and heat adaptation, or exercise immunology.', N'Exercise Science', N'Health Sciences', 500, 3, N'Graduate standing'),
  ('Winter28', N'ENG 181: English Composition II', N'A continuation of composition skills with emphasis on research-based writing. Students learn to locate, evaluate, and synthesize scholarly sources while developing longer analytical arguments. Topics include rhetorical analysis, information literacy, and documentation practices.', N'English', N'Arts & Sciences', 100, 4, N'ENG 101'),
  ('Winter28', N'PBH 337: Health Policy and Management', N'A study of healthcare organization, financing, and policy in the United States and internationally. Topics include health insurance, managed care, healthcare quality, access disparities, and the policy-making process.', N'Public Health', N'Health Sciences', 300, 2, N'PBH 101'),
  ('Spring28', N'CHM 362: Biochemistry', N'An exploration of the chemistry of living systems covering amino acids, protein structure, enzyme kinetics, carbohydrate and lipid metabolism, and nucleic acid chemistry. Integrates organic chemistry and biology to understand molecular mechanisms of life.', N'Chemistry', N'Arts & Sciences', 300, 3, N'CHM 202 and BIO 101'),
  ('Fall26', N'MUS 551: Graduate Seminar in Ethnomusicology', N'An advanced seminar in the study of music in its cultural context. Students engage with ethnomusicological theories and methods, conduct fieldwork, and produce research exploring the relationships between music, identity, and society.', N'Music', N'Fine Arts', 500, 3, N'Graduate standing'),
  ('Winter27', N'BIO 449: Senior Research in Biology', N'An independent research project conducted under faculty mentorship. Students design experiments, collect and analyze data, and present findings in both written and oral formats following scientific conventions. Develops skills essential for graduate study and careers in research.', N'Biology', N'Arts & Sciences', 400, 3, N'Senior standing in BIO and faculty approval'),
  ('Spring28', N'BIO 247: Genetics', N'A comprehensive study of heredity and gene expression from molecular to population levels. Topics include Mendelian genetics, chromosomal inheritance, DNA replication, transcription, translation, gene regulation, and population genetics. Laboratory includes genetic crosses and DNA analysis.', N'Biology', N'Arts & Sciences', 200, 4, N'BIO 101 and BIO 102'),
  ('Spring27', N'MKT 351: International Marketing', N'An examination of marketing strategy in global markets. Topics include market entry strategies, cross-cultural consumer behavior, global branding, pricing across markets, and distribution in emerging economies.', N'Marketing', N'Business', 300, 3, N'MKT 201'),
  ('Fall27', N'MKT 492: Strategic Marketing Management', N'A capstone course integrating marketing concepts in strategic decision-making. Students analyze complex marketing cases, develop comprehensive go-to-market strategies, and present recommendations to industry panels.', N'Marketing', N'Business', 400, 3, N'Senior standing in MKT'),
  ('Winter28', N'CPE 316: Operating System Design', N'An examination of operating system internals with emphasis on implementation. Topics include process scheduling, memory management, file systems, device drivers, and system calls. Students implement kernel modules in a Unix-like environment.', N'Computer Engineering', N'Engineering', 300, 3, N'CPE 211 and CSC 231'),
  ('Spring28', N'SPE 342: Transition Planning and Life Skills', N'A course focused on preparing students with disabilities for post-secondary education, employment, and independent living. Topics include self-determination, vocational assessment, community-based instruction, and interagency collaboration.', N'Special Education', N'Education', 300, 3, N'SPE 201'),
  ('Spring27', N'WLG 261: Language and Culture', N'An interdisciplinary exploration of the relationship between language, thought, and culture. Topics include linguistic relativity, bilingualism, language and identity, translation, and the cultural dimensions of communication. Taught in English; no language prerequisite.', N'World Languages', N'Arts & Sciences', 200, 3, NULL),
  ('Winter27', N'CTV 369: Film Theory and Criticism', N'An examination of major theoretical approaches to cinema including auteur theory, genre theory, feminist film theory, psychoanalytic criticism, and postcolonial perspectives. Students write critical essays analyzing films through theoretical frameworks.', N'Cinema & Television', N'Communications', 300, 3, N'CTV 101'),
  ('Fall26', N'ENV 151: Sustainability and Society', N'An exploration of sustainability concepts and practices across environmental, economic, and social dimensions. Students examine case studies of sustainable communities, renewable energy, circular economies, and corporate sustainability initiatives.', N'Environmental Science', N'Arts & Sciences', 100, 4, NULL),
  ('Fall26', N'ELE 301: Power Systems', N'A study of electric power generation, transmission, and distribution. Topics include three-phase systems, transformers, synchronous generators, power flow analysis, stability, and an introduction to renewable energy integration.', N'Electrical Engineering', N'Engineering', 300, 4, N'ELE 201'),
  ('Spring27', N'CIV 382: Transportation Engineering', N'A study of the planning, design, and operation of transportation systems. Topics include highway geometric design, traffic flow theory, intersection design, pavement materials, and sustainable transportation planning.', N'Civil Engineering', N'Engineering', 300, 4, N'CIV 101 and MTH 242'),
  ('Winter28', N'ENV 454: Senior Capstone in Environmental Science', N'An interdisciplinary capstone project addressing a real environmental challenge. Students work in teams with community partners to research, analyze, and propose solutions for local environmental issues. Culminates in a public presentation and written report.', N'Environmental Science', N'Arts & Sciences', 400, 3, N'Senior standing in ENV'),
  ('Spring28', N'BAN 123: Introduction to Business Analytics', N'An overview of how organizations use data to drive decision-making. Topics include descriptive analytics, data visualization, basic statistical analysis, and an introduction to predictive modeling. Students work with real business datasets using Excel and Tableau.', N'Business Analytics', N'Business', 100, 4, NULL),
  ('Spring28', N'ENG 432: Advanced Creative Writing', N'An advanced workshop for students committed to developing their literary craft. Students produce a portfolio of polished work in their chosen genre, engage with visiting writers, and explore the contemporary publishing landscape.', N'English', N'Arts & Sciences', 400, 3, N'ENG 211 or ENG 212'),
  ('Fall27', N'ENG 309: Literary Theory and Criticism', N'An introduction to major schools of literary criticism including formalism, structuralism, poststructuralism, feminism, postcolonialism, and cultural studies. Students apply theoretical frameworks to literary texts and develop skills in critical argumentation.', N'English', N'Arts & Sciences', 300, 3, N'Two 200-level ENG courses'),
  ('Spring27', N'SCM 515: Graduate Seminar in Corporate Communications', N'An advanced seminar in corporate communication strategy. Topics include executive communication, internal communications, ESG reporting, corporate storytelling, and managing stakeholder relationships in complex organizational environments.', N'Strategic Communications', N'Communications', 500, 3, N'Graduate standing'),
  ('Winter28', N'CHM 276: Organic Chemistry I', N'A systematic study of carbon-based compounds covering nomenclature, stereochemistry, reaction mechanisms, and functional group transformations. Students develop skills in predicting reactivity based on molecular structure and electronic effects.', N'Chemistry', N'Arts & Sciences', 200, 3, N'CHM 102'),
  ('Fall27', N'MGT 215: Organizational Behavior', N'A study of human behavior in organizational settings. Topics include motivation, group dynamics, communication, conflict resolution, organizational culture, power and politics, and leadership theories. Students apply behavioral concepts through case analyses and simulations.', N'Management', N'Business', 200, 3, N'MGT 101'),
  ('Winter27', N'PBH 278: Biostatistics', N'An introduction to statistical methods for public health research. Topics include descriptive statistics, probability, sampling distributions, hypothesis testing, regression, and survival analysis. Students use SAS or R to analyze health datasets.', N'Public Health', N'Health Sciences', 200, 2, N'MTH 110'),
  ('Winter28', N'ACC 526: Graduate Seminar in Data Analytics for Accountants', N'An advanced course in applying data analytics to accounting and auditing problems. Students use Python, SQL, and visualization tools to detect anomalies, automate audit procedures, and extract insights from large financial datasets.', N'Accounting', N'Business', 500, 3, N'ACC 303 and graduate standing'),
  ('Winter27', N'ACC 254: Intermediate Accounting II', N'Continuation of Intermediate Accounting I covering accounting for liabilities, stockholders'' equity, investments, leases, pensions, income taxes, and cash flow statements. Emphasizes analysis of complex transactions and financial statement presentation.', N'Accounting', N'Business', 200, 4, N'ACC 211'),
  ('Fall27', N'POL 346: Constitutional Law', N'An in-depth study of U.S. constitutional interpretation focusing on landmark Supreme Court decisions. Topics include judicial review, separation of powers, federalism, equal protection, due process, and First Amendment freedoms.', N'Political Science', N'Arts & Sciences', 300, 3, N'POL 101'),
  ('Spring27', N'PHY 478: Electrodynamics', N'An advanced study of electromagnetic theory based on Maxwell''s equations. Topics include boundary value problems, electromagnetic waves, radiation, and special relativity. Students develop skills in vector calculus and mathematical physics.', N'Physics', N'Arts & Sciences', 400, 3, N'PHY 312 and MTH 302'),
  ('Spring27', N'JOU 482: Senior Capstone in Journalism', N'A culminating project in which students produce a substantial piece of original journalism — investigative report, documentary, multimedia project, or podcast series. Students pitch, research, produce, and present their work.', N'Journalism', N'Communications', 400, 3, N'Senior standing in JOU'),
  ('Fall26', N'ENG 243: World Literature', N'A comparative study of literary traditions from Africa, Asia, Latin America, the Middle East, and Europe. Students read works in translation and explore themes of identity, migration, colonialism, and cultural exchange across global literary traditions.', N'English', N'Arts & Sciences', 200, 3, N'ENG 103'),
  ('Winter27', N'MEC 512: Graduate Seminar in Advanced Manufacturing', N'An advanced seminar covering emerging manufacturing technologies including additive manufacturing, smart factories, digital twins, and sustainable manufacturing practices. Students analyze case studies and conduct research projects.', N'Mechanical Engineering', N'Engineering', 500, 3, N'Graduate standing'),
  ('Fall27', N'CSC 397: Computer Networks', N'A study of network architectures, protocols, and communication fundamentals. Topics include the OSI model, TCP/IP, routing algorithms, network security basics, and socket programming. Students build simple client-server applications and analyze network traffic.', N'Computer Science', N'Arts & Sciences', 300, 3, N'CSC 231'),
  ('Spring28', N'CPE 485: Senior Design in Computer Engineering', N'A capstone project integrating hardware and software design. Student teams develop a complete embedded computing system from specification through implementation and testing.', N'Computer Engineering', N'Engineering', 400, 3, N'Senior standing in CPE'),
  ('Summer27', N'ELE 226: Digital Logic Design', N'An introduction to digital systems including Boolean algebra, combinational and sequential logic, flip-flops, counters, state machines, and memory. Students design and implement digital circuits using FPGA development boards.', N'Electrical Engineering', N'Engineering', 200, 4, N'ELE 101'),
  ('Spring28', N'MKT 595: Graduate Seminar in Customer Analytics', N'An advanced seminar in applying machine learning and statistical methods to customer data. Topics include customer lifetime value modeling, churn prediction, recommendation systems, and natural language processing for sentiment analysis.', N'Marketing', N'Business', 500, 3, N'Graduate standing'),
  ('Fall27', N'PHY 466: Electrodynamics', N'An advanced study of electromagnetic theory based on Maxwell''s equations. Topics include boundary value problems, electromagnetic waves, radiation, and special relativity. Students develop skills in vector calculus and mathematical physics.', N'Physics', N'Arts & Sciences', 400, 3, N'PHY 312 and MTH 302'),
  ('Winter27', N'SPE 393: Transition Planning and Life Skills', N'A course focused on preparing students with disabilities for post-secondary education, employment, and independent living. Topics include self-determination, vocational assessment, community-based instruction, and interagency collaboration.', N'Special Education', N'Education', 300, 1, N'SPE 201'),
  ('Fall26', N'EDL 493: Educational Policy and Reform', N'An analysis of education policy at local, state, and federal levels. Students examine policy formation, implementation, and evaluation with attention to equity, accountability, school choice, and the politics of education reform.', N'Educational Leadership', N'Education', 400, 3, N'EDL 301');
INSERT INTO dbo.CourseCatalog (TermID, CourseTitle, CourseDescription, Department, College, CourseLevel, Credits, Prerequisites)
VALUES
  ('Spring28', N'ARH 304: Contemporary Art Since 1960', N'An examination of art from the 1960s to the present including Pop Art, Minimalism, Conceptual Art, Installation, Performance, and Digital Art. Students analyze how contemporary artists engage with issues of identity, globalization, and technology.', N'Art History', N'Fine Arts', 300, 3, N'ARH 211'),
  ('Winter27', N'EED 331: Teaching Mathematics in Elementary Schools', N'A methods course in teaching mathematics to children in grades K-6. Students explore mathematical content knowledge, research-based instructional strategies, manipulative use, problem-solving approaches, and assessment techniques for diverse learners.', N'Elementary Education', N'Education', 300, 3, N'EED 202 and MTH 131'),
  ('Spring28', N'MUS 157: Introduction to Music', N'A survey of music for non-majors exploring diverse genres, styles, and historical periods. Students develop active listening skills and learn to articulate their responses to music through guided analysis of representative works.', N'Music', N'Fine Arts', 100, 3, NULL),
  ('Spring28', N'CTV 206: Documentary Filmmaking', N'A practical course in documentary production. Students study documentary traditions, develop stories, conduct interviews, and produce short documentary films. Covers ethical considerations in representing real people and events on screen.', N'Cinema & Television', N'Communications', 200, 4, N'CTV 102'),
  ('Summer28', N'CHM 245: Analytical Chemistry', N'A study of quantitative and qualitative analytical methods including gravimetry, titrimetry, spectrophotometry, chromatography, and electroanalytical techniques. Emphasizes method validation, error analysis, and quality assurance in chemical measurements.', N'Chemistry', N'Arts & Sciences', 200, 4, N'CHM 102'),
  ('Spring27', N'CIV 566: Graduate Seminar in Sustainable Infrastructure', N'An advanced seminar on designing infrastructure for resilience and sustainability. Topics include green building, climate-adaptive design, lifecycle assessment, smart cities, and infrastructure equity.', N'Civil Engineering', N'Engineering', 500, 3, N'Graduate standing'),
  ('Spring28', N'CPE 319: VLSI Design', N'An introduction to the design of very large scale integrated circuits. Topics include CMOS logic design, layout, verification, timing analysis, and low-power techniques. Students design and simulate circuits using industry CAD tools.', N'Computer Engineering', N'Engineering', 300, 4, N'ELE 202'),
  ('Summer28', N'PHL 539: Graduate Seminar in Applied Ethics', N'An advanced seminar examining contemporary ethical issues through philosophical analysis. Topics rotate and may include bioethics, technology ethics, business ethics, or environmental justice. Students write a publishable-quality research paper.', N'Philosophy', N'Arts & Sciences', 500, 4, N'Graduate standing'),
  ('Spring28', N'ECN 378: Public Economics', N'A study of the economic role of government. Topics include public goods, externalities, tax policy, income redistribution, social insurance, healthcare economics, and education finance. Students evaluate policy proposals using cost-benefit analysis.', N'Economics', N'Business', 300, 3, N'ECN 201'),
  ('Spring28', N'NUR 373: Medical-Surgical Nursing', N'Clinical nursing practice focused on adults with acute and chronic health conditions. Students develop skills in assessment, care planning, medication administration, and patient education across hospital and outpatient settings.', N'Nursing', N'Health Sciences', 300, 1, N'NUR 201, NUR 202, NUR 203'),
  ('Fall27', N'POL 544: Graduate Seminar in Political Theory', N'An advanced seminar examining classic and contemporary political thought. Students engage with texts from ancient, modern, and postmodern traditions while exploring questions of justice, power, freedom, and democracy.', N'Political Science', N'Arts & Sciences', 500, 3, N'Graduate standing'),
  ('Spring27', N'PSY 214: Biological Psychology', N'A study of the biological bases of behavior including neuroanatomy, neurotransmitter systems, sensory processing, motivation, emotion, learning, and psychopharmacology. Bridges neuroscience and psychological perspectives on mind-brain relationships.', N'Psychology', N'Arts & Sciences', 200, 3, N'PSY 101'),
  ('Winter28', N'BAN 278: Data Management for Business', N'A practical course in managing and querying business data. Students learn relational database concepts, SQL query writing, data cleaning and transformation techniques, and basic data warehousing principles. Applications focus on marketing, finance, and operations datasets.', N'Business Analytics', N'Business', 200, 3, N'BAN 101'),
  ('Fall26', N'EED 161: Introduction to Education', N'An exploration of the foundations of American education including its history, philosophy, and social contexts. Students examine current issues in education reform, observe in local classrooms, and reflect on their motivations for entering the teaching profession.', N'Elementary Education', N'Education', 100, 3, NULL),
  ('Fall27', N'PHL 323: Philosophy of Science', N'An analysis of the foundations, methods, and implications of scientific inquiry. Topics include the problem of induction, theory change, scientific explanation, realism vs. anti-realism, and the relationship between science and values.', N'Philosophy', N'Arts & Sciences', 300, 2, N'PHL 101 and one science course'),
  ('Spring28', N'PBH 421: Senior Capstone in Public Health', N'A culminating experience integrating public health knowledge and skills through a practicum with a community health organization. Students design, implement, and evaluate a health program or research project under professional mentorship.', N'Public Health', N'Health Sciences', 400, 3, N'Senior standing in PBH'),
  ('Winter27', N'ENG 161: English Composition II', N'A continuation of composition skills with emphasis on research-based writing. Students learn to locate, evaluate, and synthesize scholarly sources while developing longer analytical arguments. Topics include rhetorical analysis, information literacy, and documentation practices.', N'English', N'Arts & Sciences', 100, 3, N'ENG 101'),
  ('Spring28', N'ART 314: Digital Art and New Media', N'A course exploring digital tools and technologies for artistic creation. Topics include digital imaging, video art, interactive installations, generative art, and the cultural implications of technology-based art practices.', N'Studio Art', N'Fine Arts', 300, 3, N'ART 102'),
  ('Spring28', N'JOU 524: Graduate Seminar in Media Ethics and Law', N'An advanced seminar examining legal and ethical frameworks governing journalism and media. Topics include press freedom, defamation, privacy, shield laws, access to information, and ethical dilemmas in the digital age.', N'Journalism', N'Communications', 500, 4, N'Graduate standing'),
  ('Spring28', N'ECN 529: Graduate Seminar in Applied Econometrics', N'An advanced course in econometric methods for causal inference. Topics include panel data models, differences-in-differences, regression discontinuity, synthetic controls, and machine learning methods for prediction in economic contexts.', N'Economics', N'Business', 500, 3, N'Graduate standing'),
  ('Winter28', N'SOC 372: Sociology of Education', N'An examination of educational institutions through sociological lenses. Topics include educational inequality, school segregation, cultural capital, hidden curriculum, standardized testing, and the role of education in social mobility and social reproduction.', N'Sociology', N'Arts & Sciences', 300, 3, N'SOC 201'),
  ('Spring27', N'POL 511: Graduate Seminar in Political Theory', N'An advanced seminar examining classic and contemporary political thought. Students engage with texts from ancient, modern, and postmodern traditions while exploring questions of justice, power, freedom, and democracy.', N'Political Science', N'Arts & Sciences', 500, 4, N'Graduate standing'),
  ('Spring28', N'HIS 363: Public History', N'An exploration of how history is presented and interpreted outside the academy. Topics include museums, historic preservation, documentary film, digital archives, oral history, and community-based historical projects. Students complete a public history project.', N'History', N'Arts & Sciences', 300, 3, N'HIS 301'),
  ('Summer27', N'NUR 391: Mental Health Nursing', N'A clinical course in nursing care for individuals experiencing mental health challenges. Topics include therapeutic communication, psychiatric assessment, psychopharmacology, crisis intervention, and community-based mental health services.', N'Nursing', N'Health Sciences', 300, 3, N'NUR 201'),
  ('Winter28', N'MEC 318: Control Systems', N'An introduction to feedback control theory for mechanical systems. Topics include system modeling, transfer functions, stability analysis, root locus, frequency response, and PID controller design. Students design and simulate controllers using MATLAB.', N'Mechanical Engineering', N'Engineering', 300, 4, N'MEC 201 and MTH 302'),
  ('Fall27', N'HLA 307: Healthcare Quality and Patient Safety', N'A study of methods for improving healthcare quality and ensuring patient safety. Topics include quality measurement, performance improvement, root cause analysis, high reliability organizations, and evidence-based management practices.', N'Health Administration', N'Health Sciences', 300, 3, N'HLA 101'),
  ('Spring27', N'MEC 209: Thermodynamics', N'A study of energy, heat, work, and their transformation in engineering systems. Topics include the first and second laws, entropy, properties of pure substances, power and refrigeration cycles, and energy efficiency analysis.', N'Mechanical Engineering', N'Engineering', 200, 3, N'PHY 211 and MTH 242'),
  ('Spring28', N'BAN 577: Graduate Seminar in Big Data Analytics', N'An advanced seminar in large-scale data processing and analytics. Topics include distributed computing frameworks, real-time stream processing, graph analytics, and building scalable machine learning pipelines. Students work with Spark, Kafka, and cloud data platforms.', N'Business Analytics', N'Business', 500, 3, N'Graduate standing'),
  ('Spring27', N'FIN 548: Graduate Seminar in Quantitative Finance', N'An advanced course in quantitative methods for financial analysis. Topics include stochastic calculus, options pricing models, Monte Carlo simulation, and machine learning applications in finance. Students implement models in Python.', N'Finance', N'Business', 500, 3, N'Graduate standing and MTH 341'),
  ('Fall26', N'PHL 199: Ethics', N'An introduction to moral philosophy examining major ethical theories including utilitarianism, deontology, virtue ethics, and care ethics. Students apply these frameworks to contemporary moral issues including bioethics, environmental ethics, and social justice.', N'Philosophy', N'Arts & Sciences', 100, 4, NULL),
  ('Fall26', N'ECN 409: Senior Seminar in Economics', N'A capstone seminar in which students conduct original empirical research on an economic question. Students develop a research proposal, collect and analyze data, and present findings in both written and oral formats.', N'Economics', N'Business', 400, 3, N'ECN 221 and senior standing'),
  ('Fall26', N'PHY 136: General Physics II', N'Continuation of General Physics I covering electricity, magnetism, optics, and modern physics. Topics include electric fields, circuits, electromagnetic waves, geometric optics, and an introduction to quantum phenomena.', N'Physics', N'Arts & Sciences', 100, 4, N'PHY 101'),
  ('Fall26', N'ECN 495: Senior Seminar in Economics', N'A capstone seminar in which students conduct original empirical research on an economic question. Students develop a research proposal, collect and analyze data, and present findings in both written and oral formats.', N'Economics', N'Business', 400, 3, N'ECN 221 and senior standing'),
  ('Spring27', N'SOC 255: Sociology of Health and Illness', N'An examination of social factors influencing health, illness, and healthcare delivery. Topics include social determinants of health, health disparities, medicalization, patient-provider relationships, and healthcare systems in comparative perspective.', N'Sociology', N'Arts & Sciences', 200, 3, N'SOC 101'),
  ('Winter27', N'MUS 389: Music Technology and Production', N'An introduction to music technology including digital audio workstations, MIDI sequencing, audio recording and mixing, synthesis, and sound design. Students produce original recordings and learn the technical skills used in modern music production.', N'Music', N'Fine Arts', 300, 3, N'MUS 101'),
  ('Fall27', N'EED 275: Curriculum and Instructional Design', N'An introduction to designing effective instruction for diverse learners. Students learn to develop lesson plans, align objectives with assessments, differentiate instruction, and integrate technology meaningfully into teaching practice.', N'Elementary Education', N'Education', 200, 3, N'EED 101'),
  ('Winter28', N'ENV 563: Graduate Seminar in Environmental Management', N'An advanced seminar on managing complex environmental challenges at organizational and community scales. Topics include environmental impact assessment, stakeholder engagement, adaptive management, and sustainability reporting frameworks.', N'Environmental Science', N'Arts & Sciences', 500, 3, N'Graduate standing'),
  ('Winter27', N'HLA 322: Healthcare Quality and Patient Safety', N'A study of methods for improving healthcare quality and ensuring patient safety. Topics include quality measurement, performance improvement, root cause analysis, high reliability organizations, and evidence-based management practices.', N'Health Administration', N'Health Sciences', 300, 3, N'HLA 101'),
  ('Spring28', N'POL 181: Introduction to International Relations', N'A survey of theories and issues in international relations including realism, liberalism, constructivism, security studies, international organizations, globalization, human rights, and environmental politics. Students analyze contemporary global challenges.', N'Political Science', N'Arts & Sciences', 100, 3, NULL),
  ('Fall27', N'PSY 413: Advanced Behavioral Neuroscience', N'An advanced study of brain mechanisms underlying complex behaviors including emotion, motivation, learning, decision-making, and consciousness. Integrates findings from neuroimaging, electrophysiology, and clinical case studies.', N'Psychology', N'Arts & Sciences', 400, 3, N'PSY 204 or BIO 321'),
  ('Spring27', N'CTV 315: Directing for Screen', N'An advanced production course focusing on the art and craft of directing. Students work with actors, plan shot compositions, manage production teams, and direct short narrative films. Covers both technical skills and the director''s creative vision.', N'Cinema & Television', N'Communications', 300, 4, N'CTV 102 and CTV 211'),
  ('Fall27', N'POL 367: Constitutional Law', N'An in-depth study of U.S. constitutional interpretation focusing on landmark Supreme Court decisions. Topics include judicial review, separation of powers, federalism, equal protection, due process, and First Amendment freedoms.', N'Political Science', N'Arts & Sciences', 300, 3, N'POL 101'),
  ('Winter28', N'NUR 591: Graduate Seminar in Advanced Practice Nursing', N'An advanced seminar exploring the expanding roles of nurse practitioners, clinical nurse specialists, and nurse educators. Topics include advanced health assessment, clinical decision-making, prescriptive authority, and healthcare system leadership.', N'Nursing', N'Health Sciences', 500, 3, N'Graduate standing in nursing'),
  ('Spring27', N'ENG 239: World Literature', N'A comparative study of literary traditions from Africa, Asia, Latin America, the Middle East, and Europe. Students read works in translation and explore themes of identity, migration, colonialism, and cultural exchange across global literary traditions.', N'English', N'Arts & Sciences', 200, 3, N'ENG 103'),
  ('Spring28', N'WLG 389: Hispanic Literature and Film', N'A study of major works of literature and film from Spain and Latin America in their cultural and historical contexts. Students develop advanced reading and analytical skills while exploring themes of identity, justice, memory, and artistic innovation.', N'World Languages', N'Arts & Sciences', 300, 3, N'WLG 202'),
  ('Winter27', N'THR 306: Playwriting', N'A workshop course in dramatic writing. Students study dramatic structure, create original short and full-length plays, participate in peer critique, and hear their work read by student actors. Explores diverse storytelling traditions and voices.', N'Theatre', N'Fine Arts', 300, 3, N'THR 101 or ENG 211'),
  ('Summer28', N'PHL 215: Environmental Ethics', N'A philosophical examination of human relationships with the natural world. Topics include intrinsic value of nature, animal rights, environmental justice, climate change ethics, and sustainability. Students evaluate competing ethical frameworks for environmental decision-making.', N'Philosophy', N'Arts & Sciences', 200, 3, N'PHL 101 or PHL 102'),
  ('Spring27', N'ECN 294: Intermediate Macroeconomics', N'An advanced treatment of macroeconomic theory and policy. Topics include national income accounting, IS-LM model, aggregate supply and demand, economic growth models, monetary and fiscal policy analysis, and open economy macroeconomics.', N'Economics', N'Business', 200, 3, N'ECN 102 and MTH 131'),
  ('Winter28', N'MEC 112: Introduction to Engineering', N'A broad introduction to engineering disciplines and the engineering design process. Students work in teams to solve open-ended design challenges using computer-aided design tools, prototyping, and iterative testing. Develops creative problem-solving and communication skills.', N'Mechanical Engineering', N'Engineering', 100, 3, NULL),
  ('Winter28', N'ELE 386: Electronics', N'A study of semiconductor devices and electronic circuit design. Topics include diodes, transistors (BJT and MOSFET), amplifier design, frequency response, feedback, and operational amplifier circuits.', N'Electrical Engineering', N'Engineering', 300, 3, N'ELE 201');
